// Baggage fee calculator: per-bag base fees plus weight and size penalties.

const FIRST_BAG_FEE = 25;
const SECOND_BAG_FEE = 35;
const EXTRA_BAG_FEE = 100;
const OVERWEIGHT_FEE = 50;
const OVERSIZE_FEE = 75;

const WEIGHT_LIMIT = 50; // pounds
const SIZE_LIMIT = 62; // linear inches

// The base fee depends only on the bag's position in the traveler's queue.
function baseFee(index, isElite) {
  if (index === 0) {
    // Elite travellers carry their first bag for free.
    return isElite ? 0 : FIRST_BAG_FEE;
  }
  if (index === 1) {
    return SECOND_BAG_FEE;
  }
  // Third bag and beyond is a flat charge each.
  return EXTRA_BAG_FEE;
}

// Penalties stack: a bag can be both too heavy and too large.
function penalties(bag) {
  let extra = 0;
  if (bag.weight > WEIGHT_LIMIT) {
    extra += OVERWEIGHT_FEE;
  }
  if (bag.size > SIZE_LIMIT) {
    extra += OVERSIZE_FEE;
  }
  return extra;
}

function feeForPassenger(passenger) {
  // A traveller with no bags listed simply owes nothing.
  const bags = passenger.bags || [];
  return bags.reduce(
    (total, bag, index) => total + baseFee(index, Boolean(passenger.elite)) + penalties(bag),
    0
  );
}

function baggage(passengers) {
  return passengers.map(feeForPassenger);
}

// Reporting helper used by the driver to print a readable invoice line.
function formatLine(passenger, fee) {
  const count = (passenger.bags || []).length;
  const tier = passenger.elite ? 'elite' : 'standard';
  return `${passenger.name} (${tier}, ${count} bag(s)): $${fee}`;
}

const travellers = [
  { name: 'Ada', elite: true, bags: [{ weight: 40, size: 55 }] },
  { name: 'Brahm', elite: false, bags: [{ weight: 52, size: 60 }, { weight: 30, size: 45 }] },
  // Three bags, the last one both overweight and oversize.
  { name: 'Chen', elite: true, bags: [
    { weight: 20, size: 40 },
    { weight: 48, size: 61 },
    { weight: 70, size: 70 }
  ] },
  { name: 'Dara', elite: false, bags: [] }
];

const fees = baggage(travellers);
travellers.forEach((passenger, i) => console.log(formatLine(passenger, fees[i])));

// Grand total across the manifest.
console.log(`Total collected: $${fees.reduce((sum, fee) => sum + fee, 0)}`);

module.exports = { baggage, feeForPassenger, formatLine };

