// Frequent flyer mileage calculator.
//
// Each flight segment is an object of the form
//   { from, to, distance, fareClass, international, elite }
// and earns miles according to distance, fare class and bonus flags.

const MINIMUM_BASE_MILES = 500;
const INTERNATIONAL_BONUS = 500;
const ELITE_FACTOR = 1.5;

// Fare class keys are normalised to lower case with spaces collapsed to
// underscores, so "Basic Economy" and "basic_economy" both resolve.
const CLASS_FACTORS = {
  basic_economy: 0.5,
  economy: 1.0,
  business: 1.5,
  first: 2.0,
};

function normaliseFareClass(fareClass) {
  return String(fareClass).trim().toLowerCase().replace(/[\s-]+/g, '_');
}

function classFactor(fareClass) {
  const key = normaliseFareClass(fareClass);
  // An unknown fare class is a data error rather than a plain economy ticket.
  if (!Object.prototype.hasOwnProperty.call(CLASS_FACTORS, key)) {
    throw new Error(`Unknown fare class: ${fareClass}`);
  }
  return CLASS_FACTORS[key];
}

function segmentMiles(flight) {
  const distance = Number(flight.distance);
  if (!Number.isFinite(distance) || distance < 0) {
    throw new Error(`Invalid distance for segment ${flight.from}-${flight.to}`);
  }
  // Short hops are still credited with the 500 mile floor.
  const base = Math.max(distance, MINIMUM_BASE_MILES);
  let earned = base * classFactor(flight.fareClass);
  if (flight.international) {
    earned += INTERNATIONAL_BONUS;
  }
  // The elite multiplier applies last, to base plus every bonus.
  if (flight.elite) {
    earned *= ELITE_FACTOR;
  }
  return earned;
}

function mileage(flights) {
  if (!Array.isArray(flights)) {
    throw new TypeError('mileage() expects an array of flight segments');
  }
  const total = flights.reduce((sum, flight) => sum + segmentMiles(flight), 0);
  // Miles are always credited as whole numbers.
  return Math.round(total);
}

function report(flights) {
  const lines = flights.map((flight) => {
    const route = `${flight.from}-${flight.to}`;
    // Pad the route so the per-segment columns line up in the printout.
    return `${route.padEnd(8)} ${String(Math.round(segmentMiles(flight))).padStart(6)}`;
  });
  lines.push(`${'TOTAL'.padEnd(8)} ${String(mileage(flights)).padStart(6)}`);
  return lines.join('\n');
}

const itinerary = [
  { from: 'SFO', to: 'LAX', distance: 337, fareClass: 'basic economy', international: false, elite: false },
  { from: 'LAX', to: 'JFK', distance: 2475, fareClass: 'business', international: false, elite: true },
  { from: 'JFK', to: 'LHR', distance: 3451, fareClass: 'first', international: true, elite: true },
  { from: 'LHR', to: 'CDG', distance: 214, fareClass: 'economy', international: true, elite: false },
];

