const INVALID = "invalid";

// A part is only well formed if it is all digits; "1e2" or " 12" must be rejected
function isDigits(part) {
  return part.length > 0 && /^[0-9]+$/.test(part);
}

function parseOctet(part) {
  if (!isDigits(part)) {
    return null;
  }
  // leading zeros are forbidden, so "0" passes but "00" and "012" do not
  if (part.length > 1 && part[0] === "0") {
    return null;
  }
  const value = Number(part);
  return value <= 255 ? value : null;
}

// Returns the four octets of a dotted address, or null when the string is malformed
function parseAddress(address) {
  if (typeof address !== "string") {
    return null;
  }
  const parts = address.split(".");
  // exactly four parts, no more and no less
  if (parts.length !== 4) {
    return null;
  }
  const octets = [];
  for (const part of parts) {
    const octet = parseOctet(part);
    if (octet === null) {
      return null;
    }
    octets.push(octet);
  }
  return octets;
}

function classify(firstOctet) {
  // 127.x.x.x is checked before class a because it is a subset of that range
  if (firstOctet === 127) {
    return "loopback";
  }
  if (firstOctet < 128) {
    return "class a";
  }
  if (firstOctet < 192) {
    return "class b";
  }
  if (firstOctet < 224) {
    return "class c";
  }
  // numerically valid but outside the classified ranges (multicast and above)
  return "reserved";
}

function network(addresses) {
  return addresses.map((address) => {
    const octets = parseAddress(address);
    return octets === null ? INVALID : classify(octets[0]);
  });
}

function report(addresses) {
  const results = network(addresses);
  // pair each input with its verdict so the output is readable
  return results.map((result, i) => `${addresses[i]} -> ${result}`).join("\n");
}

const samples = [
  "127.0.0.1",
  "10.0.0.255",
  "172.16.0.1",
  "192.168.1.1",
  "239.255.255.250",
  "256.1.1.1",
  "192.168.01.1",
  "1.2.3",
  "1.2.3.4.5",
  "a.b.c.d",
];

console.log(report(samples));

module.exports = { network, parseAddress, classify, report };

