const SCALE_FACTOR = 2.5;
const SPICE_CAP = 2;

// Spices lose their balance when scaled linearly, so they are tracked by name
const SPICES = new Set([
  'salt', 'pepper', 'black pepper', 'cinnamon', 'nutmeg', 'cumin',
  'paprika', 'turmeric', 'cayenne', 'oregano', 'chili powder', 'cloves'
]);

// Unit spellings are normalised so that "Tbsp." and "tablespoons" behave alike
const UNIT_ALIASES = {
  tbsp: 'tablespoon', tbsps: 'tablespoon', tablespoon: 'tablespoon', tablespoons: 'tablespoon',
  tsp: 'teaspoon', tsps: 'teaspoon', teaspoon: 'teaspoon', teaspoons: 'teaspoon',
  cup: 'cup', cups: 'cup', g: 'g', gram: 'g', grams: 'g', kg: 'kg', kilogram: 'kg'
};

function normaliseUnit(unit) {
  const key = String(unit).toLowerCase().replace(/\.$/, '');
  // Unknown units (pinches, cloves, whole eggs) are kept verbatim
  return UNIT_ALIASES[key] || key;
}

function isSpice(name) {
  return SPICES.has(String(name).toLowerCase());
}

function scaleAmount(amount, name) {
  const factor = isSpice(name) ? SPICE_CAP : SCALE_FACTOR;
  return amount * factor;
}

function convertUnit(amount, unit) {
  let value = amount;
  let current = normaliseUnit(unit);
  // Teaspoons promote to tablespoons first, and may then promote again to cups
  if (current === 'teaspoon' && value > 3) {
    value /= 3;
    current = 'tablespoon';
  }
  if (current === 'tablespoon' && value > 16) {
    value /= 16;
    current = 'cup';
  }
  if (current === 'g' && value > 1000) {
    value /= 1000;
    current = 'kg';
  }
  return { amount: value, unit: current };
}

function formatAmount(amount) {
  // Two decimals is enough precision for a kitchen scale or measuring spoon
  const rounded = Math.round(amount * 100) / 100;
  return String(rounded);
}

function pluralise(unit, amount) {
  // Only the spelled-out volume units take an "s"; abbreviations like kg never do
  const countable = ['cup', 'tablespoon', 'teaspoon'];
  return countable.includes(unit) && amount !== 1 ? `${unit}s` : unit;
}

function recipe(ingredients) {
  return ingredients.map(({ name, amount, unit }) => {
    const scaled = scaleAmount(amount, name);
    const converted = convertUnit(scaled, unit);
    const label = pluralise(converted.unit, converted.amount);
    return `${formatAmount(converted.amount)} ${label} ${name}`;
  });
}

const fourServings = [
  { name: 'flour', amount: 8, unit: 'tablespoons' },
  { name: 'cinnamon', amount: 2, unit: 'teaspoons' },
  { name: 'beef', amount: 500, unit: 'g' },
  { name: 'milk', amount: 1, unit: 'cup' },
  { name: 'eggs', amount: 2, unit: 'whole' }
];

// Driver: print the ten-guest version of the four-serving recipe
recipe(fourServings).forEach((phrase) => console.log(phrase));

module.exports = { recipe, scaleAmount, convertUnit, isSpice };

