// Server log parser: extracts timestamp / severity / message and tallies severities.

// A valid line starts with "[", contains a closing "]", then a severity word.
const LINE_PATTERN = /^\[([^\]]+)\]\s+(\S+)\s*(.*)$/;

function parseLine(line) {
  const match = LINE_PATTERN.exec(line.trim());
  // Malformed lines (no surrounding brackets, or nothing after them) yield null.
  if (!match) return null;
  return {
    timestamp: match[1].trim(),
    level: match[2].toUpperCase(),
    message: match[3].trim(),
  };
}

// "timeout" must be matched regardless of capitalisation, as a standalone word.
const TIMEOUT_PATTERN = /\btimeout\b/i;

function isTimeoutMessage(message) {
  return TIMEOUT_PATTERN.test(message);
}

function logs(lines) {
  let warnings = 0;
  let errors = 0;
  let timeoutErrors = 0;

  for (const line of lines) {
    const entry = parseLine(line);
    // Skip malformed input instead of aborting the whole scan.
    if (entry === null) continue;

    if (entry.level === 'WARNING') {
      warnings += 1;
    } else if (entry.level === 'ERROR') {
      errors += 1;
      // Timeout errors are counted in addition to the plain error total.
      if (isTimeoutMessage(entry.message)) timeoutErrors += 1;
    }
  }

  return [warnings, errors, timeoutErrors];
}

// Human-readable summary used by the driver below.
function formatSummary([warnings, errors, timeoutErrors]) {
  const healthy = errors === 0 && warnings === 0;
  const lines = [
    `warnings:       ${warnings}`,
    `errors:         ${errors}`,
    `timeout errors: ${timeoutErrors}`,
  ];
  // A clean log deserves an explicit note, otherwise the ratio is more useful.
  if (healthy) {
    lines.push('status:         clean');
  } else {
    const ratio = errors === 0 ? 0 : (timeoutErrors / errors) * 100;
    lines.push(`status:         ${ratio.toFixed(1)}% of errors were timeouts`);
  }
  return lines.join('\n');
}

const sampleLog = [
  '[2024-05-01 09:14:02] INFO Service started on port 8080',
  '[2024-05-01 09:14:47] WARNING Disk usage at 81%',
  'connection reset by peer',
  '[2024-05-01 09:15:10] ERROR Upstream TIMEOUT while fetching /users',
  '[2024-05-01 09:15:11] error request timed out after 30s',
  '[2024-05-01 09:16:00] WARNING Retrying upstream call',
  '[2024-05-01 09:16:30 ERROR Missing closing bracket',
  '[2024-05-01 09:17:05] ERROR Timeout contacting database replica',
];

const totals = logs(sampleLog);
console.log(formatSummary(totals));
// Downstream monitoring only cares about the raw triple.
console.log(totals.join(','));

module.exports = { logs, parseLine, isTimeoutMessage, formatSummary };

