const SCORE_NAMES = ['love', 'fifteen', 'thirty', 'forty'];
const PLAYER_ONE = 'player one';
const PLAYER_TWO = 'player two';

// Accepted spellings for each player, so the caller can use "one", "p1", "player1", ...
const POINT_ALIASES = {
  [PLAYER_ONE]: ['one', '1', 'p1', 'player1', 'player one', 'player 1'],
  [PLAYER_TWO]: ['two', '2', 'p2', 'player2', 'player two', 'player 2'],
};

function normalizePoint(point) {
  if (typeof point !== 'string') {
    throw new TypeError(`point winner must be a string, got ${typeof point}`);
  }
  const key = point.trim().toLowerCase();
  // Collapse repeated inner whitespace so "player  1" still resolves
  const compact = key.replace(/\s+/g, ' ');
  if (POINT_ALIASES[PLAYER_ONE].includes(compact)) return PLAYER_ONE;
  if (POINT_ALIASES[PLAYER_TWO].includes(compact)) return PLAYER_TWO;
  throw new Error(`unrecognised point winner: "${point}"`);
}

function describeScore(one, two) {
  // Once both players have at least forty the game is decided by the gap, not by names
  if (one >= 3 && two >= 3) {
    if (one === two) return 'deuce';
    return `advantage ${one > two ? PLAYER_ONE : PLAYER_TWO}`;
  }
  if (one === two) return `${SCORE_NAMES[one]}-all`;
  return `${SCORE_NAMES[one]}-${SCORE_NAMES[two]}`;
}

function gameWinner(one, two) {
  // A game needs four points and a two point cushion
  if (one >= 4 && one - two >= 2) return PLAYER_ONE;
  if (two >= 4 && two - one >= 2) return PLAYER_TWO;
  return null;
}

function tennis(points) {
  if (!Array.isArray(points)) {
    throw new TypeError('points must be an array of point winner strings');
  }
  let one = 0;
  let two = 0;
  for (const point of points) {
    const winner = normalizePoint(point);
    if (winner === PLAYER_ONE) one += 1;
    else two += 1;
    const decided = gameWinner(one, two);
    // Extra points after the game is over are ignored
    if (decided) return decided;
  }
  return describeScore(one, two);
}

function report(label, points) {
  // The result is either a winner name or the score the game stalled at
  console.log(`${label}: ${tennis(points)}`);
}

function main() {
  report('straight sets', ['one', 'one', 'one', 'one']);
  report('short rally', ['p1', 'p2', 'p1']);
  report('into deuce', ['one', 'one', 'one', 'two', 'two', 'two']);
  // Advantage lost, so the score falls back to deuce before running out
  report('advantage then back', ['1', '1', '1', '2', '2', '2', '1', '2']);
  report('won from deuce', ['two', 'two', 'two', 'one', 'one', 'one', 'two', 'two']);
  try {
    report('bad input', ['one', 'referee']);
  } catch (err) {
    // Unknown names are a caller error, not a legal point
    console.log(`bad input rejected: ${err.message}`);
  }
}

main();

module.exports = { tennis, normalizePoint, describeScore, gameWinner };

