/* Scoring model for a single over of cricket. */

/* Runs credited for each recognised delivery type. */
const RUNS = {
  single: 1,
  double: 2,
  boundary: 4,
  sixer: 6,
  wide: 1,
  noball: 1,
  wicket: 0,
};

/* Wides and noballs are re-bowled, so they never count towards the over. */
const EXTRAS = new Set(['wide', 'noball']);

const BALLS_PER_OVER = 6;

function runsFor(delivery) {
  const runs = RUNS[delivery];
  if (runs === undefined) {
    /* An unknown word cannot be scored, so fail loudly rather than silently. */
    throw new Error(`unknown delivery type: ${delivery}`);
  }
  return runs;
}

function isLegal(delivery) {
  return !EXTRAS.has(delivery);
}

function evaluate(balls) {
  let runs = 0;
  let legal = 0;
  let wickets = 0;

  for (const delivery of balls) {
    runs += runsFor(delivery);

    if (delivery === 'wicket') {
      /* A wicket scores nothing but still consumes a ball of the over. */
      wickets += 1;
    }

    if (isLegal(delivery)) {
      legal += 1;
    }

    if (legal === BALLS_PER_OVER) {
      /* The over is complete; anything left in the list is not bowled. */
      break;
    }
  }

  return [runs, legal, wickets];
}

/* Render the tuple the way a scoreboard would show a finished over. */
function formatSummary([runs, legal, wickets]) {
  const wicketWord = wickets === 1 ? 'wicket' : 'wickets';
  return `${runs} runs off ${legal} balls, ${wickets} ${wicketWord}`;
}

function main() {
  const overs = [
    ['single', 'wide', 'wicket', 'double', 'boundary'],
    ['sixer', 'sixer', 'noball', 'single', 'wicket', 'double', 'boundary', 'sixer', 'single'],
    ['wide', 'noball', 'wide'],
  ];

  for (const over of overs) {
    const result = evaluate(over);
    /* Show both the raw triple and the human-readable line for each over. */
    console.log(JSON.stringify(result), '->', formatSummary(result));
  }
}

main();

module.exports = { evaluate, runsFor, isLegal, formatSummary };

