const AGE_DEDUCTION_PER_YEAR = 1000;
const MAX_AGE_DEDUCTION = 50000;

// The five feature slots must arrive in this fixed order
const FEATURE_NAMES = ['squareFeet', 'bedrooms', 'bathrooms', 'ageYears', 'condition'];

function parseFeatures(features) {
  if (!Array.isArray(features) || features.length !== FEATURE_NAMES.length) {
    throw new TypeError(`appraise expects ${FEATURE_NAMES.length} numeric features`);
  }
  const parsed = {};
  FEATURE_NAMES.forEach((name, index) => {
    const value = Number(features[index]);
    // Reject NaN, Infinity and negative measurements before they poison the arithmetic
    if (!Number.isFinite(value) || value < 0) {
      throw new RangeError(`${name} must be a finite non-negative number, got ${features[index]}`);
    }
    parsed[name] = value;
  });
  // The rating scale is closed: anything outside 1..5 has no defined adjustment
  if (parsed.condition < 1 || parsed.condition > 5) {
    throw new RangeError(`condition must be between 1 and 5, got ${parsed.condition}`);
  }
  return parsed;
}

function ageDeduction(ageYears) {
  // A very old house still loses at most fifty thousand
  return Math.min(ageYears * AGE_DEDUCTION_PER_YEAR, MAX_AGE_DEDUCTION);
}

function conditionMultiplier(condition) {
  // Rating 3 is the neutral midpoint, each step away is worth ten percent
  return 1 + (condition - 3) * 0.1;
}

function appraise(features) {
  const { squareFeet, bedrooms, bathrooms, ageYears, condition } = parseFeatures(features);
  const base = squareFeet * 150;
  const rooms = bedrooms * 10000 + bathrooms * 15000;
  const subtotal = base + rooms - ageDeduction(ageYears);
  // Floating point multipliers such as 1.1 leave cent-level dust, so round to whole currency
  return Math.round(subtotal * conditionMultiplier(condition));
}

function describe(features) {
  const { squareFeet, bedrooms, bathrooms, ageYears, condition } = parseFeatures(features);
  const deduction = ageDeduction(ageYears);
  const lines = [
    `${squareFeet} sq ft base: ${squareFeet * 150}`,
    `${bedrooms} bed / ${bathrooms} bath: +${bedrooms * 10000 + bathrooms * 15000}`,
    `${ageYears} years old: -${deduction}`
  ];
  // Flag the cap so a reader of the report knows the age term stopped growing
  if (deduction === MAX_AGE_DEDUCTION && ageYears * AGE_DEDUCTION_PER_YEAR > MAX_AGE_DEDUCTION) {
    lines.push('(age deduction capped at 50000)');
  }
  const percent = Math.round((conditionMultiplier(condition) - 1) * 100);
  lines.push(`condition ${condition}: ${percent >= 0 ? '+' : ''}${percent}%`);
  lines.push(`appraised value: ${appraise(features)}`);
  return lines.join('\n');
}

function main() {
  const listings = [
    [2000, 3, 2, 10, 3],
    [1500, 2, 1, 75, 1],
    [3200, 5, 3, 4, 5]
  ];
  // Print one itemised block per listing, blank line separated
  console.log(listings.map(describe).join('\n\n'));
}

module.exports = { appraise, describe, ageDeduction, conditionMultiplier };

// Only run the report when this file is the program being executed
if (require.main === module) {
  main();
}

