/* Blood transfusion compatibility checker. */
/* A blood type is written as a letter group (O, A, B, AB) followed by an rh factor. */

const LETTER_GROUPS = ["O", "A", "B", "AB"];

/* Donors are keyed by letter group; each entry lists the recipient groups they may supply. */
const DONATION_MAP = {
  O: ["O", "A", "B", "AB"],
  A: ["A", "AB"],
  B: ["B", "AB"],
  AB: ["AB"],
};

function parseType(type) {
  if (typeof type !== "string") {
    throw new TypeError("blood type must be a string");
  }
  /* Designations arrive as free text such as "  ab POSITIVE ", so normalise whitespace and case. */
  const parts = type.trim().split(/\s+/);
  if (parts.length !== 2) {
    throw new Error(`malformed blood type: "${type}"`);
  }
  const group = parts[0].toUpperCase();
  const rh = parts[1].toLowerCase();
  if (!LETTER_GROUPS.includes(group)) {
    throw new Error(`unknown letter group: "${parts[0]}"`);
  }
  /* Only the two standard rh factors are meaningful for compatibility. */
  if (rh !== "positive" && rh !== "negative") {
    throw new Error(`unknown rh factor: "${parts[1]}"`);
  }
  return { group, rh };
}

function groupCompatible(donorGroup, recipientGroup) {
  return DONATION_MAP[donorGroup].includes(recipientGroup);
}

function rhCompatible(donorRh, recipientRh) {
  /* A negative donor suits both factors, so only a positive donor can be blocked. */
  return donorRh === "negative" || recipientRh === "positive";
}

function match(types) {
  if (!Array.isArray(types) || types.length !== 2) {
    throw new Error("expected a list of exactly two blood types");
  }
  const [donor, recipient] = types.map(parseType);
  /* Both the letter group and the rh factor must clear for the transfusion to be safe. */
  const safe =
    groupCompatible(donor.group, recipient.group) &&
    rhCompatible(donor.rh, recipient.rh);
  return safe ? "safe" : "unsafe";
}

function describe(types) {
  const verdict = match(types);
  /* Render a one-line report of the pairing for human readers. */
  return `${types[0]} -> ${types[1]}: ${verdict}`;
}

