// Soil texture classification from a sand / silt / clay composition.

const TOLERANCE = 1e-9;

// Thresholds expressed as percentages, in the order the rules are applied.
const HEAVY_CLAY_MIN = 40;
const SAND_MIN = 85;
const SILT_MIN = 80;
const LOAM_MAX = { clay: 30, silt: 50, sand: 52 };

function parseComposition(percentages) {
  if (!Array.isArray(percentages) || percentages.length !== 3) {
    throw new TypeError('expected an array of three percentages [sand, silt, clay]');
  }
  const [sand, silt, clay] = percentages.map(Number);
  // A single NaN would silently poison every comparison below, so reject it up front.
  if ([sand, silt, clay].some((value) => !Number.isFinite(value))) {
    throw new TypeError('percentages must be finite numbers');
  }
  if ([sand, silt, clay].some((value) => value < 0 || value > 100)) {
    throw new RangeError('each percentage must lie between 0 and 100');
  }
  // Floating point input such as 33.3 + 33.3 + 33.4 needs the tolerance.
  if (Math.abs(sand + silt + clay - 100) > TOLERANCE) {
    throw new RangeError('percentages must sum to exactly 100');
  }
  return { sand, silt, clay };
}

function classify(percentages) {
  const { sand, silt, clay } = parseComposition(percentages);

  // Clay dominates the physical behaviour of the soil, so it is tested first.
  if (clay >= HEAVY_CLAY_MIN) {
    return 'heavy clay';
  }
  if (sand >= SAND_MIN) {
    return 'sand';
  }
  if (silt >= SILT_MIN) {
    return 'silt';
  }
  // Loam is the balanced middle: every fraction must stay under its own ceiling.
  if (clay < LOAM_MAX.clay && silt < LOAM_MAX.silt && sand < LOAM_MAX.sand) {
    return 'loam';
  }
  return 'mixed';
}

function describe(percentages) {
  const { sand, silt, clay } = parseComposition(percentages);
  const parts = [`sand ${sand}%`, `silt ${silt}%`, `clay ${clay}%`];
  return `${parts.join(', ')} -> ${classify(percentages)}`;
}

function report(samples) {
  // describe() re-validates, so a bad sample surfaces as a labelled error instead of aborting the run.
  return samples.map((sample) => {
    try {
      return describe(sample);
    } catch (error) {
      return `${JSON.stringify(sample)} -> invalid (${error.message})`;
    }
  });
}

const samples = [
  [40, 40, 20],
  [20, 30, 50],
  [90, 5, 5],
  [10, 85, 5],
  [60, 25, 15],
  [50, 60, 10],
];

// Driver: print one classified line per sample.
for (const line of report(samples)) {
  console.log(line);
}

module.exports = { classify, describe, report };

