// Exposure calculator: turns raw camera settings into an exposure value and a lighting category.

// The base exposure value formula assumes a sensitivity of ISO 100.
const BASE_ISO = 100;

function validateSettings(settings) {
  if (!Array.isArray(settings) || settings.length !== 3) {
    throw new TypeError('settings must be [aperture, shutterSeconds, iso]');
  }
  const [aperture, shutter, iso] = settings.map(Number);
  // A zero or negative shutter time would make the logarithm undefined.
  if (!(shutter > 0)) {
    throw new RangeError('shutter speed must be a positive number of seconds');
  }
  if (!(aperture > 0)) {
    throw new RangeError('aperture f-stop must be a positive number');
  }
  if (!(iso > 0)) {
    throw new RangeError('iso sensitivity must be a positive number');
  }
  return { aperture, shutter, iso };
}

function baseExposureValue(aperture, shutter) {
  // EV = log2(N^2 / t), with N the f-stop and t the exposure time in seconds.
  return Math.log2((aperture * aperture) / shutter);
}

function isoAdjustment(iso) {
  // Each doubling of the sensitivity over ISO 100 is worth one whole stop.
  return Math.log2(iso / BASE_ISO);
}

function classifyLight(ev) {
  if (ev < 0) {
    return 'night';
  }
  // Ten stops is the agreed boundary between interior light and open daylight.
  if (ev <= 10) {
    return 'indoor lighting';
  }
  return 'outdoor daylight';
}

function expose(settings) {
  const { aperture, shutter, iso } = validateSettings(settings);
  const ev = baseExposureValue(aperture, shutter) + isoAdjustment(iso);
  // Keep a single decimal place so the reported value stays photographer-friendly.
  const trimmed = Math.round(ev * 10) / 10;
  return [trimmed, classifyLight(trimmed)];
}

function describeShutter(shutter) {
  // Shutter times faster than a second are conventionally written as fractions.
  if (shutter < 1) {
    return `1/${Math.round(1 / shutter)}s`;
  }
  return `${shutter}s`;
}

function report(settings) {
  const [ev, category] = expose(settings);
  const [aperture, shutter, iso] = settings;
  return `f/${aperture} ${describeShutter(shutter)} ISO ${iso} -> EV ${ev.toFixed(1)} (${category})`;
}

function main() {
  const shots = [
    [2.8, 1 / 60, 400],
    [16, 1 / 500, 100],
    [1.4, 2, 3200],
  ];
  // The driver prints one formatted line per set of camera settings.
  for (const shot of shots) {
    console.log(report(shot));
  }
}

main();

module.exports = { expose, report, classifyLight };

