const DICE_MIN = 1;
const DICE_MAX = 6;

// A clash is described by exactly five values, in a fixed order
const FIELDS = ['attackerRoll', 'weaponStrength', 'defenderRoll', 'armorValue', 'terrainFlag'];

function parseClash(clash) {
  if (!Array.isArray(clash) || clash.length !== FIELDS.length) {
    throw new TypeError(`a clash needs ${FIELDS.length} values: ${FIELDS.join(', ')}`);
  }
  const record = {};
  FIELDS.forEach((name, index) => {
    const raw = clash[index];
    // the terrain advantage arrives as a flag, everything else as a number
    record[name] = name === 'terrainFlag' ? Boolean(raw) : Number(raw);
  });
  if (!Number.isFinite(record.weaponStrength) || !Number.isFinite(record.armorValue)) {
    throw new RangeError('weapon strength and armor value must be finite numbers');
  }
  for (const die of [record.attackerRoll, record.defenderRoll]) {
    // only real six-sided dice results can drive the critical / natural-one rules
    if (!Number.isInteger(die) || die < DICE_MIN || die > DICE_MAX) {
      throw new RangeError(`dice rolls must be integers in ${DICE_MIN}..${DICE_MAX}, got ${die}`);
    }
  }
  return record;
}

function strikePower({ attackerRoll, weaponStrength }) {
  const base = attackerRoll + weaponStrength;
  // a natural six is a critical hit and doubles the whole strike total
  return attackerRoll === DICE_MAX ? base * 2 : base;
}

function blockPower({ defenderRoll, armorValue, terrainFlag }) {
  // a natural one means the armor fails completely
  const armor = defenderRoll === DICE_MIN ? 0 : armorValue;
  const terrainBonus = terrainFlag ? 3 : 0;
  return defenderRoll + armor + terrainBonus;
}

function resolve(clash) {
  const record = parseClash(clash);
  const strike = strikePower(record);
  const block = blockPower(record);
  // anything that does not exceed the block is absorbed entirely
  return strike > block ? strike - block : 0;
}

function describeClash(clash) {
  const record = parseClash(clash);
  const damage = resolve(clash);
  const notes = [];
  if (record.attackerRoll === DICE_MAX) {
    notes.push('critical hit');
  }
  if (record.defenderRoll === DICE_MIN) {
    // worth reporting, because the defender's armor contributed nothing
    notes.push('armor ignored');
  }
  if (record.terrainFlag) {
    notes.push('terrain +3');
  }
  const outcome = damage > 0 ? `${damage} damage` : 'fully blocked';
  const suffix = notes.length ? ` (${notes.join(', ')})` : '';
  return `strike ${strikePower(record)} vs block ${blockPower(record)} -> ${outcome}${suffix}`;
}

const round = [
  [6, 2, 4, 3, false],
  [3, 1, 1, 5, false],
  [4, 4, 5, 2, true],
  [2, 3, 6, 1, false],
];

// report the round and keep a running total of the damage dealt
let total = 0;
for (const clash of round) {
  total += resolve(clash);
  console.log(`[${clash.join(', ')}] ${describeClash(clash)}`);
}
console.log(`total damage this round: ${total}`);

module.exports = { resolve, strikePower, blockPower, parseClash, describeClash };

