const SAFETY_THRESHOLD = 5;
const SAFETY_DEDUCTION = 1;

// A routine is only scorable if every numeric field is a real, finite number
function validateRoutine(routine, index) {
  const { gymnast, apparatus, execution, difficulty, deduction } = routine;
  if (typeof gymnast !== 'string' || gymnast.trim() === '') {
    throw new Error(`Routine ${index}: missing gymnast name`);
  }
  if (typeof apparatus !== 'string' || apparatus.trim() === '') {
    throw new Error(`Routine ${index}: missing apparatus for ${gymnast}`);
  }
  for (const [field, value] of [['execution', execution], ['difficulty', difficulty], ['deduction', deduction]]) {
    // Number.isFinite rejects strings, NaN and Infinity in one step
    if (!Number.isFinite(value)) {
      throw new Error(`Routine ${index}: ${field} of ${gymnast} on ${apparatus} is not a number`);
    }
  }
  // Execution is judged out of ten, so anything outside that range is a data error
  if (execution < 0 || execution > 10) {
    throw new Error(`Routine ${index}: execution ${execution} out of range for ${gymnast}`);
  }
}

function scoreRoutine(routine) {
  const { execution, difficulty, deduction } = routine;
  let mark = execution + difficulty - deduction;
  // A shaky landing below five costs an extra mandatory point
  if (execution < SAFETY_THRESHOLD) {
    mark -= SAFETY_DEDUCTION;
  }
  return mark;
}

function evaluate(routines) {
  const totals = new Map();
  routines.forEach((routine, index) => {
    validateRoutine(routine, index);
    const name = routine.gymnast.trim();
    // Several apparatus scores from one gymnast accumulate into a single standing
    const running = totals.get(name) || 0;
    totals.set(name, running + scoreRoutine(routine));
  });
  const standings = [...totals].map(([gymnast, mark]) => ({ gymnast, mark }));
  standings.sort((a, b) => {
    // Highest mark first; equal marks fall back to alphabetical order
    if (b.mark !== a.mark) return b.mark - a.mark;
    return a.gymnast.localeCompare(b.gymnast);
  });
  return standings;
}

function formatStandings(standings) {
  // Column width follows the longest name so the printed table lines up
  const width = standings.reduce((max, entry) => Math.max(max, entry.gymnast.length), 0);
  return standings
    .map((entry, i) => `${i + 1}. ${entry.gymnast.padEnd(width)}  ${entry.mark.toFixed(2)}`)
    .join('\n');
}

const teamRoutines = [
  { gymnast: 'Nadia', apparatus: 'beam', execution: 8, difficulty: 6, deduction: 0.5 },
  { gymnast: 'Nadia', apparatus: 'vault', execution: 9.2, difficulty: 5.4, deduction: 0.3 },
  { gymnast: 'Kohei', apparatus: 'rings', execution: 4.6, difficulty: 6.8, deduction: 0.2 },
  { gymnast: 'Kohei', apparatus: 'floor', execution: 8.8, difficulty: 6.1, deduction: 0 },
  { gymnast: 'Simone', apparatus: 'vault', execution: 9.5, difficulty: 6.4, deduction: 0.1 },
  { gymnast: 'Aliya', apparatus: 'bars', execution: 7.0, difficulty: 6.3, deduction: 1.2 },
];

const finalStandings = evaluate(teamRoutines);
console.log(formatStandings(finalStandings));
// The winner takes the team slot for the all-around final
console.log(`Team representative: ${finalStandings[0].gymnast}`);

module.exports = { evaluate, scoreRoutine, formatStandings };

