// Wind chill index calculator.
// The Environment Canada formula is only valid for low temperatures and
// non-negligible wind, so readings outside that domain are passed through.

const TEMP_THRESHOLD = 10;
const WIND_THRESHOLD = 4.8;
const WIND_EXPONENT = 0.16;

// Rounds to one decimal place without the binary-float surprises of toFixed
// on values such as 1.005 by nudging through an exponential string form.
function roundToTenth(value) {
  return Number(`${Math.round(Number(`${value}e1`))}e-1`);
}

function validateReading(reading, position) {
  if (!Array.isArray(reading) || reading.length !== 2) {
    throw new TypeError(`Reading at ${position} must be a [temperature, windSpeed] pair`);
  }
  const [temperature, windSpeed] = reading;
  // Both components must be real numbers; NaN would silently poison the math.
  if (!Number.isFinite(temperature) || !Number.isFinite(windSpeed)) {
    throw new TypeError(`Reading at ${position} contains a non-numeric value`);
  }
  if (windSpeed < 0) {
    throw new RangeError(`Reading at ${position} has a negative wind speed`);
  }
  return [temperature, windSpeed];
}

function windChill(temperature, windSpeed) {
  const windFactor = Math.pow(windSpeed, WIND_EXPONENT);
  return 13.12 + 0.6215 * temperature - 11.37 * windFactor + 0.3965 * temperature * windFactor;
}

function index(conditions) {
  if (!Array.isArray(conditions)) {
    throw new TypeError('index expects a list of weather readings');
  }
  return conditions.map((reading, position) => {
    const [temperature, windSpeed] = validateReading(reading, position);
    // Warm air or a light breeze: the body feels the ambient temperature.
    if (temperature > TEMP_THRESHOLD || windSpeed < WIND_THRESHOLD) {
      return roundToTenth(temperature);
    }
    return roundToTenth(windChill(temperature, windSpeed));
  });
}

// Pairs each raw reading with its perceived value for human-readable output.
function report(conditions) {
  const perceived = index(conditions);
  return conditions.map(([temperature, windSpeed], position) => {
    const felt = perceived[position];
    const delta = roundToTenth(felt - temperature);
    // A zero delta means the formula was skipped, which is worth stating plainly.
    const note = delta === 0 ? 'no wind chill effect' : `${delta} degree shift`;
    return `${temperature}C at ${windSpeed} km/h feels like ${felt}C (${note})`;
  });
}

const readings = [
  [10, 4.8],
  [10.1, 20],
  [-5, 25],
  [0, 4.7],
  [-20, 50],
];

// Driver: print the perceived temperatures, then the annotated report.
console.log(index(readings).join(', '));
for (const line of report(readings)) {
  console.log(line);
}

module.exports = { index, report, windChill };

