const RED_NUMBERS = new Set([1, 3, 5, 7, 9, 12, 14, 16, 18, 19, 21, 23, 25, 27, 30, 32, 34, 36]);

// payout multipliers keyed by bet type, expressed as "to one" odds
const ODDS = { straight: 35, split: 17, corner: 8, red: 1, black: 1, odd: 1, even: 1, high: 1, low: 1 };

// number of picks a positional bet must contain to be legal
const PICK_COUNT = { straight: 1, split: 2, corner: 4 };

function isWinner(bet, winning) {
  switch (bet.type) {
    case 'straight':
    case 'split':
    case 'corner':
      return bet.numbers.includes(winning);
    // zero is neither red nor black, and counts as neither odd nor even here
    case 'red':
      return RED_NUMBERS.has(winning);
    case 'black':
      return winning !== 0 && !RED_NUMBERS.has(winning);
    case 'odd':
      return winning !== 0 && winning % 2 === 1;
    case 'even':
      return winning !== 0 && winning % 2 === 0;
    // low covers 1-18, high covers 19-36, so zero loses both
    case 'high':
      return winning >= 19;
    case 'low':
      return winning >= 1 && winning <= 18;
    default:
      throw new Error(`unknown bet type: ${bet.type}`);
  }
}

function validate(bets) {
  const { winning, records } = bets;
  // a European wheel only has pockets 0 through 36
  if (!Number.isInteger(winning) || winning < 0 || winning > 36) {
    throw new Error(`invalid winning number: ${winning}`);
  }
  records.forEach((bet, i) => {
    if (!(bet.type in ODDS)) throw new Error(`bet ${i} has unknown type ${bet.type}`);
    if (!(bet.wager > 0)) throw new Error(`bet ${i} has a non-positive wager`);
    const expected = PICK_COUNT[bet.type];
    // only positional bets carry picks; category bets must not
    if (expected !== undefined && (!Array.isArray(bet.numbers) || bet.numbers.length !== expected)) {
      throw new Error(`bet ${i} of type ${bet.type} needs exactly ${expected} number(s)`);
    }
  });
}

function settle(bets) {
  validate(bets);
  return bets.records.reduce((total, bet) => {
    // winners return the odds times the wager, losers forfeit the wager
    if (isWinner(bet, bets.winning)) return total + bet.wager * ODDS[bet.type];
    return total - bet.wager;
  }, 0);
}

function describe(bet, winning) {
  const picks = bet.numbers ? ` ${bet.numbers.join('/')}` : '';
  const result = isWinner(bet, winning) ? `+${bet.wager * ODDS[bet.type]}` : `-${bet.wager}`;
  return `${bet.type}${picks} @ ${bet.wager}: ${result}`;
}

function main() {
  const table = {
    winning: 17,
    records: [
      { type: 'straight', numbers: [17], wager: 5 },
      { type: 'split', numbers: [17, 20], wager: 10 },
      { type: 'corner', numbers: [1, 2, 4, 5], wager: 20 },
      { type: 'black', wager: 50 },
      { type: 'odd', wager: 25 },
      { type: 'high', wager: 25 },
    ],
  };
  // per-bet breakdown first, so the final figure can be checked by hand
  table.records.forEach((bet) => console.log(describe(bet, table.winning)));
  console.log(`winning number ${table.winning}, net result: ${settle(table)}`);
}

main();

module.exports = { settle, isWinner, describe };

