// Corporate bond yield calculations: current yield and approximate yield to maturity.

// Reject inputs that would make the yield formulas meaningless.
function validateBond(bond) {
  if (bond === null || typeof bond !== 'object') {
    throw new TypeError('bond must be an object');
  }
  const { faceValue, couponRate, marketPrice, yearsToMaturity } = bond;
  const numeric = { faceValue, couponRate, marketPrice, yearsToMaturity };
  for (const [key, value] of Object.entries(numeric)) {
    // Number.isFinite also rejects strings, NaN and Infinity.
    if (!Number.isFinite(value)) {
      throw new TypeError(`${key} must be a finite number`);
    }
  }
  // A zero price would divide by zero in the current-yield step.
  if (marketPrice <= 0) {
    throw new RangeError('marketPrice must be greater than zero');
  }
  if (faceValue <= 0) {
    throw new RangeError('faceValue must be greater than zero');
  }
  // Years to maturity divides the capital gain, so it cannot be zero either.
  if (yearsToMaturity <= 0) {
    throw new RangeError('yearsToMaturity must be greater than zero');
  }
  return numeric;
}

function round2(value) {
  return Math.round(value * 100) / 100;
}

function yieldOf(bond) {
  const { faceValue, couponRate, marketPrice, yearsToMaturity } = validateBond(bond);

  // Coupon rate arrives as a percentage, so scale it down to a fraction.
  const annualCoupon = faceValue * (couponRate / 100);

  const currentYield = (annualCoupon / marketPrice) * 100;

  // Spread the discount or premium evenly across the remaining years.
  const annualizedGain = (faceValue - marketPrice) / yearsToMaturity;
  const averageValue = (faceValue + marketPrice) / 2;
  const yieldToMaturity = ((annualCoupon + annualizedGain) / averageValue) * 100;

  return {
    currentYield: round2(currentYield),
    yieldToMaturity: round2(yieldToMaturity)
  };
}

// Expose the function under the name required by the task.
const yieldFn = yieldOf;

function formatReport(name, bond) {
  const { currentYield, yieldToMaturity } = yieldFn(bond);
  // toFixed keeps trailing zeros that rounding alone would drop.
  return `${name}: current yield ${currentYield.toFixed(2)}%, YTM ${yieldToMaturity.toFixed(2)}%`;
}

function main() {
  const portfolio = [
    ['Discount bond', { faceValue: 1000, couponRate: 5, marketPrice: 950, yearsToMaturity: 10 }],
    ['Par bond', { faceValue: 1000, couponRate: 6, marketPrice: 1000, yearsToMaturity: 5 }],
    ['Premium bond', { faceValue: 1000, couponRate: 8, marketPrice: 1080, yearsToMaturity: 4 }]
  ];

  for (const [name, bond] of portfolio) {
    console.log(formatReport(name, bond));
  }

  // Show that malformed input is reported rather than silently returning NaN.
  try {
    yieldFn({ faceValue: 1000, couponRate: 5, marketPrice: 0, yearsToMaturity: 10 });
  } catch (err) {
    console.log(`Rejected: ${err.message}`);
  }
}

main();

module.exports = { yield: yieldFn, formatReport, validateBond };

