// Rule-of-twelfths tide estimation.
// The twelfths that are gained during each successive sixth of the interval
// between two tide extremes (low->high or high->low).
const TWELFTHS = [1, 2, 3, 3, 2, 1];

// Times are expressed in minutes since midnight, so a day wraps at 1440.
const MINUTES_PER_DAY = 1440;

function parseTime(value) {
  if (typeof value === 'number') return value;
  // Accept "HH:MM" clock strings as well as raw minute counts.
  const match = /^(\d{1,2}):(\d{2})$/.exec(String(value).trim());
  if (!match) throw new Error(`cannot parse time: ${value}`);
  const hours = Number(match[1]);
  const minutes = Number(match[2]);
  if (hours > 23 || minutes > 59) throw new Error(`time out of range: ${value}`);
  return hours * 60 + minutes;
}

function formatTime(minutes) {
  const wrapped = ((minutes % MINUTES_PER_DAY) + MINUTES_PER_DAY) % MINUTES_PER_DAY;
  const hh = String(Math.floor(wrapped / 60)).padStart(2, '0');
  const mm = String(wrapped % 60).padStart(2, '0');
  return `${hh}:${mm}`;
}

function span(from, to) {
  const diff = to - from;
  // A negative difference means the later extreme is past midnight.
  return diff >= 0 ? diff : diff + MINUTES_PER_DAY;
}

// Fraction of the total range that has been gained after `elapsed` of `duration`.
function twelfthsGained(elapsed, duration) {
  const sixth = duration / 6;
  let gained = 0;
  for (let i = 0; i < TWELFTHS.length; i += 1) {
    const remaining = elapsed - i * sixth;
    if (remaining <= 0) break;
    // Inside the current sixth the level changes linearly.
    const portion = Math.min(remaining / sixth, 1);
    gained += TWELFTHS[i] * portion;
  }
  return gained / 12;
}

function estimate(tides) {
  const start = parseTime(tides.previousTime);
  const end = parseTime(tides.nextTime);
  const target = parseTime(tides.targetTime);
  const duration = span(start, end);
  if (duration === 0) throw new Error('the two extremes must differ in time');
  const elapsed = span(start, target);
  if (elapsed > duration) throw new Error('target time lies outside the interval');
  const range = tides.nextHeight - tides.previousHeight;
  return tides.previousHeight + range * twelfthsGained(elapsed, duration);
}

function report(tides) {
  const height = estimate(tides);
  // Two decimals is plenty for a tide table read off a chart.
  return `${formatTime(parseTime(tides.targetTime))} -> ${height.toFixed(2)} m`;
}

const lowWater = { previousTime: '06:24', previousHeight: 0.9, nextTime: '12:42', nextHeight: 5.4 };

// Walk the rising tide hour by hour and print the estimated depth.
for (let t = parseTime(lowWater.previousTime); t <= parseTime(lowWater.nextTime); t += 60) {
  console.log(report({ ...lowWater, targetTime: t }));
}

// The falling tide reuses the same machinery with the heights reversed.
console.log(report({
  previousTime: '12:42',
  previousHeight: 5.4,
  nextTime: '19:06',
  nextHeight: 1.1,
  targetTime: '15:54',
}));

module.exports = { estimate, report, parseTime, formatTime };

