'use strict';

// Angles in the spoke-hole computation are expressed in degrees first,
// so a small conversion helper keeps the main formula readable.
function toRadians(degrees) {
  return (degrees * Math.PI) / 180;
}

// A wheel description is only usable when every measurement is a finite
// positive number; a zero spoke count would also divide by zero below.
function validate(wheel) {
  const required = ['rimDiameter', 'hubDiameter', 'hubCenterToFlange', 'spokeCount', 'crosses'];

  for (const key of required) {
    const value = wheel[key];
    if (typeof value !== 'number' || !Number.isFinite(value)) {
      throw new TypeError(`wheel.${key} must be a finite number`);
    }
  }

  // Spoke count must be even: half of them go to each flange.
  if (wheel.spokeCount <= 0 || wheel.spokeCount % 2 !== 0) {
    throw new RangeError('wheel.spokeCount must be a positive even number');
  }

  if (wheel.crosses < 0) {
    throw new RangeError('wheel.crosses cannot be negative');
  }
}

// Angle between the hub hole and the rim hole a spoke connects, in degrees.
function spokeHoleAngle(spokeCount, crosses) {
  return (360 / (spokeCount / 2)) * crosses;
}

function length(wheel) {
  validate(wheel);

  const { rimDiameter, hubDiameter, hubCenterToFlange, spokeCount, crosses } = wheel;
  const angle = toRadians(spokeHoleAngle(spokeCount, crosses));

  const squares =
    Math.pow(rimDiameter / 2, 2) +
    Math.pow(hubDiameter / 2, 2) +
    Math.pow(hubCenterToFlange, 2);

  // The cosine term shortens the chord as the lacing pattern gets more crossed.
  const correction = rimDiameter * hubDiameter * Math.cos(angle);

  return Math.round(Math.sqrt(squares - correction) * 10) / 10;
}

// Report one line per wheel so a build sheet can be read at a glance.
function describe(wheel) {
  const pattern = wheel.crosses === 0 ? 'radial' : `${wheel.crosses}-cross`;
  return `${wheel.spokeCount} spokes, ${pattern}: ${length(wheel).toFixed(1)} mm`;
}

const buildSheet = [
  { rimDiameter: 600, hubDiameter: 40, hubCenterToFlange: 30, spokeCount: 32, crosses: 3 },
  { rimDiameter: 559, hubDiameter: 58, hubCenterToFlange: 35, spokeCount: 36, crosses: 3 },
  // Radial lacing leaves the cosine term at its maximum, giving the shortest spoke.
  { rimDiameter: 622, hubDiameter: 44, hubCenterToFlange: 33, spokeCount: 24, crosses: 0 }
];

for (const wheel of buildSheet) {
  console.log(describe(wheel));
}

module.exports = { length, spokeHoleAngle, describe };

