const SPECS = {
  // Each spec holds the inclusive temperature window (C) and steeping window (s)
  green: { tempMin: 70, tempMax: 80, timeMin: 120, timeMax: 180 },
  black: { tempMin: 90, tempMax: 95, timeMin: 200, timeMax: 300 },
  // White tea has no lower bound on time, so anything up to 150 s is acceptable
  white: { tempMin: 80, tempMax: 85, timeMin: 0, timeMax: 150 }
};

function normalizeType(type) {
  // Trial data often comes from spreadsheets, so accept "Green Tea", " GREEN ", etc.
  const cleaned = String(type).trim().toLowerCase().replace(/\s*tea$/, '');
  if (!Object.prototype.hasOwnProperty.call(SPECS, cleaned)) {
    throw new Error(`unknown tea type: ${type}`);
  }
  return cleaned;
}

function readNumber(value, label) {
  const num = typeof value === 'string' ? Number(value.trim()) : value;
  // Reject NaN, Infinity and non-numeric junk before comparing against a window
  if (typeof num !== 'number' || !Number.isFinite(num)) {
    throw new Error(`${label} must be a finite number, got: ${value}`);
  }
  return num;
}

function evaluateTrial(trial) {
  const spec = SPECS[normalizeType(trial.type)];
  const temperature = readNumber(trial.temperature, 'temperature');
  const time = readNumber(trial.time, 'time');

  const tooHot = temperature > spec.tempMax;
  const tooLong = time > spec.timeMax;
  // Excess heat or excess contact time both pull tannins out, which dominates
  if (tooHot || tooLong) return 'over extracted';

  const tooCool = temperature < spec.tempMin;
  const tooShort = time < spec.timeMin;
  if (tooCool || tooShort) return 'under extracted';

  return 'optimal';
}

function optimize(parameters) {
  // The task guarantees a list of trials; anything else is a caller mistake
  if (!Array.isArray(parameters)) {
    throw new TypeError('optimize expects a list of brewing trials');
  }
  return parameters.map(evaluateTrial);
}

function formatReport(parameters, evaluations) {
  return parameters.map((trial, i) => {
    const type = normalizeType(trial.type);
    const label = type[0].toUpperCase() + type.slice(1);
    // Pad so the verdict column lines up in the console output
    const brew = `${label} @ ${trial.temperature}C / ${trial.time}s`.padEnd(30);
    return `${brew}-> ${evaluations[i]}`;
  }).join('\n');
}

function main() {
  const trials = [
    { type: 'green', temperature: 75, time: 150 },
    { type: 'Green Tea', temperature: 95, time: 150 },
    { type: 'green', temperature: 72, time: 90 },
    { type: 'black', temperature: 92, time: 250 },
    { type: 'black', temperature: 88, time: 400 },
    { type: 'white', temperature: 82, time: 40 },
    { type: 'white', temperature: '84', time: '150' }
  ];

  const evaluations = optimize(trials);
  console.log(formatReport(trials, evaluations));

  const optimalCount = evaluations.filter(v => v === 'optimal').length;
  // A quick yield figure tells the taster whether the run is worth repeating
  console.log(`\n${optimalCount}/${evaluations.length} trials hit the optimal window`);
}

main();

