// Soil moisture deficit model.
//
// The deficit is the amount of water (in mm) that would have to be added to
// bring the soil back to field capacity: evapotranspiration dries the soil out
// and raises it, rainfall wets the soil and lowers it.

function validateWeather(weather) {
  // The model is meaningless without a starting point and a capacity
  if (!weather || typeof weather !== 'object') {
    throw new TypeError('weather must be an object');
  }
  const { initial, capacity, days } = weather;
  if (!Number.isFinite(initial) || initial < 0) {
    throw new RangeError('initial deficit must be a non-negative number');
  }
  // A capacity of zero would mean the soil can never hold a deficit at all
  if (!Number.isFinite(capacity) || capacity <= 0) {
    throw new RangeError('capacity must be a positive number');
  }
  if (!Array.isArray(days)) {
    throw new TypeError('days must be an array of daily records');
  }
  return { initial, capacity, days };
}

function stepDeficit(current, day, capacity) {
  // Missing readings are treated as "nothing measured", i.e. zero mm
  const rain = Number.isFinite(day.rain) ? day.rain : 0;
  const et = Number.isFinite(day.et) ? day.et : 0;
  const next = current + et - rain;
  if (next < 0) {
    // Soil is saturated; the surplus runs off instead of being stored
    return 0;
  }
  // Water below the capacity is unavailable, so the deficit plateaus there
  return Math.min(next, capacity);
}

function deficit(weather) {
  const { initial, capacity, days } = validateWeather(weather);
  // The starting deficit itself must respect the capacity of the soil
  let current = Math.min(initial, capacity);
  const daily = [];
  for (const day of days) {
    current = stepDeficit(current, day, capacity);
    daily.push(current);
  }
  return daily;
}

function formatReport(weather) {
  const daily = deficit(weather);
  const lines = ['day  rain    et  deficit'];
  daily.forEach((value, index) => {
    const day = weather.days[index];
    const rain = (Number.isFinite(day.rain) ? day.rain : 0).toFixed(1);
    const et = (Number.isFinite(day.et) ? day.et : 0).toFixed(1);
    // Right-align the columns so the report reads like a gauge log
    lines.push(
      String(index + 1).padStart(3) +
        rain.padStart(6) +
        et.padStart(6) +
        value.toFixed(1).padStart(9)
    );
  });
  return lines.join('\n');
}

function main() {
  const weather = {
    initial: 10,
    capacity: 50,
    days: [
      { rain: 0, et: 5 },
      { rain: 0, et: 5 },
      // A downpour large enough to saturate the soil and cause runoff
      { rain: 30, et: 4 },
      { rain: 2, et: 6 },
    ],
  };
  console.log(formatReport(weather));
  console.log('deficits:', deficit(weather).join(', '));
}

main();

module.exports = { deficit, stepDeficit, formatReport };

