/* Seismic magnitude conversion utilities: energy, TNT equivalent, class and felt radius. */

/* Descriptive classes keyed by the integer part of the magnitude. */
const MAGNITUDE_CLASSES = {
  0: 'micro',
  1: 'micro',
  2: 'minor',
  3: 'minor',
  4: 'light',
  5: 'moderate',
  6: 'strong',
  7: 'major',
};

/* Energy released by one ton of TNT, in joules. */
const JOULES_PER_TON_TNT = 4.184e9;

function classify(magnitude) {
  const step = Math.floor(magnitude);
  /* Anything at or above magnitude 8 is lumped into the "great" class. */
  if (step >= 8) return 'great';
  return MAGNITUDE_CLASSES[step];
}

function feltRadius(magnitude) {
  /* Perceptibility grows exponentially with magnitude; 0.6 is the scaling factor. */
  return 10 * Math.exp(0.6 * magnitude);
}

function convert(magnitude) {
  if (typeof magnitude !== 'number' || Number.isNaN(magnitude)) {
    throw new TypeError('convert expects a numeric Richter reading');
  }

  /* Negative readings are negligible tremors, so every output collapses to zero. */
  if (magnitude < 0) return [0, 0, 0, 0];

  const joules = Math.pow(10, 1.5 * magnitude + 4.8);
  const tons = joules / JOULES_PER_TON_TNT;

  return [joules, tons, classify(magnitude), feltRadius(magnitude)];
}

