// Darts 501 scoring: each throw is [points, multiplier] and the game must end on a double.

const STARTING_SCORE = 501;

// A dartboard segment is either a miss, one of the twenty numbers, or the bullseye.
const VALID_POINTS = new Set([0, 25, ...Array.from({ length: 20 }, (_, i) => i + 1)]);

function validateThrow(candidate, index) {
  if (!Array.isArray(candidate) || candidate.length !== 2) {
    throw new TypeError(`throw ${index} must be an array of [points, multiplier]`);
  }
  const [points, multiplier] = candidate;
  // Both halves of a throw are counted in whole units, never fractions.
  if (!Number.isInteger(points) || !Number.isInteger(multiplier)) {
    throw new TypeError(`throw ${index} must contain integers`);
  }
  if (!VALID_POINTS.has(points)) {
    throw new RangeError(`throw ${index} has an impossible point value: ${points}`);
  }
  // The bullseye ring only supports single and double; the numbered beds go up to treble.
  const maxMultiplier = points === 25 ? 2 : 3;
  if (multiplier < 1 || multiplier > maxMultiplier) {
    throw new RangeError(`throw ${index} has an invalid multiplier: ${multiplier}`);
  }
  return [points, multiplier];
}

function score(throws) {
  let running = STARTING_SCORE;

  for (let i = 0; i < throws.length; i += 1) {
    const [points, multiplier] = validateThrow(throws[i], i);
    const deduction = points * multiplier;
    const remaining = running - deduction;

    // Overshooting the target busts the turn and leaves the score untouched.
    if (deduction > running) continue;

    // One point left is unfinishable, because no double can score a single point.
    if (remaining === 1) continue;

    if (remaining === 0 && multiplier !== 2) {
      // Landing on zero with a single or treble does not check out.
      continue;
    }

    running = remaining;

    // A double that lands exactly on zero wins, so the rest of the darts are never thrown.
    if (running === 0) break;
  }

  return running;
}

function describeGame(throws) {
  const finalScore = score(throws);
  // The win condition is the only way for the running score to reach zero.
  const verdict = finalScore === 0 ? 'game shot' : `${finalScore} remaining`;
  const sequence = throws
    .map(([points, multiplier]) => `${'.SDT'[multiplier]}${points}`)
    .join(' ');
  return `${sequence} -> ${verdict}`;
}

function main() {
  const games = [
    [[20, 3], [20, 1]],
    [[20, 3], [20, 3], [20, 3], [20, 3], [20, 3], [20, 3], [20, 3], [17, 3], [25, 2]],
    [[25, 2], [20, 3], [1, 1]],
  ];
  // Report each sample game; the first one deducts eighty points from 501.
  for (const game of games) {
    console.log(describeGame(game));
  }
}

main();

module.exports = { score, describeGame, validateThrow };

