// Blood pressure classification based on standard ACC/AHA categories.

function categorize(readings) {
  const [systolic, diastolic] = readings;

  // A non-positive cuff value means the measurement never completed.
  if (systolic <= 0 || diastolic <= 0) {
    return ['Invalid reading'];
  }

  let category;

  // Hypertensive crisis dominates: either number alone is enough to trigger it.
  if (systolic > 180 || diastolic > 120) {
    category = 'Hypertensive crisis';
  } else if (systolic >= 140 || diastolic >= 90) {
    category = 'Stage 2 hypertension';
  } else if (systolic >= 130 || diastolic >= 80) {
    // Stage 1 also catches the 130-139 systolic band with a normal diastolic.
    category = 'Stage 1 hypertension';
  } else if (systolic >= 120 && diastolic < 80) {
    category = 'Elevated';
  } else {
    // Remaining case: systolic under 120 and diastolic under 80.
    category = 'Normal';
  }

  // Pulse pressure is the gap between the two readings.
  const pulsePressure = systolic - diastolic;

  return [category, pulsePressure];
}

function parseReading(text) {
  // Accept the usual "120/80" chart notation.
  const parts = String(text).split('/');
  if (parts.length !== 2) {
    throw new Error(`Malformed reading: ${text}`);
  }
  return parts.map((part) => Number.parseInt(part.trim(), 10));
}

function describe(text) {
  const result = categorize(parseReading(text));

  // The invalid case carries no pulse pressure, so report it on its own.
  if (result.length === 1) {
    return `${text.padEnd(8)} -> ${result[0]}`;
  }

  const [category, pulsePressure] = result;
  return `${text.padEnd(8)} -> ${category} (pulse pressure ${pulsePressure})`;
}

function report(chart) {
  return chart.map((text) => {
    try {
      return describe(text);
    } catch (err) {
      // Keep the batch going when a single chart entry is unreadable.
      return `${text} -> ${err.message}`;
    }
  });
}

const chart = ['118/75', '124/78', '133/85', '150/95', '190/100', '0/80', '12080'];

// Print one line per charted measurement.
for (const line of report(chart)) {
  console.log(line);
}

module.exports = { categorize, parseReading, describe, report };

