const AUTOLYSE_HOURS = 1;
const SHAPING_HOURS = 1;
const COLD_RETARD_HOURS = 12;

// Guard the public entry point: the three readings must all be present and numeric
function validateConditions(conditions) {
  if (!Array.isArray(conditions) || conditions.length !== 3) {
    throw new TypeError('conditions must be [startHour, roomTemp, hydration]');
  }
  for (const value of conditions) {
    // Reject NaN and non-numeric entries, which would silently poison the arithmetic
    if (typeof value !== 'number' || Number.isNaN(value)) {
      throw new TypeError('every condition must be a real number');
    }
  }
}

// Warm kitchens accelerate the dough: half an hour off the six hour base per degree over 20C
function bulkFermentationHours(roomTemp, hydration) {
  const base = 6;
  const warmthPenalty = Math.max(0, roomTemp - 20) * 0.5;
  // A very liquid starter is far more active, so it shortens the bulk by a full hour
  const hydrationPenalty = hydration > 80 ? 1 : 0;
  const bulk = base - warmthPenalty - hydrationPenalty;
  // Never schedule a non-positive bulk; half an hour is the shortest workable window
  return Math.max(0.5, bulk);
}

function timetable(conditions) {
  validateConditions(conditions);
  const [startHour, roomTemp, hydration] = conditions;
  const bulk = bulkFermentationHours(roomTemp, hydration);
  const total = AUTOLYSE_HOURS + bulk + SHAPING_HOURS + COLD_RETARD_HOURS;
  // The timeline wraps around midnight, hence the modulo on a 24 hour clock
  const bakeHour = (startHour + total) % 24;
  return [bulk, total, bakeHour];
}

// Turn a possibly fractional clock position into a readable HH:MM stamp
function formatClock(hour) {
  const whole = Math.floor(hour);
  const minutes = Math.round((hour - whole) * 60);
  return `${String(whole).padStart(2, '0')}:${String(minutes).padStart(2, '0')}`;
}

function describeSchedule(conditions) {
  const [bulk, total, bakeHour] = timetable(conditions);
  const [startHour] = conditions;
  const phases = [
    ['autolyse', AUTOLYSE_HOURS],
    ['bulk fermentation', bulk],
    ['shaping and bench rest', SHAPING_HOURS],
    ['cold retard', COLD_RETARD_HOURS]
  ];
  const lines = [];
  let cursor = startHour;
  for (const [name, duration] of phases) {
    // Each phase starts where the previous one ended, again wrapped to the clock
    lines.push(`${formatClock(cursor % 24)}  ${name} (${duration}h)`);
    cursor += duration;
  }
  lines.push(`${formatClock(bakeHour)}  bake  [total ${total}h]`);
  return lines.join('\n');
}

// Driver: two doughs, one in a cool kitchen with a stiff starter, one hot and very wet
const samples = [[9, 20, 70], [14, 26, 100]];
for (const sample of samples) {
  console.log(`conditions ${JSON.stringify(sample)} -> ${JSON.stringify(timetable(sample))}`);
  console.log(describeSchedule(sample));
  console.log('');
}

module.exports = { timetable, bulkFermentationHours, describeSchedule, formatClock };

