// A board is only usable here if all four measurements are finite positive numbers
function validateBoard(board, index) {
  if (!Array.isArray(board) || board.length !== 4) {
    throw new TypeError(`Board ${index} must be [thickness, width, length, density]`);
  }
  const labels = ['thickness', 'width', 'length', 'density'];
