const DNF_PENALTY = 1e12;

// A boat entry must carry an id, an elapsed time and a rating factor
function parseEntry(entry) {
  const [id, seconds, rating] = entry;
  if (typeof id === 'undefined' || id === null) {
    throw new TypeError('each boat needs an identification number');
  }
  // Negative or non numeric times cannot be corrected in any meaningful way
  if (!Number.isFinite(seconds) || seconds < 0) {
    throw new RangeError(`boat ${id} has an invalid elapsed time: ${seconds}`);
  }
  if (!Number.isFinite(rating) || rating <= 0) {
    throw new RangeError(`boat ${id} has an invalid rating factor: ${rating}`);
  }
  return { id, seconds, rating };
}

function score(boats) {
  // Result list holds [id, correctedTime] pairs before sorting
  const results = [];
  for (const entry of boats) {
    const { id, seconds, rating } = parseEntry(entry);
    let corrected = seconds * rating;
    let finished = true;
    // An elapsed time of exactly zero means the boat never crossed the line
    if (seconds === 0) {
      finished = false;
      corrected = DNF_PENALTY;
    }
    results.push([id, corrected, finished]);
  }
  // Lowest corrected time takes first place, so sort ascending
  results.sort((a, b) => a[1] - b[1]);
  const placements = results.map((row) => row[0]);
  // The gap only exists once there is a second boat to compare against
  const gapToSecond = results.length > 1 ? results[1][1] - results[0][1] : 0;
  return [placements, gapToSecond];
}

// Corrected times are easier to read as minutes and seconds
function formatTime(totalSeconds) {
  if (totalSeconds >= DNF_PENALTY) {
    return 'DNF';
  }
  const minutes = Math.floor(totalSeconds / 60);
  const seconds = (totalSeconds - minutes * 60).toFixed(1);
  return `${minutes}:${seconds.padStart(4, '0')}`;
}

function report(boats) {
  const [placements, gapToSecond] = score(boats);
  // Rebuild a lookup so the report can print each boat's corrected time
  const corrected = new Map();
  for (const entry of boats) {
    const { id, seconds, rating } = parseEntry(entry);
    corrected.set(id, seconds === 0 ? DNF_PENALTY : seconds * rating);
  }
  const lines = placements.map((id, index) => {
    const place = index + 1;
    return `${place}. boat ${id} — ${formatTime(corrected.get(id))}`;
  });
  // A dead heat at the top is worth calling out explicitly
  if (gapToSecond === 0 && placements.length > 1) {
    lines.push('Tie for first place');
  } else if (placements.length > 1) {
    lines.push(`Margin to second: ${gapToSecond.toFixed(1)}s`);
  }
  return lines.join('\n');
}

const roster = [
  [17, 3612, 0.98],
  [4, 3540, 1.02],
  [23, 0, 0.95],
  [8, 3701, 0.94],
];

console.log(report(roster));

module.exports = { score, report, formatTime };

