// Sugar-beet style harvest estimator: converts field geometry into an
// estimated tonnage of roots delivered to the weighbridge.

const SQ_FT_PER_ACRE = 43560;
const INCHES_PER_FOOT = 12;
const GRAMS_PER_METRIC_TON = 1e6;
const FIELD_LOSS_FACTOR = 0.05; // mechanical damage during lifting

// The four inputs are all physical measurements, so anything non-positive
// (or non-numeric) makes the rest of the arithmetic meaningless.
function validateField(field) {
  if (!Array.isArray(field) || field.length !== 4) {
    throw new TypeError('field must be [acres, rowSpacing, plantSpacing, rootWeight]');
  }
  const labels = ['acres', 'row spacing', 'plant spacing', 'root weight'];
  field.forEach((value, i) => {
    // Number.isFinite rejects strings, NaN and Infinity in one go.
    if (!Number.isFinite(value) || value <= 0) {
      throw new RangeError(`${labels[i]} must be a positive finite number`);
    }
  });
}

function yield(field) {
  validateField(field);
  const [acres, rowSpacingIn, plantSpacingIn, rootWeightG] = field;

  const areaSqFt = acres * SQ_FT_PER_ACRE;
  // A square field of this area has sides of sqrt(area); that side length is
  // both the run of each row and the distance across which rows are laid out.
  const sideFt = Math.sqrt(areaSqFt);

  const rowSpacingFt = rowSpacingIn / INCHES_PER_FOOT;
  const plantSpacingFt = plantSpacingIn / INCHES_PER_FOOT;

  const rows = sideFt / rowSpacingFt;
  const plantsPerRow = sideFt / plantSpacingFt;
  const population = rows * plantsPerRow;

  const totalGrams = population * rootWeightG;
  const grossTons = totalGrams / GRAMS_PER_METRIC_TON;
  const netTons = grossTons * (1 - FIELD_LOSS_FACTOR);

  // One decimal place is the resolution the task asks for.
  return Math.round(netTons * 10) / 10;
}

// Turns a field spec into a one-line agronomy report for the console driver.
function describeField(name, field) {
  const [acres, rowSpacingIn, plantSpacingIn, rootWeightG] = field;
  const tons = yield(field);
  const perAcre = Math.round((tons / acres) * 10) / 10;
  return `${name}: ${acres} ac, ${rowSpacingIn}" rows, ${plantSpacingIn}" plants, ` +
    `${rootWeightG} g roots -> ${tons.toFixed(1)} t (${perAcre.toFixed(1)} t/ac)`;
}

function main() {
  const trials = [
    ['North quarter', [40, 22, 6, 850]],
    ['Creek bottom', [12.5, 30, 8, 1100]],
    ['Home block', [160, 20, 5, 700]],
  ];

  trials.forEach(([name, field]) => console.log(describeField(name, field)));

  // Total tonnage across the whole operation, for contract planning.
  const fleetTotal = trials.reduce((sum, [, field]) => sum + yield(field), 0);
  console.log(`Estimated delivery: ${(Math.round(fleetTotal * 10) / 10).toFixed(1)} t`);

  // Bad agronomy data should surface loudly rather than produce a plausible number.
  try {
    yield([10, 22, 0, 850]);
  } catch (err) {
    console.log(`Rejected: ${err.message}`);
  }
}

main();

