function range(specs) {
  // Destructure the five-element spec array into named quantities
  const [capacityMah, voltage, cruiseAmps, speedMps, headwindMps] = specs;

  // Energy stored on board: mAh * V / 1000 gives watt hours
  const wattHours = (capacityMah * voltage) / 1000;

  // Power actually burned while cruising, in watts
  const cruisePower = cruiseAmps * voltage;

  // Endurance in hours, then the same figure in seconds for distance math
  const flightHours = wattHours / cruisePower;
  const flightSeconds = flightHours * 3600;

  // A headwind directly erodes the ground speed the drone achieves
  const groundSpeed = speedMps - headwindMps;

  // Zero or reversed ground speed means no forward progress at all
  if (groundSpeed <= 0) {
    return 0;
  }

  const rangeMeters = groundSpeed * flightSeconds;

  // Keep 10% of the range in reserve so the drone can land safely
  const rangeKm = rangeMeters / 1000;
  return rangeKm * 0.9;
}

function validateSpecs(specs) {
  if (!Array.isArray(specs) || specs.length !== 5) {
    throw new TypeError('specs must be an array of exactly five numbers');
  }
  for (const value of specs) {
    // Reject strings, NaN and Infinity before they poison the arithmetic
    if (typeof value !== 'number' || !Number.isFinite(value)) {
      throw new TypeError('every spec entry must be a finite number');
    }
  }
  const [capacityMah, voltage, cruiseAmps] = specs;
  // Division by zero current or voltage would yield an infinite endurance
  if (capacityMah <= 0 || voltage <= 0 || cruiseAmps <= 0) {
    throw new RangeError('capacity, voltage and cruise draw must be positive');
  }
  return specs;
}

function describeRange(name, specs) {
  validateSpecs(specs);
  const km = range(specs);
  // A zero result is reported as grounded rather than as a 0.00 km flight
  if (km === 0) {
    return `${name}: grounded (headwind cancels cruise speed)`;
  }
