const SENSITIVITY_DBM = -90; // receiver hardware threshold in dB

// Free space path loss: 20*log10(d_km) + 20*log10(f_MHz) + 32.44
function freeSpacePathLoss(distanceKm, frequencyMhz) {
  if (!(distanceKm > 0) || !(frequencyMhz > 0)) {
    // log10 is undefined at zero, so a degenerate link has no meaningful loss
    throw new RangeError('distance and frequency must be positive');
  }
  return 20 * Math.log10(distanceKm) + 20 * Math.log10(frequencyMhz) + 32.44;
}

// Effective isotropic radiated power is the transmitter output plus its antenna gain
function effectiveIsotropicRadiatedPower(txPowerDb, txGainDb) {
  return txPowerDb + txGainDb;
}

function budget(link) {
  if (!Array.isArray(link) || link.length !== 5) {
    // the formula needs exactly power, frequency, distance and both gains
    throw new TypeError('link must be an array of five numbers');
  }
  const values = link.map(Number);
  if (!values.every(Number.isFinite)) {
    throw new TypeError('link values must be finite numbers');
  }
  const [txPowerDb, frequencyMhz, distanceKm, txGainDb, rxGainDb] = values;
  const pathLoss = freeSpacePathLoss(distanceKm, frequencyMhz);
  const eirp = effectiveIsotropicRadiatedPower(txPowerDb, txGainDb);
  // attenuation over the atmospheric distance
  const attenuated = eirp - pathLoss;
  const receivedPower = attenuated + rxGainDb;
  let failed = false;
  if (receivedPower < SENSITIVITY_DBM) {
    // the radio cannot demodulate anything weaker than its sensitivity
    failed = true;
  }
  const fadeMargin = receivedPower - SENSITIVITY_DBM;
  return [receivedPower, fadeMargin, failed];
}

// Human readable one-line summary of a computed budget
function describe(name, link) {
  const [receivedPower, fadeMargin, failed] = budget(link);
  const status = failed ? 'LINK DOWN' : 'LINK UP';
  return `${name}: Rx ${receivedPower.toFixed(2)} dB, margin ${fadeMargin.toFixed(2)} dB — ${status}`;
}

function main() {
  const links = [
    // short 2.4 GHz Wi-Fi hop with modest dish gains
    ['Wi-Fi hop', [20, 2400, 1, 6, 6]],
    // 5.8 GHz backhaul across a valley
    ['Backhaul', [30, 5800, 25, 23, 23]],
    // deep space style link where the loss swamps the antennas
    ['Deep space', [10, 8400, 400000, 40, 60]],
    ['Broken', [20, 2400, 0, 6, 6]],
  ];
  for (const [name, link] of links) {
    try {
      console.log(describe(name, link));
    } catch (err) {
      // a malformed descriptor should report the problem rather than abort the report
      console.log(`${name}: ${err.message}`);
    }
  }
}

main();

module.exports = { budget, freeSpacePathLoss, effectiveIsotropicRadiatedPower, describe };

