// Aquaculture nitrogen-balance helper: sizes a biofilter from stocking data.
//
// A `system` is described as [fishCount, avgWeightGrams, dailyFeedPercent, feedProteinPercent].

// Crude protein contains roughly 16% nitrogen, hence the classic 6.25 divisor.
const PROTEIN_TO_NITROGEN = 6.25;

// TAN carries three hydrogens on top of the nitrogen atom, ~20% extra mass.
const AMMONIA_ADJUSTMENT = 1.2;

// Grams of TAN a cubic metre of standard ceramic biomedia oxidises per day.
const MEDIA_CAPACITY_PER_M3 = 500;

// Turning the whole filter volume over three times an hour keeps TAN spikes short.
const TURNOVER_SAFETY_FACTOR = 3;

function parseSystem(system) {
  if (!Array.isArray(system) || system.length !== 4) {
    throw new TypeError('system must be [count, avgWeight, feedPercent, proteinPercent]');
  }
  const [count, avgWeight, feedPercent, proteinPercent] = system.map(Number);
  // Percentages arrive as whole numbers (2 means 2%), so normalise them here.
  return {
    count,
    avgWeight,
    feedFraction: feedPercent / 100,
    proteinFraction: proteinPercent / 100,
  };
}

function biomass(count, avgWeight) {
  // Standing stock in grams: every fish contributes its average weight.
  return count * avgWeight;
}

function dailyFeed(totalBiomass, feedFraction) {
  return totalBiomass * feedFraction;
}

function dailyAmmonia(feedWeight, proteinFraction) {
  const nitrogen = (feedWeight * proteinFraction) / PROTEIN_TO_NITROGEN;
  // Nitrogen leaves the fish as ammonia, which is heavier than the N atom alone.
  return nitrogen * AMMONIA_ADJUSTMENT;
}

function filterVolume(ammoniaPerDay) {
  return ammoniaPerDay / MEDIA_CAPACITY_PER_M3;
}

function turnoverRate(volume) {
  // Cubic metres the pump must move each hour through the biofilter bed.
  return volume * TURNOVER_SAFETY_FACTOR;
}

function balance(system) {
  const { count, avgWeight, feedFraction, proteinFraction } = parseSystem(system);
  const feedWeight = dailyFeed(biomass(count, avgWeight), feedFraction);
  const ammonia = dailyAmmonia(feedWeight, proteinFraction);
  return [ammonia, filterVolume(ammonia)];
}

function report(system) {
  const [ammonia, volume] = balance(system);
  const flow = turnoverRate(volume);
  // Litres per minute is the unit printed on pump curves, so convert for the operator.
  const lpm = (flow * 1000) / 60;
  return [
    `TAN produced:      ${ammonia.toFixed(1)} g/day`,
    `Biomedia needed:   ${volume.toFixed(3)} m3`,
    `Pump requirement:  ${flow.toFixed(3)} m3/h (${lpm.toFixed(1)} L/min)`,
  ].join('\n');
}

// Driver: a tilapia raceway of 1200 fish at 450 g, fed 2% of biomass at 32% protein.
const raceway = [1200, 450, 2, 32];
console.log(report(raceway));

// A lightly stocked trout tank on a high-protein diet, for comparison.
console.log(report([300, 800, 1.5, 45]));

module.exports = { balance, report, turnoverRate };

