// Ideal storage conditions for each supported cheese type.
// Brie has no upper humidity limit and needs humidity strictly above 90%.
const IDEAL = {
  brie: { tempMin: 11, tempMax: 13, humMin: 90, humMinExclusive: true, humMax: Infinity },
  cheddar: { tempMin: 10, tempMax: 12, humMin: 80, humMax: 85 },
  gouda: { tempMin: 10, tempMax: 16, humMin: 75, humMax: 80 },
};

// A reading is usable only if the cheese is known and both measurements are numbers.
function parseReading(reading) {
  if (!Array.isArray(reading) || reading.length < 3) return null;
  const [rawType, temp, humidity] = reading;
  if (typeof rawType !== 'string') return null;
  // Sensors report the label with inconsistent casing and padding.
  const type = rawType.trim().toLowerCase();
  if (!Object.prototype.hasOwnProperty.call(IDEAL, type)) return null;
  if (!Number.isFinite(temp) || !Number.isFinite(humidity)) return null;
  return { type, temp, humidity };
}

// Humidity floors are inclusive except for brie, which must exceed its floor.
function humidityInRange(humidity, spec) {
  if (spec.humMinExclusive) return humidity > spec.humMin && humidity <= spec.humMax;
  return humidity >= spec.humMin && humidity <= spec.humMax;
}

// Counts how many of the two parameters fall outside the ideal window.
function countViolations({ type, temp, humidity }) {
  const spec = IDEAL[type];
  let violations = 0;
  // Temperature bounds are inclusive, so exactly 13 degrees still suits brie.
  if (temp < spec.tempMin || temp > spec.tempMax) violations += 1;
  if (!humidityInRange(humidity, spec)) violations += 1;
  return violations;
}

function monitor(readings) {
  let evaluated = 0;
  let critical = 0;
  let minor = 0;
  for (const reading of readings || []) {
    const parsed = parseReading(reading);
    // Unrecognised or malformed rows never reach the tally at all.
    if (parsed === null) continue;
    evaluated += 1;
    const violations = countViolations(parsed);
    if (violations === 2) {
      critical += 1;
    } else if (violations === 1) {
      minor += 1;
    }
  }
  return [evaluated, critical, minor];
}

// Turns the raw tally into a line a cave keeper can read at a glance.
function formatReport([evaluated, critical, minor]) {
  const healthy = evaluated - critical - minor;
  return `${evaluated} cheeses checked: ${healthy} ideal, ${minor} minor, ${critical} critical`;
}

function main() {
  const readings = [
    ['brie', 12, 92],
    ['Cheddar', 15, 90],
    ['gouda', 11, 82],
    ['gouda', 20, 60],
    ['stilton', 12, 85],
    ['brie', 13, 90],
  ];
  const tally = monitor(readings);
  console.log(formatReport(tally));
  // The critical count is what triggers a visit to the cave.
  if (tally[1] > 0) {
    console.log(`Attention needed: ${tally[1]} wheel(s) in danger.`);
  }
}

main();

module.exports = { monitor, formatReport };

