const BREATHING_RATE = 20; // average surface air consumption in liters per minute
const FILL_PRESSURE = 200; // cylinders are assumed filled to 200 bar
const RESERVE_BAR = 50;

// depth is converted to atmospheres: ten meters of water add one atmosphere
function ambientPressure(depth) {
  return depth / 10 + 1;
}

// the diver breathes the same volume per minute, compressed by the ambient pressure
function gasConsumed(depth, time) {
  return ambientPressure(depth) * time * BREATHING_RATE;
}

function remainingBar(depth, time, cylinder) {
  const startVolume = cylinder * FILL_PRESSURE;
  const leftVolume = startVolume - gasConsumed(depth, time);
  // dividing the free volume by the cylinder size gives the gauge reading again
  return leftVolume / cylinder;
}

function validateDive(dive, index) {
  if (!Array.isArray(dive) || dive.length !== 3) {
    throw new TypeError(`dive ${index} must be [depth, time, cylinder]`);
  }
  const [depth, time, cylinder] = dive;
  if (![depth, time, cylinder].every(Number.isFinite)) {
    throw new TypeError(`dive ${index} contains a non-numeric value`);
  }
  // a cylinder of zero liters would make the bar conversion divide by zero
  if (cylinder <= 0) {
    throw new RangeError(`dive ${index} has an unusable cylinder size`);
  }
  if (depth < 0 || time < 0) {
    throw new RangeError(`dive ${index} has a negative depth or time`);
  }
  return [depth, time, cylinder];
}

function track(dives) {
  let lowest = Infinity;
  let violations = 0;
  dives.forEach((dive, index) => {
    const [depth, time, cylinder] = validateDive(dive, index);
    const left = remainingBar(depth, time, cylinder);
    if (left < lowest) {
      lowest = left;
    }
    // anything under the reserve means the diver surfaced without a safety margin
    if (left < RESERVE_BAR) {
      violations += 1;
    }
  });
  // an empty log has no pressures at all, so report a neutral zero
  return [dives.length === 0 ? 0 : lowest, violations];
}

function formatReport(dives) {
  const [lowest, violations] = track(dives);
  const lines = dives.map((dive, index) => {
    const [depth, time, cylinder] = validateDive(dive, index);
    const left = remainingBar(depth, time, cylinder);
    const flag = left < RESERVE_BAR ? 'RESERVE VIOLATION' : 'ok';
    return `${depth}m/${time}min/${cylinder}L -> ${left.toFixed(1)} bar (${flag})`;
  });
  // the summary repeats the tracked figures so the log can be read on its own
  lines.push(`lowest: ${lowest.toFixed(1)} bar, violations: ${violations}`);
  return lines.join('\n');
}

const log = [
  [20, 45, 12],
  [18, 40, 15],
  [30, 25, 12],
];

console.log(formatReport(log));
// the single dive from the task statement runs out of gas before the end
console.log(track([[20, 45, 12]]));

module.exports = { track, ambientPressure, gasConsumed, remainingBar, formatReport };

