// Whitewater classification for a sequence of river sections.
// Each section is [flowRate (m^3/s), gradientDrop (m/km), rocks (0 or 1)].

const MAX_CLASS = 6; // international scale tops out at class VI

function parseSection(section, index) {
  if (!Array.isArray(section) || section.length < 3) {
    throw new TypeError(`section ${index} must be [flow, drop, rocks]`);
  }
  const [flow, drop, rocks] = section.map(Number);
  // a NaN anywhere would silently poison the steepness sum, so reject it up front
  if ([flow, drop, rocks].some(Number.isNaN)) {
    throw new TypeError(`section ${index} contains a non-numeric value`);
  }
  return { flow, drop, rocks: rocks ? 1 : 0 };
}

function baseClass({ flow, drop }) {
  // strongest condition first: heavy flow *and* a steep drop is class three
  if (flow > 100 && drop > 10) {
    return 3;
  }
  // either a moderate flow band or a moderate drop band is enough for class two
  if ((flow >= 50 && flow <= 100) || (drop >= 5 && drop <= 10)) {
    return 2;
  }
  return 1; // gentle water: low flow, shallow gradient
}

function classify(section) {
  const parsed = section;
  let level = baseClass(parsed);
  if (parsed.rocks === 1) {
    level += 1; // exposed rocks make the line harder by one full grade
  }
  return Math.min(level, MAX_CLASS);
}

function navigate(rapids) {
  if (!Array.isArray(rapids)) {
    throw new TypeError('navigate expects an array of river sections');
  }

  let maxClass = 0;
  let steepness = 0;
  let challenging = 0;

  rapids.forEach((raw, index) => {
    const section = parseSection(raw, index);
    const level = classify(section);

    if (level > maxClass) {
      maxClass = level;
    }
    steepness += section.drop; // overall river steepness is the sum of all drops
    if (level >= 3) {
      challenging += 1; // class three and above counts as a challenging section
    }
  });

  return [maxClass, steepness, challenging];
}

function report(rapids) {
  const [maxClass, steepness, challenging] = navigate(rapids);
  // round the total so floating point drops like 3.1 + 4.2 read cleanly
  const total = Math.round(steepness * 100) / 100;
  return `max class ${maxClass}, steepness ${total} m/km, ${challenging} challenging section(s)`;
}

const river = [
  [120, 12, 1],
  [40, 3, 0],
  [75, 6, 1],
  [30, 4, 1],
];

console.log(navigate([[120, 12, 1]])); // [4, 12, 1]
console.log(navigate(river));
console.log(report(river));

module.exports = { navigate, classify, report };

