const TARGET_SUGAR_PERCENT = 66;
const LITERS_PER_CORD = 1000;

// A batch is only usable if both fields are finite numbers in a sane range
function validateBatch(batch, index) {
  if (!Array.isArray(batch) || batch.length < 2) {
    throw new TypeError(`batch ${index} must be an array of [liters, percent]`);
  }
  const [liters, percent] = batch;
  if (!Number.isFinite(liters) || liters < 0) {
    throw new RangeError(`batch ${index}: sap volume must be a non-negative number`);
  }
  // sap sweeter than the target would already be syrup, so cap the input there
  if (!Number.isFinite(percent) || percent <= 0 || percent > TARGET_SUGAR_PERCENT) {
    throw new RangeError(`batch ${index}: sugar content must be between 0 and ${TARGET_SUGAR_PERCENT}`);
  }
  return { liters, percent };
}

// Boiling concentrates the sugar: volume shrinks by the ratio of the percentages
function boilDown(liters, percent) {
  const syrup = (liters * percent) / TARGET_SUGAR_PERCENT;
  return { syrup, water: liters - syrup };
}

function round(value, places) {
  const factor = 10 ** places;
  return Math.round(value * factor) / factor;
}

function evaporate(sap) {
  if (!Array.isArray(sap)) {
    throw new TypeError('evaporate expects an array of batches');
  }
  let totalSyrup = 0;
  let totalWater = 0;
  for (let i = 0; i < sap.length; i += 1) {
    const { liters, percent } = validateBatch(sap[i], i);
    const { syrup, water } = boilDown(liters, percent);
    // running totals across every batch of the season
    totalSyrup += syrup;
    totalWater += water;
  }
  // one cord of wood drives off a thousand liters of water
  const cords = totalWater / LITERS_PER_CORD;
  return [round(totalSyrup, 1), round(totalWater, 1), round(cords, 2)];
}

// Turn the numeric result into the line a sugarhouse operator actually reads
function describeSeason(sap) {
  const [syrup, water, cords] = evaporate(sap);
  const batches = sap.length === 1 ? '1 batch' : `${sap.length} batches`;
  return `${batches}: ${syrup} L syrup, ${water} L water boiled off, ${cords} cords of wood`;
}

function main() {
  const season = [
    [100, 2],
    [250, 2.5],
    [80, 1.8],
  ];
  // each batch on its own, so a bad reading is easy to spot in the log
  for (const batch of season) {
    console.log(describeSeason([batch]));
  }
  console.log(describeSeason(season));
  try {
    // a mis-typed hydrometer reading of 660% must not silently inflate the yield
    evaporate([[100, 660]]);
  } catch (err) {
    console.error(`rejected: ${err.message}`);
  }
}

main();

module.exports = { evaporate, describeSeason, boilDown, validateBatch };

