// Naismith-rule route planner for multi-stage mountain itineraries.

// Terrain multipliers applied to the Naismith base time.
const TERRAIN_FACTORS = {
  trail: 1.0,
  scree: 1.2,
  glacier: 1.3,
};

// Roping up on a glacier costs a flat half hour per stage.
const GLACIER_SETUP_HOURS = 0.5;

function naismithBase(distanceKm, ascentM) {
  // One hour per 5 km walked, plus one hour per 600 m climbed.
  return distanceKm / 5 + ascentM / 600;
}

function validateStage(stage, index) {
  if (!Array.isArray(stage) || stage.length !== 3) {
    throw new TypeError(`Stage ${index} must be [distanceKm, ascentM, terrain]`);
  }
  const [distanceKm, ascentM, terrain] = stage;
  // Negative or non-numeric legs would silently corrupt the totals.
  if (typeof distanceKm !== 'number' || distanceKm < 0) {
    throw new RangeError(`Stage ${index} has an invalid distance: ${distanceKm}`);
  }
  if (typeof ascentM !== 'number' || ascentM < 0) {
    throw new RangeError(`Stage ${index} has an invalid ascent: ${ascentM}`);
  }
  if (!Object.prototype.hasOwnProperty.call(TERRAIN_FACTORS, terrain)) {
    throw new RangeError(`Stage ${index} has an unknown terrain: ${terrain}`);
  }
  return { distanceKm, ascentM, terrain };
}

function stageTime(distanceKm, ascentM, terrain) {
  let hours = naismithBase(distanceKm, ascentM) * TERRAIN_FACTORS[terrain];
  if (terrain === 'glacier') {
    // Rope, harness and crevasse-rescue setup before stepping onto the ice.
    hours += GLACIER_SETUP_HOURS;
  }
  return hours;
}

function calculate(stages) {
  let totalHours = 0;
  let totalAscent = 0;
  stages.forEach((stage, index) => {
    const { distanceKm, ascentM, terrain } = validateStage(stage, index);
    totalHours += stageTime(distanceKm, ascentM, terrain);
    totalAscent += ascentM;
  });
  // Anything longer than a twelve-hour day needs a bivouac or hut booking.
  const overnight = totalHours > 12;
  return [Math.round(totalHours * 10) / 10, totalAscent, overnight];
}

function formatReport(stages) {
  const [hours, ascent, overnight] = calculate(stages);
  const whole = Math.floor(hours);
  // Show the fractional hour as minutes so the summary reads like a timetable.
  const minutes = Math.round((hours - whole) * 60);
  const plan = overnight ? 'overnight trip' : 'single day';
  return `${hours} h (${whole}h${String(minutes).padStart(2, '0')}), ` +
    `${ascent} m ascent, ${plan}`;
}

const dayHike = [[10, 1200, 'trail']];
const traverse = [
  [12, 900, 'trail'],
  [4, 700, 'scree'],
  [6, 1100, 'glacier'],
  [9, 300, 'trail'],
];

console.log(formatReport(dayHike));
console.log(formatReport(traverse));
// Raw tuples are what downstream tooling consumes.
console.log(calculate(traverse));

