const BASE_LENGTHS = {
  shirt: 40,
  dress: 60,
  pants: 50
};

// Patterns are drafted for 54 inch bolts; anything else needs a correction factor
const STANDARD_WIDTH = 54;
const STANDARD_HEIGHT = 65;
const INCHES_PER_YARD = 36;

function baseLength(type) {
  const key = String(type).trim().toLowerCase();
  const base = BASE_LENGTHS[key];
  if (base === undefined) {
    // An unknown pattern type has no draft to scale, so refuse rather than guess
    throw new Error(`Unknown pattern type: ${type}`);
  }
  return base;
}

function heightAdjustment(height) {
  if (height > STANDARD_HEIGHT) {
    // Taller wearers need two extra inches of length per inch of height
    return (height - STANDARD_HEIGHT) * 2;
  }
  // Shorter wearers only save one inch per inch, since hems still need allowance
  return -(STANDARD_HEIGHT - height);
}

function widthFactor(width) {
  if (width < STANDARD_WIDTH) {
    // Narrow fabric forces panels to be pieced, costing half again as much length
    return 1.5;
  }
  if (width > STANDARD_WIDTH) {
    return 0.9;
  }
  return 1;
}

function garmentLength(garment) {
  const [type, height, width] = garment;
  if (!(height > 0) || !(width > 0)) {
    throw new Error(`Height and width must be positive for ${type}`);
  }
  const adjusted = baseLength(type) + heightAdjustment(height);
  return adjusted * widthFactor(width);
}

function estimate(patterns) {
  const totalInches = patterns.reduce((sum, garment) => sum + garmentLength(garment), 0);
  // Fabric is sold by the whole yard, so always round up
  return Math.ceil(totalInches / INCHES_PER_YARD);
}

