//
// Trace width calculator (IPC-2221 style): given current, allowable temperature
// rise and copper thickness, report the internal and external trace widths.
//

const INTERNAL_CONSTANT = 0.048;
const EXTERNAL_CONSTANT = 0.064;
const MIN_TEMP_RISE = 10;
const MIN_THICKNESS = 0.5;

// Cross sectional area in square mils for a given layer constant.
function crossSection(current, tempRise, constant) {
  const scaled = Math.pow(current * (1 / constant), 1 / 0.44);
  return scaled / Math.pow(tempRise, 0.44);
}

// A copper "ounce" is 1.378 mils of thickness, so area / thickness gives width.
function areaToWidth(area, thickness) {
  return area / (thickness * 1.378);
}

function trace(parameters) {
  const [current, tempRiseInput, thickness] = parameters;

  // Zero current needs no copper at all.
  if (current === 0) {
    return [0, 0];
  }

  // Thinner foil than half an ounce is outside the model's validity.
  if (thickness < MIN_THICKNESS) {
    return 'Error: copper thickness must be at least 0.5 oz';
  }

  // Clamp unrealistically small temperature rises upward for safety margin.
  const tempRise = tempRiseInput < MIN_TEMP_RISE ? MIN_TEMP_RISE : tempRiseInput;

  const internalWidth = areaToWidth(
    crossSection(current, tempRise, INTERNAL_CONSTANT),
    thickness
  );
  const externalWidth = areaToWidth(
    crossSection(current, tempRise, EXTERNAL_CONSTANT),
    thickness
  );

  return [internalWidth, externalWidth];
}

// Turn a trace() result into one human readable line.
function describe(parameters, result) {
  const [current, tempRise, thickness] = parameters;
  const header = `${current} A, +${tempRise} C, ${thickness} oz -> `;

  // An error result arrives as a plain string instead of a pair of widths.
  if (typeof result === 'string') {
    return header + result;
  }

  const [internal, external] = result;
  return `${header}internal ${internal.toFixed(2)} mils, external ${external.toFixed(2)} mils`;
}

function main() {
  const cases = [
    [0, 10, 1],
    [5, 10, 1],
    [10, 45, 2],
    [2.5, 5, 0.5],
    [3, 20, 0.25],
  ];

  // The 5 C case is silently promoted to 10 C by trace() before computing.
  for (const parameters of cases) {
    console.log(describe(parameters, trace(parameters)));
  }
}

main();

module.exports = { trace, crossSection, areaToWidth, describe };

