// Shoe size conversion utilities: centimetre foot length -> global standards.

// The mondopoint scale is expressed in millimetres, quantised to 5 mm steps.
const MONDOPOINT_STEP = 5;

// Continental sizes advance in half-size increments.
const HALF_SIZE = 0.5;

// Conversion constant used by the european (Paris point) approximation.
const PARIS_POINT_CM = 0.667;

// Inches per centimetre denominator for the british scale.
const CM_PER_INCH = 2.54;

function roundTo(value, step) {
  // Snap to the closest multiple of step, keeping the result free of float dust.
  return Math.round(value / step) * step;
}

function shoes(length) {
  // Measurements outside 10..40 cm are not real adult/child foot lengths.
  if (typeof length !== 'number' || Number.isNaN(length)) return [];
  if (length < 10 || length > 40) return [];

  const mondopoint = roundTo(length * 10, MONDOPOINT_STEP);
  const european = roundTo(length / PARIS_POINT_CM + 1.5, HALF_SIZE);

  // British sizing works in barleycorns: three per centimetre, offset by 25.
  let uk = roundTo((length * 3) / CM_PER_INCH - 25, HALF_SIZE);

  // Very short feet drive the formula below the bottom of the UK scale.
  if (uk < 0) uk = 0;

  const usMen = uk + 1;
  const usWomen = uk + 2;
  return [mondopoint, european, uk, usMen, usWomen];
}

function formatSizes(sizes) {
  // An empty list means the input was rejected as an invalid measurement.
  if (sizes.length === 0) return 'invalid measurement';

  const [mondopoint, european, uk, usMen, usWomen] = sizes;
  const labels = [
    `MP ${mondopoint}`,
    `EU ${european}`,
    `UK ${uk}`,
    `US-M ${usMen}`,
    `US-W ${usWomen}`
  ];
  return labels.join(' | ');
}

function report(lengths) {
  // Build one aligned line per requested foot length.
  return lengths.map((length) => {
    const label = `${length.toFixed(1)} cm`.padStart(8);
    return `${label}  ${formatSizes(shoes(length))}`;
  });
}

function main() {
  // A spread of lengths: too small, child, adult, oversized.
  const samples = [9.5, 15, 22.3, 25, 27.8, 30, 41];
  report(samples).forEach((line) => console.log(line));
}

main();

module.exports = { shoes, formatSizes, report };

