// Optical depth-of-field calculator.
// A settings list is [focalLengthMm, apertureFNumber, subjectDistanceM, circleOfConfusionMm].

// Round to one decimal place, the precision used for the published results.
function roundTenth(value) {
  return Math.round(value * 10) / 10;
}

function validateSettings(settings) {
  if (!Array.isArray(settings) || settings.length !== 4) {
    throw new TypeError('settings must be a list of four numbers');
  }
  const [focal, aperture, subject, coc] = settings;
  // Every entry has to be a real number before any division happens.
  for (const value of settings) {
    if (typeof value !== 'number' || !Number.isFinite(value)) {
      throw new TypeError('settings must contain finite numbers');
    }
  }
  // The hyperfocal formula divides by aperture and circle of confusion, so neither may be zero.
  if (focal <= 0 || aperture <= 0 || coc <= 0 || subject <= 0) {
    throw new RangeError('focal length, aperture, distance and CoC must be positive');
  }
  return { focal, aperture, subject, coc };
}

function focus(settings) {
  const { focal, aperture, subject, coc } = validateSettings(settings);

  // Hyperfocal distance in metres: the 1000 converts millimetres to metres.
  const hyperfocal = (focal * focal) / (aperture * coc * 1000);

  // The focal length also enters the limits in metres rather than millimetres.
  const focalM = focal / 1000;
  const product = hyperfocal * subject;

  const near = product / (hyperfocal + subject - focalM);

  // A non-positive denominator means the far limit lies beyond infinity.
  const farDenominator = hyperfocal - subject + focalM;
  const far = farDenominator > 0 ? product / farDenominator : -1;

  return [roundTenth(hyperfocal), roundTenth(near), far === -1 ? -1 : roundTenth(far)];
}

// Turn one result triple into a readable report line.
function describe(settings, [hyperfocal, near, far]) {
  const [focal, aperture, subject] = settings;
  const lens = `${focal}mm f/${aperture} at ${subject}m`;
  // -1 is the sentinel for "everything past the near limit is sharp".
  const farText = far === -1 ? 'infinity' : `${far}m`;
  return `${lens}: hyperfocal ${hyperfocal}m, sharp from ${near}m to ${farText}`;
}

function report(configurations) {
  return configurations.map((settings) => describe(settings, focus(settings)));
}

function main() {
  const configurations = [
    [50, 8, 5, 0.03],
    [50, 8, 15, 0.03],
    [200, 2.8, 12, 0.019],
    [24, 11, 3, 0.03],
  ];
  // The second configuration focuses past the hyperfocal distance, giving an infinite far limit.
  for (const line of report(configurations)) {
    console.log(line);
  }
}

main();

module.exports = { focus, report, describe };

