// Kayak paddle sizing helper: converts paddler measurements into a recommended
// paddle length in centimetres.

const YOUTH_HEIGHT_CUTOFF = 48;
const YOUTH_PADDLE_LENGTH = 150;
const BASE_PADDLE_LENGTH = 200;

// Style names are normalised so that "High Angle", "high-angle" and "high angle"
// all map onto the same adjustment.
function normalizeStyle(style) {
  return String(style).trim().toLowerCase().replace(/[-_]+/g, ' ');
}

function styleAdjustment(style) {
  const normalized = normalizeStyle(style);
  if (normalized === 'high angle') {
    // A vertical stroke needs a shorter shaft.
    return -5;
  }
  if (normalized === 'low angle') {
    // A relaxed, horizontal stroke needs extra reach.
    return 5;
  }
  return 0;
}

function paddle(paddler) {
  const [height, boatWidth, style] = paddler;

  // Youth paddlers get a fixed size, ignoring boat width and style entirely.
  if (height < YOUTH_HEIGHT_CUTOFF) {
    return YOUTH_PADDLE_LENGTH;
  }

  let length = BASE_PADDLE_LENGTH;

  // Only full inches strictly above the thresholds count, hence Math.floor.
  const heightOver = Math.max(0, Math.floor(height - 60));
  const widthOver = Math.max(0, Math.floor(boatWidth - 24));

  length += heightOver;
  length += widthOver * 2;
  length += styleAdjustment(style);

  // Very wide hulls (pack canoes, fishing rigs) force the paddler to reach out.
  if (boatWidth > 36) {
    length += 10;
  }

  return length;
}

// Human-readable summary for a single fitting, used by the report below.
function describeFit(paddler) {
  const [height, boatWidth, style] = paddler;
  const feet = Math.floor(height / 12);
  const inches = height % 12;
  const recommendation = paddle(paddler);
  return `${feet}'${inches}" paddler, ${boatWidth}" beam, ${normalizeStyle(style)}: ${recommendation} cm`;
}

function fittingReport(paddlers) {
  return paddlers.map(describeFit).join('\n');
}

const clinic = [
  [44, 26, 'low angle'],
  [60, 24, 'high angle'],
  [72, 30, 'low angle'],
  [68, 40, 'high angle'],
  [65, 28, 'touring'],
];

console.log(fittingReport(clinic));

