// Coffee brewing analysis: extraction yield and quality classification.

const IDEAL_MIN = 18;
const IDEAL_MAX = 22;

// A refractometer reports TDS as a percentage, so it must stay within 0..100.
function validateBrew(brew) {
  if (!Array.isArray(brew) || brew.length < 3) {
    return 'invalid brew: expected [dryGrams, liquidGrams, tdsPercent]';
  }
  const [dry, liquid, tds] = brew;
  if (![dry, liquid, tds].every((n) => typeof n === 'number' && Number.isFinite(n))) {
    return 'invalid brew: all values must be finite numbers';
  }
  // Zero dry coffee would make the yield division meaningless.
  if (dry <= 0) {
    return 'invalid brew: dry coffee weight must be positive';
  }
  if (tds < 0 || tds > 100) {
    return 'invalid brew: TDS percentage out of range';
  }
  return null;
}

function classifyYield(yieldPercent) {
  if (yieldPercent < IDEAL_MIN) {
    return 'under-extracted';
  }
  // Strictly above the upper bound tastes bitter; the bound itself is still ideal.
  if (yieldPercent > IDEAL_MAX) {
    return 'over-extracted';
  }
  return 'ideally extracted';
}

function extraction(brew) {
  const problem = validateBrew(brew);
  if (problem) {
    return problem;
  }
  const [dry, liquid, tds] = brew;
  // Liquid lighter than the dose cannot happen: water only adds mass.
  if (liquid < dry) {
    return 'error: brewed liquid weight cannot be less than dry coffee weight';
  }
  if (tds === 0) {
    return [0, 'unextracted'];
  }
  const dissolvedMass = (liquid * tds) / 100;
  const yieldPercent = (dissolvedMass / dry) * 100;
  return [yieldPercent, classifyYield(yieldPercent)];
}

// Turn either return shape (error string or [yield, quality]) into one report line.
function describe(brew) {
  const result = extraction(brew);
  if (typeof result === 'string') {
    return result;
  }
  const [yieldPercent, quality] = result;
  return `${yieldPercent.toFixed(2)}% yield -> ${quality}`;
}

function main() {
  const brews = [
    [18, 288, 1.35],
    [20, 320, 1.0],
    [15, 250, 1.6],
    [22, 20, 1.4],
    [17, 270, 0],
  ];
  // The driver prints one line per brew so batches can be compared at a glance.
  for (const brew of brews) {
    console.log(`${brew.join('g / ')}: ${describe(brew)}`);
  }
}

main();

module.exports = { extraction, classifyYield, describe };

