const RAD_PER_DEG = Math.PI / 180;

// Angles arrive in degrees but every trigonometric call below needs radians.
function toRadians(degrees) {
  return degrees * RAD_PER_DEG;
}

function toDegrees(radians) {
  return radians / RAD_PER_DEG;
}

// The three values must be numbers inside the usual geographic ranges.
function validateLocation(location) {
  if (!Array.isArray(location) || location.length !== 3) {
    throw new TypeError('location must be [satelliteLongitude, receiverLatitude, receiverLongitude]');
  }
  const [satLon, recvLat, recvLon] = location;
  if (![satLon, recvLat, recvLon].every(Number.isFinite)) {
    throw new TypeError('location must contain finite numbers');
  }
  if (Math.abs(recvLat) > 90) {
    throw new RangeError('receiver latitude must lie between -90 and 90 degrees');
  }
  if (Math.abs(satLon) > 180 || Math.abs(recvLon) > 180) {
    throw new RangeError('longitudes must lie between -180 and 180 degrees');
  }
}

// A raw subtraction can exceed half a turn, so fold it back into (-180, 180].
function longitudeDifference(satLon, recvLon) {
  let diff = (satLon - recvLon) % 360;
  if (diff > 180) {
    diff -= 360;
  } else if (diff <= -180) {
    diff += 360;
  }
  return diff;
}

function pointing(location) {
  validateLocation(location);
  const [satLon, recvLat, recvLon] = location;
  const diffDeg = longitudeDifference(satLon, recvLon);
  const diff = toRadians(diffDeg);
  const lat = toRadians(recvLat);

  // On the equator cos(latitude) is 1, so elevation depends on the longitude difference alone.
  const elevationRad = recvLat === 0
    ? Math.acos(Math.cos(diff))
    : Math.acos(Math.cos(lat) * Math.cos(diff));

  // Directly overhead on the equator the arctangent argument is 0/0 and the heading is undefined.
  const azimuthRad = recvLat === 0 && diffDeg === 0
    ? 0
    : Math.atan(Math.tan(diff) / Math.sin(lat));

  const elevation = toDegrees(elevationRad);
  let azimuth = toDegrees(azimuthRad);

  // Northern receivers look south, so the heading is measured from due south.
  if (recvLat > 0) {
    azimuth = 180 - azimuth;
  }

  // A negative elevation puts the satellite under the horizon: no line of sight.
  if (elevation < 0) {
    return [];
  }
  return [elevation, azimuth];
}

// Turn one computation into a single human readable report line.
function describePointing(name, location) {
  const result = pointing(location);
  if (result.length === 0) {
    return `${name}: satellite below the horizon`;
  }
  const [elevation, azimuth] = result;
  return `${name}: elevation ${elevation.toFixed(2)}°, azimuth ${azimuth.toFixed(2)}°`;
}

function main() {
  const stations = [
    ['Nairobi -> 21.5E', [21.5, 0, 36.8]],
    ['London -> 19.2E', [19.2, 51.5, -0.13]],
    ['Sydney -> 160.0E', [160.0, -33.87, 151.2]],
    ['Quito -> 75.0W', [-75.0, 0, -78.5]],
  ];
  for (const [name, location] of stations) {
    console.log(describePointing(name, location));
  }
}

main();

