function dive(profile) {
  const [maxDepth, bottomTime] = profile;

  // A dive that never leaves the surface has no ascent to plan
  if (!(maxDepth > 0)) {
    return [];
  }

  // Time cannot run backwards, so a negative bottom time is rejected
  if (bottomTime < 0) {
    return [];
  }

  const loading = maxDepth * bottomTime; // tissue nitrogen loading factor
  if (loading < 500) {
    // Short and/or shallow: direct ascent, no mandatory stops
    return [];
  }

  if (loading <= 800) {
    // Moderate loading only calls for the standard safety stop
    return [[5, 3]];
  }

  // Heavy loading: break the ascent at half the maximum depth first
  const deepStop = Math.floor(maxDepth / 2);
  return [[deepStop, 2], [5, 5]];
}

function totalStopTime(schedule) {
  return schedule.reduce((sum, [, minutes]) => sum + minutes, 0);
}

function formatSchedule(schedule) {
  if (schedule.length === 0) {
    // Nothing to hold for: report the direct ascent explicitly
    return 'direct ascent';
  }
  return schedule
    .map(([depth, minutes]) => `${minutes} min @ ${depth} m`)
    .join(', ');
}

function describeDive(profile) {
  const [maxDepth, bottomTime] = profile;
