const TOO_LIGHT = 'Skier is too light for adult bindings';

const MAX_RELEASE_VALUE = 18;

// Release values are only ever published in half-step increments
function roundToHalf(value) {
  return Math.round(value * 2) / 2;
}

// The five fields arrive in a fixed order, so validation is positional
function parseSkier(skier) {
  if (!Array.isArray(skier) || skier.length !== 5) {
    throw new TypeError('skier must be [weight, height, age, soleLength, type]');
  }
  const [weight, height, age, soleLength, type] = skier.map(Number);
  if ([weight, height, age, soleLength, type].some((n) => !Number.isFinite(n))) {
    throw new TypeError('all skier measurements must be finite numbers');
  }
  // Skier type drives a lookup table further down, so reject unknown codes early
  if (![1, 2, 3].includes(type)) {
    throw new RangeError('skier type must be 1, 2 or 3');
  }
  return { weight, height, age, soleLength, type };
}

function binding(skier) {
  const { weight, height, age, soleLength, type } = parseSkier(skier);

  // Children's systems are a different standard entirely
  if (weight < 13) {
    return TOO_LIGHT;
  }
  // A short sole cannot be clamped safely by an adult toe piece
  if (soleLength < 200) {
    return 0;
  }

  let value = weight / 10;

  // Short skiers put less bending force into the ski
  if (height < 150) {
    value -= 1;
  }
  // Bone density concerns at both ends of the age range
  if (age > 50 || age < 10) {
    value -= 1;
  }

  // Aggressive skiers want the binding to hold on longer
  const typeBonus = { 1: 0, 2: 1, 3: 2 };
  value += typeBonus[type];

  // A long sole is a long lever arm, so the same twist reaches the bone sooner
  if (soleLength > 330) {
    value -= 0.5;
  }

  return roundToHalf(Math.min(value, MAX_RELEASE_VALUE));
}

// Turn the raw return value into something a shop technician can read
function describeSetting(skier) {
  const result = binding(skier);
  if (typeof result === 'string') {
    return result;
  }
  // Zero is the sentinel for "no adult binding fits this boot"
  if (result === 0) {
    return 'Boot sole too short for adult bindings';
  }
  return `Release value: ${result.toFixed(1)}`;
}

function main() {
  const customers = [
    [80, 180, 30, 320, 2],
    [10, 90, 5, 180, 1],
    [45, 140, 9, 190, 1],
    [120, 195, 55, 355, 3],
  ];
  // One line per customer keeps the bench printout easy to scan
  for (const customer of customers) {
    console.log(customer.join(' / '), '->', describeSetting(customer));
  }
}

main();

module.exports = { binding, describeSetting, roundToHalf };

