const ROTOR_RADIUS_FT = 20;
const ROTOR_FLOW_GPM = 3;
const MIN_PRESSURE_PSI = 30;

// A rotor sweeps a full circle, so its footprint is pi * r^2
function rotorCoverage(radius) {
  return Math.PI * radius * radius;
}

// The yard is treated as a simple rectangle of length by width
function yardArea(length, width) {
  return length * width;
}

function sprinkler(yard) {
  const [length, width, pressure, flowRate] = yard;

  // Below 30 psi the rotors never pop up, so nothing can be installed
  if (pressure < MIN_PRESSURE_PSI) {
    return [0, 0];
  }

  // Under 3 gpm the supply cannot even drive one rotor
  if (flowRate < ROTOR_FLOW_GPM) {
    return [-1, -1];
  }

  const area = yardArea(length, width);
  const coverage = rotorCoverage(ROTOR_RADIUS_FT);

  // Partial coverage still needs a whole rotor, hence the ceiling
  const rotors = Math.ceil(area / coverage);

  // Every rotor draws the same fixed flow when it is running
  const requiredFlow = rotors * ROTOR_FLOW_GPM;

  // Rotors are split into zones that each fit inside the available flow
  const zones = Math.ceil(requiredFlow / flowRate);

  return [rotors, zones];
}

// Turn a result pair back into the wording an installer would read
function describeLayout(yard, result) {
  const [rotors, zones] = result;

  if (rotors === 0) {
    return `${yard[0]}x${yard[1]} ft: pressure ${yard[2]} psi is too low for pop-up rotors`;
  }

  if (rotors === -1) {
    return `${yard[0]}x${yard[1]} ft: flow ${yard[3]} gpm cannot power a single rotor`;
  }

  // Zones run one after another, so the watering time multiplies by zone count
  const runtimePerZone = 20;
  const totalRuntime = zones * runtimePerZone;

  return `${yard[0]}x${yard[1]} ft: ${rotors} rotors in ${zones} zone(s), ` +
    `${totalRuntime} min total run time`;
}

function main() {
  const yards = [
    [100, 50, 45, 12],
    [200, 120, 60, 9],
    [80, 40, 22, 15],
    [60, 30, 50, 2],
  ];

  for (const yard of yards) {
    const result = sprinkler(yard);
    // Print the raw pair alongside the human-readable summary
    console.log(JSON.stringify(result), '-', describeLayout(yard, result));
  }
}

main();

module.exports = { sprinkler, describeLayout, rotorCoverage, yardArea };

