const BASE_PER_SWITCH = 0.05;
const THICK_SURCHARGE = 0.02;
const HEAVY_SPRING_EXTRA = 0.01;
const BRUSH_BUFFER = 1;
const MINIMUM_ORDER = 3;

const LINEAR = 1;
const TACTILE = 2;
const THIN = 1;
const THICK = 2;

// A build is described positionally, so reject anything that is not a 4-slot list
function parseBuild(build) {
  if (!Array.isArray(build) || build.length !== 4) {
    throw new TypeError('build must be [count, switchType, springWeight, applicationStyle]');
  }
  const [count, switchType, springWeight, applicationStyle] = build.map(Number);
  if (!Number.isInteger(count) || count <= 0) {
    throw new RangeError('switch count must be a positive integer');
  }
  // Only the two documented switch types and the two documented styles have defined volumes
  if (switchType !== LINEAR && switchType !== TACTILE) {
    throw new RangeError('switch type must be 1 (linear) or 2 (tactile)');
  }
  if (applicationStyle !== THIN && applicationStyle !== THICK) {
    throw new RangeError('application style must be 1 (thin) or 2 (thick)');
  }
  if (!Number.isFinite(springWeight) || springWeight <= 0) {
    throw new RangeError('spring weight must be a positive number of grams');
  }
  return { count, switchType, springWeight, applicationStyle };
}

function perSwitchVolume({ switchType, springWeight, applicationStyle }) {
  let volume = BASE_PER_SWITCH;
  // Thick application simply needs more product on every switch
  if (applicationStyle === THICK) {
    volume += THICK_SURCHARGE;
  }
  if (switchType === TACTILE) {
    // Trim a tenth off tactile switches so the bump survives the lube
    volume *= 0.9;
  }
