function validateWeapon(weapon) {
  // The task supplies the weapon as a four-element list, so reject anything else
  if (!Array.isArray(weapon) || weapon.length !== 4) {
    throw new TypeError('weapon must be a list of four values');
  }
  const [counterweight, projectile, sling, friction] = weapon.map(Number);
  if ([counterweight, projectile, sling, friction].some(Number.isNaN)) {
    throw new TypeError('weapon values must be numeric');
  }
  // A zero projectile mass would make the mass ratio infinite
  if (projectile <= 0) {
    throw new RangeError('projectile mass must be greater than zero');
  }
  return { counterweight, projectile, sling, friction };
}

function siege(weapon) {
  const { counterweight, projectile, sling, friction } = validateWeapon(weapon);

  // Mechanical advantage of the counterweight over the load
  const massRatio = counterweight / projectile;
  const energy = massRatio * sling;

  let range = energy * 2.5;

  // Pivot friction is given in percent but subtracted as plain meters
  range -= friction;

  if (projectile > 50) {
    // Heavy stones lose roughly ten meters to air drag
    range -= 10;
  }

  if (sling > 3) {
    // Long slings whip the projectile faster, worth a 15% bonus
    range *= 1.15;
  }

  if (massRatio < 50) {
    // Too little counterweight: the beam stalls and loses a fifth of the throw
    range *= 0.8;
  }

  // A negative range is meaningless; the stone simply drops at the pivot
  return Math.round(Math.max(range, 0));
}

function describeSiege(name, weapon) {
  const distance = siege(weapon);
  // Wall-breaching artillery was generally sited beyond bowshot, about 180 m
  const verdict = distance >= 180 ? 'outranges the walls' : 'must be moved closer';
  return `${name}: ${distance} m — ${verdict}`;
}

function main() {
  const arsenal = [
    ['Warwolf', [8000, 60, 4.5, 12]],
    ['Bad Neighbour', [3000, 45, 3.2, 8]],
    ['Little Sister', [900, 30, 2.4, 15]],
    ['Rusty Hinge', [400, 80, 2.0, 60]],
  ];

  for (const [name, weapon] of arsenal) {
    console.log(describeSiege(name, weapon));
  }

  // Report the best engine so the master gunner knows which to load first
  const best = arsenal.reduce((a, b) => (siege(b[1]) > siege(a[1]) ? b : a));
  console.log(`Longest throw: ${best[0]} at ${siege(best[1])} m`);
}

main();

module.exports = { siege, describeSiege };

