function parseWash(input) {
  // The task hands us a four-element list rather than named arguments
  const [inkDrops, shadePercent, skinTone, needle] = input;
  if (!Number.isFinite(inkDrops) || inkDrops <= 0) {
    throw new RangeError('initial ink drops must be a positive number');
  }
  // The shading range is fixed by the technique: 10% to 90%
  if (shadePercent < 10 || shadePercent > 90) {
    throw new RangeError('target shade must be between 10 and 90 percent');
  }
  if (skinTone < 1 || skinTone > 10) {
    throw new RangeError('skin tone darkness must be between 1 and 10');
  }
  // Only two needle groupings are supported: 1 = liner, 2 = magnum
  if (needle !== 1 && needle !== 2) {
    throw new RangeError('needle must be 1 (liner) or 2 (magnum)');
  }
  return { inkDrops, shadePercent, skinTone, needle };
}

function wash(ink) {
  const { inkDrops, shadePercent, skinTone, needle } = parseWash(ink);

  // Total mixture volume follows from the dilution ratio
  const totalDrops = inkDrops / (shadePercent / 100);
  let waterDrops = totalDrops - inkDrops;

  if (needle === 2) {
    // Magnums saturate the skin more heavily, so thin the wash further
    waterDrops *= 1.2;
  }

  if (skinTone >= 7) {
    // Darker skin needs a denser pigment to stay visible
    waterDrops -= 3;
  }

  if (shadePercent < 20) {
    // Very light shades need extra water for a buttery smooth fade
    waterDrops += 5;
  }

  // A negative amount of water is meaningless at the workstation
  if (waterDrops < 0) {
    waterDrops = 0;
  }

  return Math.round(waterDrops);
}

function describeWash(ink) {
  const { inkDrops, shadePercent, skinTone, needle } = parseWash(ink);
  const water = wash(ink);
  // Report the needle by its shop name so the artist can read the mix sheet
  const needleName = needle === 1 ? 'liner' : 'magnum';
  return `${inkDrops} drops ink + ${water} drops water -> ${shadePercent}% gray` +
    ` (tone ${skinTone}, ${needleName})`;
}

function main() {
  const mixSheet = [
    [10, 50, 5, 1],
    [10, 50, 5, 2],
    [12, 15, 8, 2],
    [5, 90, 9, 1],
  ];

  for (const recipe of mixSheet) {
    console.log(describeWash(recipe));
  }

  // Out-of-range recipes are rejected rather than silently mixed
  try {
    wash([8, 95, 4, 1]);
  } catch (err) {
    console.log(`rejected: ${err.message}`);
  }
}

main();

