text_nat:
// Fountain pen ink flow estimator.
// A pen is described as [slitWidthMm, surfaceTensionMnPerM, feedDepthMm, absorbency]

const MAX_FLOW = 20;

function validatePen(pen) {
  if (!Array.isArray(pen) || pen.length !== 4) {
    throw new TypeError('pen must be a list of four values');
  }
  const [slit, tension, depth, absorbency] = pen;
  // every physical characteristic must be a finite number
  if (![slit, tension, depth, absorbency].every((v) => Number.isFinite(v))) {
    throw new TypeError('pen values must be finite numbers');
  }
  // dividing by the surface tension only makes sense for a positive value
  if (tension <= 0) {
    throw new RangeError('surface tension must be greater than zero');
  }
  if (slit < 0 || depth < 0) {
    throw new RangeError('slit width and feed depth cannot be negative');
  }
  // the absorbency score is a paper rating on a one-to-five scale
  if (absorbency < 1 || absorbency > 5) {
    throw new RangeError('absorbency must be between 1 and 5');
  }
  return { slit, tension, depth, absorbency };
}

function flow(pen) {
  const { slit, tension, depth, absorbency } = validatePen(pen);

  // base flow: the cross-section of the ink path, scaled to microliters
  let rate = slit * depth * 1000;

  // thinner ink (low surface tension) runs more freely through the feed
  rate = (rate / tension) * 50;

  if (absorbency >= 4) {
    // thirsty paper pulls ink off the nib like a vacuum
    rate *= 1.25;
  } else if (absorbency === 1) {
    // coated, non-absorbent paper holds the ink back
    rate *= 0.85;
  }

  if (depth > 1) {
    rate += 3; // deep channel delivers a heavy flow bonus
  } else if (slit < 0.2) {
    // a very tight slit restricts capillary action
    rate -= 2;
  }

  // cap the result so the nib does not pool ink on the page
  if (rate > MAX_FLOW) {
    rate = MAX_FLOW;
  }

  return Math.round(rate * 100) / 100;
}

function describe(name, pen) {
  const rate = flow(pen);
  // report the capped pens explicitly so the user knows why they match
  const note = rate === MAX_FLOW ? ' (capped)' : '';
  return `${name}: ${rate.toFixed(2)} uL/min${note}`;
}

function main() {
  const pens = [
    ['Fine steel nib', [0.15, 45, 0.6, 3]],
    ['Broad gold nib', [0.35, 32, 1.2, 5]],
    ['Vintage flex nib', [0.25, 38, 0.9, 1]],
  ];
  for (const [name, pen] of pens) {
    console.log(describe(name, pen));
  }
}

main();

module.exports = { flow, describe, validatePen };

