'use strict';

// Each cube specification arrives as a flat list, so name the slots once here
const FIELDS = ['viscosity', 'drops', 'tension', 'breakIn'];

function parseCube(cube) {
  if (!Array.isArray(cube) || cube.length !== FIELDS.length) {
    throw new TypeError(`expected [${FIELDS.join(', ')}]`);
  }
  const spec = {};
  FIELDS.forEach((name, i) => {
    const value = Number(cube[i]);
    // Strings such as "1000" are accepted, anything non-numeric is not
    if (!Number.isFinite(value)) {
      throw new TypeError(`${name} must be numeric, got ${cube[i]}`);
    }
    spec[name] = value;
  });
  // Dividing ten thousand by the viscosity only makes sense for a real fluid
  if (spec.viscosity <= 0) {
    throw new RangeError('viscosity must be positive');
  }
  // Spring tension is specified on a one-to-ten scale
  if (spec.tension < 1 || spec.tension > 10) {
    throw new RangeError('tension must be between 1 and 10');
  }
  return spec;
}

function lube(cube) {
  const { viscosity, drops, tension, breakIn } = parseCube(cube);

  // Thinner lube flows faster, hence the inverse relationship
  const initialSpeedFactor = 10000 / viscosity;
  const frictionModifier = initialSpeedFactor * drops;
  let speed = 100 - frictionModifier;

  // Only tension points above the neutral setting of five cost speed
  if (tension > 5) {
    speed -= 2 * (tension - 5);
  }

  // One point per completed ten solves, capped at fifteen
  const breakInBonus = Math.min(Math.floor(breakIn / 10), 15);
  speed += breakInBonus;

  // Very thin lube is snappy and earns a flat bonus
  if (viscosity < 500) {
    speed += 5;
  }

  if (speed < 0) {
    speed = 0;
  }
  return Math.round(speed * 10) / 10;
}

function report(cube) {
  const { viscosity, drops } = parseCube(cube);
  const speed = lube(cube);
  // Zero means the cube is locked up solid, which deserves a clearer word
  const verdict = speed === 0 ? 'unturnable' : `${speed} speed factor`;
  return `${viscosity} cSt x ${drops} drop(s): ${verdict}`;
}

function main() {
  const cubes = [
    [1000, 2, 5, 100],
    [300, 1, 7, 45],
    [50, 5, 10, 0],
    ['5000', '3', '4', '250'],
  ];
  cubes.forEach((cube) => console.log(report(cube)));

  // Surface bad data instead of letting NaN reach the report
  try {
    report([1000, 2, 12, 30]);
  } catch (err) {
    console.log(`rejected: ${err.message}`);
  }
}

main();

module.exports = { lube, report };

