// Table tennis spin estimator: converts equipment and stroke data into revolutions per second.

const MAX_SPIN = 150;

// Each racket entry is [tackiness, spongeThickness, swingSpeed, carbonFlag] in that fixed order.
const FIELD_NAMES = ["tackiness", "sponge thickness", "swing speed", "carbon indicator"];

function validateRacket(racket) {
  if (!Array.isArray(racket) || racket.length !== 4) {
    throw new TypeError("racket must be a list of four values: " + FIELD_NAMES.join(", "));
  }
  racket.forEach((value, index) => {
    // A non-finite entry would silently poison every later arithmetic step.
    if (typeof value !== "number" || !Number.isFinite(value)) {
      throw new TypeError(`${FIELD_NAMES[index]} must be a finite number`);
    }
  });
  const [tackiness, thickness, speed, carbon] = racket;
  if (tackiness < 1 || tackiness > 10) {
    // Rubber tackiness is published on a one-to-ten scale.
    throw new RangeError("tackiness must be between 1 and 10");
  }
  if (thickness <= 0 || speed < 0) {
    throw new RangeError("sponge thickness and swing speed must be positive");
  }
  if (carbon !== 0 && carbon !== 1) {
    // The blade indicator is a flag: one is true, zero is false.
    throw new RangeError("carbon indicator must be 0 or 1");
  }
  return { tackiness, thickness, speed, carbon };
}

function spin(racket) {
  const { tackiness, thickness, speed, carbon } = validateRacket(racket);

  // Grip coefficient couples the rubber's bite with how deep the ball sinks.
  const grip = tackiness * thickness;
  let rps = (speed * grip) / 10;

  if (carbon === 1) {
    // Carbon stiffens the blade and shortens dwell time, costing twelve percent of the spin.
    rps *= 0.88;
  }
  if (thickness > 2.0) {
    // Thick sponge catapults the ball out with extra rotation.
    rps += 5;
  }
  if (speed < 40) {
    // Slow swings cannot brush the ball properly.
    rps -= 3;
  }

  return Math.round(Math.min(rps, MAX_SPIN));
}

function describe(name, racket) {
  const blade = racket[3] === 1 ? "carbon" : "all-wood";
  // Pad the label so the report lines up in a terminal.
  return `${name.padEnd(18)} ${blade.padEnd(9)} ${spin(racket)} rps`;
}

const rackets = {
  "Hurricane 3 / ALC": [9, 2.15, 62, 1],
  "Tenergy 05 / Wood": [6, 2.1, 55, 0],
  "Beginner set": [3, 1.5, 32, 0],
  "Pro loop driver": [10, 2.2, 95, 1],
};

// Print one line per racket in the comparison table.
for (const [name, racket] of Object.entries(rackets)) {
  console.log(describe(name, racket));
}

module.exports = { spin, describe, validateRacket };

