// Neon sign transformer sizing calculator.
//
// A sign is described as [tubeLengthFeet, tubeDiameterMm, electrodeCount, gasCode]
// where the gas code 1 means neon and 2 means argon.

const NEON = 1;
const ARGON = 2;

// Volts required per foot of illuminated tubing before any adjustments.
const VOLTS_PER_FOOT = 300;
const VOLTS_PER_ELECTRODE = 200;
const STANDARD_STEP = 1000;

function parseSign(sign) {
  if (!Array.isArray(sign) || sign.length !== 4) {
    throw new TypeError('sign must be [length, diameter, electrodes, gasCode]');
  }
  const [length, diameter, electrodes, gasCode] = sign.map(Number);
  // A malformed entry anywhere would silently poison the arithmetic below.
  if ([length, diameter, electrodes, gasCode].some(Number.isNaN)) {
    throw new TypeError('all sign values must be numeric');
  }
  if (gasCode !== NEON && gasCode !== ARGON) {
    throw new RangeError(`unknown gas code: ${gasCode}`);
  }
  return { length, diameter, electrodes, gasCode };
}

function transformer(sign) {
  const { length, diameter, electrodes, gasCode } = parseSign(sign);

  let volts = length * VOLTS_PER_FOOT;

  // Argon strikes more easily than neon, so it needs 20% less driving voltage.
  if (gasCode === ARGON) {
    volts *= 0.8;
  }

  volts += electrodes * VOLTS_PER_ELECTRODE;

  // Narrow tubing constricts the arc and demands extra headroom.
  if (diameter <= 10) {
    volts *= 1.15;
  }

  // Long runs lose voltage along the way; compensate with a flat penalty.
  if (length > 40) {
    volts += 500;
  }

  // Transformers only exist in 1 kV steps, so never round down.
  return Math.ceil(volts / STANDARD_STEP) * STANDARD_STEP;
}

function describe(name, sign) {
  const rating = transformer(sign);
  const gas = sign[3] === ARGON ? 'argon' : 'neon';
  // Ratings are quoted in kilovolts on the transformer nameplate.
  const kv = (rating / 1000).toFixed(0);
  return `${name}: ${sign[0]} ft of ${sign[1]}mm ${gas}, ` +
    `${sign[2]} electrodes -> ${kv} kV (${rating} V)`;
}

function main() {
  const jobs = [
    ['Diner window', [30, 12, 2, NEON]],
    ['Arcade arrow', [18, 9, 2, ARGON]],
    ['Rooftop banner', [52, 15, 4, NEON]],
    ['Cursive script', [45, 8, 6, ARGON]],
  ];

  for (const [name, sign] of jobs) {
    console.log(describe(name, sign));
  }

  // The largest rating on the order determines which stock we must carry.
  const biggest = Math.max(...jobs.map(([, sign]) => transformer(sign)));
  console.log(`Largest transformer needed: ${biggest} V`);
}

main();

module.exports = { transformer, describe };

