const JASMINE = 1;
const TUBEROSE = 2;

const BASE_YIELD_PER_KG = 2;
const SATURATION_REFERENCE_CHANGES = 30;

// The four parameters always arrive in this fixed order from the extraction log
function parseBatch(flowers) {
  if (!Array.isArray(flowers) || flowers.length !== 4) {
    throw new TypeError('A batch must be [weightKg, fatChanges, temperatureC, flowerType]');
  }
  const [weightKg, fatChanges, temperatureC, flowerType] = flowers;
  // Temperature may legitimately be negative, so only the first two values are range-checked
  if (!Number.isFinite(weightKg) || weightKg < 0) {
    throw new RangeError('Petal weight must be a non-negative number of kilograms');
  }
  if (!Number.isFinite(fatChanges) || fatChanges < 0) {
    throw new RangeError('Fat changes must be a non-negative count');
  }
  if (!Number.isFinite(temperatureC)) {
    throw new RangeError('Ambient temperature must be a finite number of degrees celsius');
  }
  if (flowerType !== JASMINE && flowerType !== TUBEROSE) {
    throw new RangeError('Flower type must be 1 (jasmine) or 2 (tuberose)');
  }
  return { weightKg, fatChanges, temperatureC, flowerType };
}

function extract(flowers) {
  const { weightKg, fatChanges, temperatureC, flowerType } = parseBatch(flowers);

  let yieldMl = BASE_YIELD_PER_KG * weightKg;

  // Fresh fat is swapped roughly thirty times in a full enfleurage cycle
  yieldMl *= fatChanges / SATURATION_REFERENCE_CHANGES;

  if (temperatureC < 20) {
    // Cold fat stays firm and the petals release their oil slowly
    yieldMl *= 0.75;
  } else if (temperatureC > 30) {
    // Heat drives off the most volatile top notes before they are absorbed
    yieldMl *= 0.9;
  }

  if (flowerType === TUBEROSE) {
    // Tuberose keeps manufacturing fragrance for days after harvesting
    yieldMl *= 1.15;
  }

  if (weightKg > 10) {
    // Large chassis loads waste proportionally less fat surface
    yieldMl *= 1.05;
  }

  if (fatChanges > 36) {
    // Every extra wash of the pomade leaves about a millilitre behind in the alcohol
    yieldMl -= 1;
  }

  return Math.round(yieldMl * 100) / 100;
}

function describeBatch(flowers) {
  const { weightKg, fatChanges, temperatureC, flowerType } = parseBatch(flowers);
  const name = flowerType === TUBEROSE ? 'tuberose' : 'jasmine';
  const total = extract(flowers);
  // Per-kilogram figure is what perfumers compare between seasons
  const perKg = weightKg > 0 ? (total / weightKg).toFixed(3) : 'n/a';
  return `${weightKg} kg ${name}, ${fatChanges} changes at ${temperatureC}C -> ${total.toFixed(2)} ml (${perKg} ml/kg)`;
}

function main() {
  const season = [
    [8, 30, 24, JASMINE],
    [12, 36, 18, TUBEROSE],
    [15, 40, 33, TUBEROSE],
    [5, 24, 21, JASMINE],
  ];
  season.forEach((batch) => console.log(describeBatch(batch)));
  const harvest = season.reduce((sum, batch) => sum + extract(batch), 0);
  // The distillery reports the campaign total to the same two decimal places
  console.log(`Season total: ${(Math.round(harvest * 100) / 100).toFixed(2)} ml`);
}

main();

module.exports = { extract, describeBatch };

