const BOW = 1;
const C_SHAPE = 2;

// Shape codes map to multipliers: a bow kite depowers, a c-shape pulls harder
const SHAPE_FACTORS = {
  [BOW]: 0.9,
  [C_SHAPE]: 1.2,
};

function parseSetup(kite) {
  if (!Array.isArray(kite) || kite.length !== 4) {
    throw new TypeError('kite must be [windKnots, areaM2, riderKg, shapeCode]');
  }
  const [windKnots, areaM2, riderKg, shapeCode] = kite.map(Number);
  // A setup with non-numeric entries cannot produce a meaningful tension
  if ([windKnots, areaM2, riderKg].some((value) => !Number.isFinite(value))) {
    throw new RangeError('wind speed, area and rider weight must be numbers');
  }
  if (!Object.prototype.hasOwnProperty.call(SHAPE_FACTORS, shapeCode)) {
    throw new RangeError(`unknown kite shape code: ${shapeCode}`);
  }
  return { windKnots, areaM2, riderKg, shapeCode };
}

function tension(kite) {
  const { windKnots, areaM2, riderKg, shapeCode } = parseSetup(kite);

  // Aerodynamic force scales with the square of the wind speed and the canopy area
  let daN = (windKnots * windKnots * areaM2) / 5;

  daN *= SHAPE_FACTORS[shapeCode];

  // A heavy rider can edge harder, loading the lines with a flat extra pull
  if (riderKg > 85) {
    daN += 15;
  }

  // Above 25 knots the gusts spike the load by a quarter
  if (windKnots > 25) {
    daN *= 1.25;
  }

  // The bar is never truly slack once the kite is flying
  if (daN < 20) {
    daN = 20;
  }

  return Math.round(daN * 10) / 10;
}

function describeSetup(kite) {
  const { windKnots, areaM2, riderKg, shapeCode } = parseSetup(kite);
  const shape = shapeCode === C_SHAPE ? 'C-shape' : 'bow';
  const load = tension(kite);
  // Line sets are usually rated around 250 daN, so flag anything close to that
  const warning = load > 200 ? ' -- WARNING: near line breaking strength' : '';
  return `${areaM2}m2 ${shape} in ${windKnots}kt, ${riderKg}kg rider: ${load.toFixed(1)} daN${warning}`;
}

function main() {
  const setups = [
    [18, 9, 78, BOW],
    [28, 12, 92, C_SHAPE],
    [8, 7, 70, BOW],
    [22, 10, 88, C_SHAPE],
  ];

  setups.forEach((setup) => console.log(describeSetup(setup)));

  // Report the worst case so the rider knows which session sizes the lines
  const heaviest = setups.reduce((worst, setup) => (tension(setup) > tension(worst) ? setup : worst));
  console.log(`Maximum line tension of the day: ${tension(heaviest).toFixed(1)} daN`);
}

main();

module.exports = { tension, describeSetup, BOW, C_SHAPE };

