const ROW_SIZE = 20;

// A seat is stored as a boolean: true means occupied, false means free
function emptyRow() {
  return new Array(ROW_SIZE).fill(false);
}

// Group sizes come from user input, so reject anything that is not a usable count
function validateSize(size) {
  if (!Number.isInteger(size) || size < 1) {
    throw new TypeError(`invalid group size: ${String(size)}`);
  }
  return size;
}

function isFree(row, index) {
  // Seats outside the row behave like occupied seats: they close off a gap
  if (index < 0 || index >= ROW_SIZE) return false;
  return !row[index];
}

// Placing a block must not strand a single free seat against a group or an edge
function leavesIsolatedSeat(row, start, size) {
  const before = start - 1;
  const after = start + size;
  // One free seat to the left, bounded on its far side by a group or the edge
  if (isFree(row, before) && !isFree(row, before - 1)) return true;
  // Mirror check on the right of the freshly placed block
  if (isFree(row, after) && !isFree(row, after + 1)) return true;
  return false;
}

function fits(row, start, size) {
  if (start + size > ROW_SIZE) return false;
  for (let i = start; i < start + size; i++) {
    if (row[i]) return false;
  }
  return !leavesIsolatedSeat(row, start, size);
}

// Leftmost contiguous block that holds the group without breaking the rule
function findBlock(row, size) {
  for (let start = 0; start + size <= ROW_SIZE; start++) {
    if (fits(row, start, size)) return start;
  }
  return -1;
}

function seat(groups) {
  const row = emptyRow();
  const placements = [];
  for (const size of groups) {
    const start = findBlock(row, validateSize(size));
    if (start === -1) {
      // The group cannot be kept together anywhere, so it is skipped
      placements.push([]);
      continue;
    }
    const indexes = [];
    for (let i = start; i < start + size; i++) {
      row[i] = true;
      indexes.push(i);
    }
    placements.push(indexes);
  }
  return placements;
}

// Render the final row, labelling each seat with the group that took it
function renderRow(placements) {
  const cells = new Array(ROW_SIZE).fill('.');
  placements.forEach((indexes, group) => {
    // Groups are numbered from 1 in the report; '.' marks a seat left empty
    for (const index of indexes) cells[index] = String((group + 1) % 10);
  });
  return cells.join('');
}

function report(groups) {
  const placements = seat(groups);
  placements.forEach((indexes, i) => {
    const where = indexes.length ? indexes.join(',') : 'no seats';
    console.log(`group ${i + 1} (size ${groups[i]}): ${where}`);
  });
  console.log(renderRow(placements));
}

report([3, 2, 4, 1, 5, 2, 6]);

