const ENGINE = 'engine';
const CABOOSE = 'caboose';
const BUFFER = 'buffer';

// Every cargo type the yard knows how to marshal, in the order it must ride
const CARGO_ORDER = ['heavy', 'standard', 'hazardous'];

// Group the manifest into one bucket per cargo class, keeping the counts
function groupCargo(cars) {
  const groups = { heavy: [], standard: [], hazardous: [] };
  for (const car of cars) {
    const type = String(car).trim().toLowerCase();
    // An unrecognised cargo label cannot be sequenced safely, so refuse the whole manifest
    if (!Object.prototype.hasOwnProperty.call(groups, type)) {
      throw new Error(`unknown cargo type: ${car}`);
    }
    groups[type].push(type);
  }
  return groups;
}

// Hazardous cars never touch each other: a buffer leads the block and separates each pair
function isolateHazardous(hazardous) {
  const isolated = [];
  for (const car of hazardous) {
    isolated.push(BUFFER, car);
  }
  return isolated;
}

function assemble(cars) {
  // Accept any iterable manifest, but reject the non-iterable ones outright
  if (cars == null || typeof cars[Symbol.iterator] !== 'function' || typeof cars === 'string') {
    throw new TypeError('assemble expects a list of cargo types');
  }
  const groups = groupCargo(cars);
  const train = [ENGINE];
  // Heavy materials sit right behind the engine so the drive wheels keep traction
  train.push(...groups.heavy);
  train.push(...groups.standard);
  // The isolated hazardous block is the last cargo before the caboose
  train.push(...isolateHazardous(groups.hazardous));
  train.push(CABOOSE);
  return train;
}

// Human-readable summary of a manifest: how many of each class were loaded
function describeManifest(cars) {
  const groups = groupCargo(cars);
  const parts = CARGO_ORDER
    .filter((type) => groups[type].length > 0)
    .map((type) => `${groups[type].length} ${type}`);
  // An empty manifest still yields a valid train, just without any cargo to report
  return parts.length === 0 ? 'no cargo' : parts.join(', ');
}

function main() {
  const manifests = [
    ['standard', 'hazardous', 'heavy'],
    ['hazardous', 'hazardous', 'hazardous'],
    ['heavy', 'heavy', 'standard', 'standard', 'hazardous'],
    [],
  ];
  for (const manifest of manifests) {
    const train = assemble(manifest);
    console.log(`${describeManifest(manifest)} -> ${train.join(' | ')}`);
  }
  try {
    assemble(['standard', 'livestock']);
  } catch (err) {
    // The yard rejects manifests it cannot marshal instead of guessing
    console.log(`rejected: ${err.message}`);
  }
}

// Run the yard report only when this file is the entry point, not when required
if (require.main === module) {
  main();
}

module.exports = { assemble, groupCargo, isolateHazardous, describeManifest };

