'use strict';

// A flight is described as [timeZonesCrossed, direction, arrivalHour]
function parseFlight(flight) {
  if (!Array.isArray(flight) || flight.length !== 3) {
    throw new TypeError('flight must be [zones, direction, arrivalHour]');
  }
  const [zones, direction, arrivalHour] = flight;
  if (!Number.isInteger(zones) || zones < 0) {
    throw new RangeError('time zones crossed must be a non-negative integer');
  }
  // direction is compared in lower case so "East" and "east" behave alike
  const heading = String(direction).toLowerCase();
  if (heading !== 'east' && heading !== 'west') {
    throw new RangeError('direction must be "east" or "west"');
  }
  if (!Number.isInteger(arrivalHour) || arrivalHour < 0 || arrivalHour > 23) {
    throw new RangeError('arrival hour must be an integer from 0 to 23');
  }
  return { zones, heading, arrivalHour };
}

// Morning arrivals run from dawn until noon
function isMorning(hour) {
  return hour >= 5 && hour < 12;
}

function isEvening(hour) {
  return hour >= 18;
}

function recover(flight) {
  const { zones, heading, arrivalHour } = parseFlight(flight);
  // One recovery day is allocated for every two zones crossed
  let days = Math.floor(zones / 2);
  if (heading === 'east' && zones > 3) {
    days += 1; // eastward travel fights the natural drift of the body clock
  }
  // Ten in the evening is the default target bedtime
  let sleepHour = 22;
  if (heading === 'east' && isMorning(arrivalHour)) {
    sleepHour -= 1; // going to bed earlier advances the circadian rhythm
  } else if (heading === 'west' && isEvening(arrivalHour)) {
    sleepHour += 1; // a later bedtime delays the clock to match the new zone
  }
  // No itinerary is ever given more than a week of recovery
  return [Math.min(days, 7), sleepHour];
}

function describe(flight) {
  const [days, sleepHour] = recover(flight);
  // Bedtimes live in the 21:00-23:00 range, so a simple PM label is enough
  const bedtime = `${sleepHour - 12} PM`;
  const dayWord = days === 1 ? 'day' : 'days';
  return `${flight[0]} zones ${flight[1]}, landing at ${flight[2]}:00 -> ` +
    `${days} ${dayWord} of recovery, sleep at ${bedtime}`;
}

function main() {
  const itineraries = [
    [6, 'east', 8],
    [3, 'west', 20],
    [2, 'east', 14],
    [15, 'west', 9],
    [20, 'east', 6],
  ];
  // Each itinerary is reported on its own line
  for (const flight of itineraries) {
    console.log(describe(flight));
  }
  try {
    recover([4, 'north', 10]);
  } catch (err) {
    // Bad input is reported rather than silently producing a schedule
    console.log(`rejected: ${err.message}`);
  }
}

main();

module.exports = { recover, describe, parseFlight };

