const DEG_TO_RAD = Math.PI / 180;

// angles may arrive as any real value, so fold them into a single turn before comparing ranges
function normalizeAngle(degrees) {
  const wrapped = degrees % 360;
  return wrapped < 0 ? wrapped + 360 : wrapped;
}

// cardioid pickup pattern: full response on axis, theoretical zero at 180 degrees
function cardioidPickup(angle) {
  return 50 + 50 * Math.cos(angle * DEG_TO_RAD);
}

// inverse square law: doubling the distance quarters the signal energy
function distanceFactor(distance) {
  return 1 / (distance * distance);
}

// the physical capsule has a rejection lobe rather than a perfect point null
function isInRejectionNull(angle) {
  return angle >= 160 && angle <= 200;
}

function clampPercentage(value) {
  return Math.min(100, Math.max(0, value));
}

function attenuate(source) {
  const [rawAngle, distance, highPass] = source;
  // a zero or negative distance would make the inverse square law explode
  if (!(distance > 0)) {
    throw new RangeError('distance must be a positive number of meters');
  }
  const angle = normalizeAngle(rawAngle);
  let signal = cardioidPickup(angle);
  signal *= distanceFactor(distance);
  if (isInRejectionNull(angle)) {
    // keep only a fifth of what is left when the source sits behind the capsule
    signal *= 0.2;
  }
  if (highPass && distance < 0.5) {
    // the filter trims the bass boost that close-miking introduces
    signal *= 0.9;
  }
  return clampPercentage(signal);
}

function describe(source) {
  const [angle, distance, highPass] = source;
  const strength = attenuate(source).toFixed(2);
  // pad the columns so the driver output lines up as a readable table
  const bearing = String(angle).padStart(5);
  const range = distance.toFixed(2).padStart(6);
  const filter = highPass ? 'HPF on ' : 'HPF off';
  return `${bearing}deg ${range}m ${filter} -> ${strength}%`;
}

const measurements = [
  [0, 1, false],
  [90, 0.25, true],
  [90, 0.25, false],
  [180, 2, false],
  [170, 0.4, true],
  [-45, 3, false],
];

// report every measurement, then flag the strongest pickup of the session
const report = measurements.map(describe);
report.forEach((line) => console.log(line));
const best = measurements.reduce((a, b) => (attenuate(b) > attenuate(a) ? b : a));
console.log(`strongest: ${describe(best)}`);

