// Pasta extruder pressure calculator.
//
// A dough spec is [hydrationPercent, semolinaGradeScore, dieComplexity].

const BASE_PRESSURE = 100;
const TARGET_HYDRATION = 30;
const MAX_PRESSURE = 150;

// Only these two complexity labels change the pressure; anything else is neutral.
const COMPLEXITY_FACTORS = {
  high: 1.2,
  simple: 0.9
};

function parseDough(dough) {
  if (!Array.isArray(dough) || dough.length !== 3) {
    throw new TypeError('dough must be [hydration, grade, complexity]');
  }
  const [hydration, grade, complexity] = dough;
  // Hydration and grade arrive from operator input, so they may be numeric strings.
  const hydrationNum = Number(hydration);
  const gradeNum = Number(grade);
  if (!Number.isFinite(hydrationNum) || !Number.isFinite(gradeNum)) {
    throw new TypeError('hydration and semolina grade must be numbers');
  }
  if (typeof complexity !== 'string') {
    throw new TypeError('die complexity must be a string');
  }
  return { hydration: hydrationNum, grade: gradeNum, complexity: complexity.trim().toLowerCase() };
}

function hydrationAdjustment(hydration) {
  const delta = hydration - TARGET_HYDRATION;
  // Dry dough resists the die (+5/point); wet dough flows more easily (-3/point).
  return delta < 0 ? -delta * 5 : -delta * 3;
}

function extrude(dough) {
  const { hydration, grade, complexity } = parseDough(dough);
  let pressure = BASE_PRESSURE + hydrationAdjustment(hydration);
  if (grade > 7) {
    // Coarse semolina needs extra force to pass the die plate.
    pressure += 12;
  }
  pressure *= COMPLEXITY_FACTORS[complexity] ?? 1;
  // Hard mechanical limit of the extruder head.
  return Math.round(Math.min(pressure, MAX_PRESSURE));
}

function describeRun(name, dough) {
  const pressure = extrude(dough);
  const [hydration, grade, complexity] = dough;
  const capped = pressure === MAX_PRESSURE ? ' (capped)' : '';
  return `${name.padEnd(10)} ${hydration}% / grade ${grade} / ${complexity} -> ${pressure} bar${capped}`;
}

const batches = [
  ['fusilli', [28, 8, 'high']],
  ['spaghetti', [35, 5, 'simple']],
  ['penne', [30, 6, 'medium']],
  ['bucatini', [22, 9, 'high']],
  // Hydration given as a string, as the shop-floor terminal reports it.
  ['orzo', ['31.5', 7, 'simple']]
];

for (const [name, dough] of batches) {
  console.log(describeRun(name, dough));
}

// The driver above only reports; the module itself is the reusable part.
module.exports = { extrude, describeRun };

