const PANEL_COVERAGE = 0.72;

/* Fraction of the panel budget dedicated to the ceiling, as stated by the task */
const CEILING_SHARE = 0.3;
const WALL_COUNT = 4;

function parseRoom(room) {
  /*: the room description must be a 4-element list before any arithmetic happens */
  if (!Array.isArray(room) || room.length !== 4) {
    throw new TypeError('treat() expects [length, width, height, absorptionTarget]');
  }
  const [length, width, height, target] = room.map(Number);
  /*: NaN slips through Number() silently, so reject non-numeric entries explicitly */
  if ([length, width, height, target].some((value) => !Number.isFinite(value))) {
    throw new TypeError('room dimensions and absorption target must be numbers');
  }
  if (length <= 0 || width <= 0 || height <= 0) {
    throw new RangeError('room dimensions must be positive');
  }
  /*: an absorption target is a percentage, so it is bounded by 0 and 100 */
  if (target < 0 || target > 100) {
    throw new RangeError('absorption target must be between 0 and 100');
  }
  return { length, width, height, target };
}

function surfaceArea({ length, width, height }) {
  /* Four walls come in two opposing pairs; the floor is left untreated */
  const walls = 2 * (length + width) * height;
  const ceiling = length * width;
  return walls + ceiling;
}

function panelsRequired(area, target) {
  /*: the target is expressed in percent, so scale it down before applying it */
  const coverage = area * (target / 100);
  return coverage / PANEL_COVERAGE;
}

function treat(room) {
  const dimensions = parseRoom(room);
  const total = panelsRequired(surfaceArea(dimensions), dimensions.target);
  const ceilingPanels = total * CEILING_SHARE;
  /*: the remaining 70 % is shared evenly, so one wall gets a quarter of it */
  const perWallPanels = (total * (1 - CEILING_SHARE)) / WALL_COUNT;
  /* Panels cannot be cut, so partial panels always round up */
  return [Math.ceil(ceilingPanels), Math.ceil(perWallPanels)];
}

function describeTreatment(room) {
  const [ceiling, wall] = treat(room);
  const [length, width, height, target] = room;
  /*: report the full wall order too, since that is what gets purchased */
  const totalPanels = ceiling + wall * WALL_COUNT;
  return (
    `${length}x${width}x${height} m at ${target}% absorption -> ` +
    `${ceiling} ceiling panels, ${wall} per wall (${totalPanels} total)`
  );
}

const rooms = [
  [5, 4, 2.5, 25],
  [8, 6, 3, 40],
  [3, 3, 2.4, 15],
];

/*: print one line per studio so the quotes can be compared side by side */
for (const room of rooms) {
  console.log(describeTreatment(room));
}

module.exports = { treat, describeTreatment, surfaceArea, panelsRequired };

