const BRICK_FACE_AREA = 0.017;   // m² of one stretcher face, including its share of joints
const BRICK_LENGTH = 0.215;      // m
const BRICK_DEPTH = 0.102;       // m
const JOINTS_PER_BRICK = 2;      // every brick carries one bed joint and one head joint
const MORTAR_DENSITY = 1800;     // kg of dry mix per m³ of finished mortar
const WASTE_FACTOR = 1.1;        // 10 % allowance for spillage and mixing losses
const BAG_WEIGHT = 25;           // kg, the usual bagged size of ready-mixed dry mortar

// The wall descriptor is a 3-element list: [length m, height m, joint mm].
function parseWall(wall) {
  if (!Array.isArray(wall) || wall.length !== 3) {
    throw new TypeError('wall must be a list of [length, height, joint]');
  }
  const [length, height, joint] = wall.map(Number);
  // Negative or non-numeric input would silently produce a nonsense weight.
  if (![length, height, joint].every((v) => Number.isFinite(v) && v > 0)) {
    throw new RangeError('length, height and joint thickness must be positive numbers');
  }
  return { length, height, joint };
}

function wallArea(length, height) {
  return length * height;
}

function brickCount(area) {
  // Bricks are laid as whole units, so the raw quotient is rounded up.
  return Math.ceil(area / BRICK_FACE_AREA);
}

function mortarPerBrick(jointMm) {
  const jointM = jointMm / 1000;   // millimetres are the trade unit for joints
  const oneJoint = BRICK_LENGTH * BRICK_DEPTH * jointM;
  return oneJoint * JOINTS_PER_BRICK;
}

function calculate(wall) {
  const { length, height, joint } = parseWall(wall);
  const area = wallArea(length, height);
  const bricks = brickCount(area);
  // Total wet mortar volume for the bed and head joints of every brick.
  const wetVolume = mortarPerBrick(joint) * bricks;
  const dryWeight = wetVolume * MORTAR_DENSITY * WASTE_FACTOR;
  return Math.round(dryWeight);
}

function describe(wall) {
  const { length, height, joint } = parseWall(wall);
  const area = wallArea(length, height);
  const kg = calculate(wall);
  const bags = Math.ceil(kg / BAG_WEIGHT);
  return [
    `${length} m x ${height} m wall (${area.toFixed(2)} m²), ${joint} mm joints`,
    `  bricks:   ${brickCount(area)}`,
    `  dry mix:  ${kg} kg`,
    `  bags:     ${bags} x ${BAG_WEIGHT} kg`,
  ].join('\n');
}

function main() {
  const walls = [
    [10, 2.5, 10],
    [4, 2.4, 12],
    [12.5, 3, 8],
  ];
  for (const wall of walls) {
    console.log(describe(wall));
  }
  // A single figure for the whole job makes ordering material easier.
  const total = walls.reduce((sum, wall) => sum + calculate(wall), 0);
  console.log(`Total for ${walls.length} walls: ${total} kg`);
}

main();

module.exports = { calculate, describe, brickCount, mortarPerBrick };

