// Generator sizing helper: computes the minimum capacity needed to run a set of
// appliances continuously, including startup surge, heat derating and margin.

const SURGE_MULTIPLIER = 1.5;
const DERATE_TEMPERATURE_C = 35;
const DERATE_FACTOR = 1.1;
const SAFETY_MARGIN = 1.2;

function parseInputs(inputs) {
  if (!Array.isArray(inputs) || inputs.length < 2) {
    throw new TypeError('size() expects [wattages, ambientTemperature]');
  }
  const [wattages, ambientC] = inputs;
  if (!Array.isArray(wattages) || wattages.length === 0) {
    // Without at least one appliance there is no load to size a generator for.
    throw new TypeError('the first element must be a non-empty array of wattages');
  }
  const loads = wattages.map((w) => {
    const value = Number(w);
    if (!Number.isFinite(value) || value < 0) {
      throw new RangeError(`invalid appliance wattage: ${w}`);
    }
    return value;
  });
  const temperature = Number(ambientC);
  if (!Number.isFinite(temperature)) {
    throw new RangeError(`invalid ambient temperature: ${ambientC}`);
  }
  return { loads, temperature };
}

// The base load is everything drawing power at the same time.
function baseLoad(loads) {
  return loads.reduce((sum, watts) => sum + watts, 0);
}

// Only the largest motor's inrush matters; appliances rarely start together.
function startingSurge(loads) {
  return Math.max(...loads) * SURGE_MULTIPLIER;
}

function temperatureDerate(watts, ambientC) {
  // Hot intake air costs engine output, so ask for more capacity above 35 C.
  return ambientC > DERATE_TEMPERATURE_C ? watts * DERATE_FACTOR : watts;
}

function roundUpToHundred(watts) {
  return Math.ceil(watts / 100) * 100;
}

function size(inputs) {
  const { loads, temperature } = parseInputs(inputs);
  const running = baseLoad(loads);
  // Startup spike rides on top of the continuous draw of the other appliances.
  const withSurge = running + startingSurge(loads);
  const derated = temperatureDerate(withSurge, temperature);
  // The final 20 % keeps the set off its maximum load rating in service.
  return roundUpToHundred(derated * SAFETY_MARGIN);
}

function describeSizing(inputs) {
  const { loads, temperature } = parseInputs(inputs);
  const required = size(inputs);
  const parts = [
    `appliances: ${loads.length}`,
    `base load: ${baseLoad(loads)} W`,
    `largest surge: ${startingSurge(loads)} W`,
    `ambient: ${temperature} C`,
  ];
  // Flag the derating so the reader knows why a hot site needs a bigger unit.
  if (temperature > DERATE_TEMPERATURE_C) parts.push('derated for heat');
  return `${parts.join(', ')} -> ${required} W generator`;
}

function main() {
  const jobs = [
    [[1200, 800, 450, 150], 22],
    [[2500, 1800, 600], 41],
    [[95], 35],
  ];
  // Print one sizing report per site survey.
  for (const job of jobs) console.log(describeSizing(job));
}

main();

module.exports = { size, describeSizing };

