const EVENTS = [
  // track events are scored on elapsed time, so the formula uses (B - performance)
  { name: 'Hundred Meter Dash', track: true, a: 25.4347, b: 18, c: 1.81, scale: 1, unit: 's' },
  // jump distances arrive in metres but the official constants are calibrated for centimetres
  { name: 'Long Jump', track: false, a: 0.14354, b: 220, c: 1.4, scale: 100, unit: 'm' },
  { name: 'Shot Put', track: false, a: 51.39, b: 1.5, c: 1.05, scale: 1, unit: 'm' },
  { name: 'High Jump', track: false, a: 0.8465, b: 75, c: 1.42, scale: 100, unit: 'm' },
  { name: 'Four Hundred Meter Dash', track: true, a: 1.53775, b: 82, c: 1.81, scale: 1, unit: 's' },
  { name: 'Hurdles', track: true, a: 5.74352, b: 28.5, c: 1.92, scale: 1, unit: 's' },
  { name: 'Discus Throw', track: false, a: 12.91, b: 4, c: 1.1, scale: 1, unit: 'm' },
  { name: 'Pole Vault', track: false, a: 0.2797, b: 100, c: 1.35, scale: 100, unit: 'm' },
  { name: 'Javelin Throw', track: false, a: 10.14, b: 7, c: 1.08, scale: 1, unit: 'm' },
  { name: 'Fifteen Hundred Meter Run', track: true, a: 0.03768, b: 480, c: 1.85, scale: 1, unit: 's' }
];

function eventPoints(event, performance) {
  const value = performance * event.scale;
  // the sign of the difference is what distinguishes the two families of formulas
  const difference = event.track ? event.b - value : value - event.b;
  if (difference <= 0) {
    // performances at or below the event's baseline earn nothing, and would make Math.pow return NaN
    return 0;
  }
  // points are always truncated towards zero before being added to the total
  return Math.floor(event.a * Math.pow(difference, event.c));
}

function validate(results) {
  if (!Array.isArray(results) || results.length !== EVENTS.length) {
    throw new TypeError(`expected ${EVENTS.length} results, got ${Array.isArray(results) ? results.length : typeof results}`);
  }
  results.forEach((performance, index) => {
    // a missing or negative mark cannot be scored, so refuse it instead of returning garbage
    if (typeof performance !== 'number' || !Number.isFinite(performance) || performance < 0) {
      throw new RangeError(`invalid performance for ${EVENTS[index].name}: ${performance}`);
    }
  });
}

function score(results) {
  validate(results);
  // the decathlon total is simply the sum of the ten individual event scores
  return EVENTS.reduce((total, event, index) => total + eventPoints(event, results[index]), 0);
}

function breakdown(results) {
  validate(results);
  return EVENTS.map((event, index) => ({
    event: event.name,
    performance: `${results[index]} ${event.unit}`,
    points: eventPoints(event, results[index])
  }));
}

function formatReport(results) {
  const rows = breakdown(results);
  // pad the columns so the report lines up regardless of the longest event name
  const width = rows.reduce((longest, row) => Math.max(longest, row.event.length), 0);
  const lines = rows.map(row =>
    `${row.event.padEnd(width)}  ${row.performance.padStart(10)}  ${String(row.points).padStart(5)}`
  );
  // the footer repeats the grand total returned by score()
  lines.push(`${'TOTAL'.padEnd(width)}  ${''.padStart(10)}  ${String(score(results)).padStart(5)}`);
  return lines.join('\n');
}

function main() {
  // each of these marks is worth roughly 500 points, so the decathlete lands near 5000
  const averageTarget = [12.82, 5.59, 10.23, 1.645, 57.57, 18.26, 31.78, 3.566, 43.95, 310.6];
  console.log(formatReport(averageTarget));
}

main();

module.exports = { score, breakdown, formatReport };

