// Fahrenheit thresholds, lowest first; each entry is the smallest reading
// that still counts as that stage
const STAGES = [
  { min: -Infinity, name: 'plain syrup' },
  { min: 230, name: 'thread stage' },
  { min: 235, name: 'soft ball' },
  { min: 244, name: 'firm ball' },
  { min: 250, name: 'hard ball' },
  { min: 270, name: 'soft crack' },
  { min: 300, name: 'hard crack' },
];

// caramel is reached only above this mark, so 320 itself is not yet caramel
const CARAMEL_MIN = 320;

const MAX_ALLOWED_DROP = 10;

// the spec leaves small gaps (240-244, 266-270, 290-300, 310-320); a reading
// inside a gap has not climbed into the next stage yet, so it keeps the previous one
function stageFor(temp) {
  if (temp > CARAMEL_MIN) return 'caramel';
  let current = STAGES[0].name;
  for (const stage of STAGES) {
    if (temp >= stage.min) current = stage.name;
  }
  return current;
}

function analyze(temperatures) {
  if (!Array.isArray(temperatures) || temperatures.length === 0) {
    return 'no temperature readings supplied';
  }

  let max = -Infinity;
  let previous = null;

  for (const reading of temperatures) {
    // a stray null or unparsed sensor value would silently poison the maximum
    if (typeof reading !== 'number' || Number.isNaN(reading)) {
      return 'invalid temperature reading';
    }
    // cooling only ruins the batch while the sugar has not passed the caramel mark
    if (previous !== null && max <= CARAMEL_MIN && previous - reading > MAX_ALLOWED_DROP) {
      return 'batch ruined: temperature dropped more than 10 degrees';
    }
    if (reading > max) max = reading;
    previous = reading;
  }

  return stageFor(max);
}

// short textual report used by the driver below
function describeBatch(label, temperatures) {
  const peak = temperatures.reduce((a, b) => (b > a ? b : a), -Infinity);
  return `${label}: peak ${peak}F -> ${analyze(temperatures)}`;
}

function main() {
  const batches = [
    ['morning syrup', [180, 195, 210, 228]],
    ['fudge', [200, 231, 236, 239]],
    ['divinity', [240, 252, 260, 265]],
    ['lollipops', [250, 280, 302, 308]],
    ['caramel sauce', [260, 300, 325, 300]],
    ['spilled pan', [230, 246, 228]],
  ];

  for (const [label, readings] of batches) {
    console.log(describeBatch(label, readings));
  }
}

main();

