const FEET_TO_METRES = 0.3048;

// the spread closes at 2 °C per 1000 ft: 2.5 °C ambient lapse minus 0.5 °C dew point lapse
const SPREAD_CONVERGENCE_PER_FOOT = 2 / 1000;

function parseConditions(conditions) {
  if (!Array.isArray(conditions) || conditions.length !== 3) {
    throw new TypeError('conditions must be [temperature, dewPoint, elevation]');
  }
  const [temperature, dewPoint, elevation] = conditions.map(Number);
  // a single NaN anywhere would silently poison the whole computation
  if ([temperature, dewPoint, elevation].some((value) => !Number.isFinite(value))) {
    throw new TypeError('temperature, dew point and elevation must all be finite numbers');
  }
  // saturated or super-saturated air has no lifting condensation level above the station
  if (dewPoint > temperature) {
    throw new RangeError('dew point cannot exceed the surface temperature');
  }
  return { temperature, dewPoint, elevation };
}

function spread(temperature, dewPoint) {
  return temperature - dewPoint;
}

function convergenceHeightFeet(temperatureSpread) {
  // height AGL in feet at which the converging spread reaches exactly zero
  return temperatureSpread / SPREAD_CONVERGENCE_PER_FOOT;
}

function ceiling(conditions) {
  const { temperature, dewPoint, elevation } = parseConditions(conditions);
  const heightAgl = convergenceHeightFeet(spread(temperature, dewPoint));
  // the cloud base is reported as an absolute elevation, so the station height is added back
  return Math.round(heightAgl * FEET_TO_METRES + elevation);
}

