  const { temperature, dewPoint, elevation } = parseConditions(conditions);
  const base = ceiling(conditions);
  const agl = cloudBaseAgl(conditions);
  return `${name}: ${temperature}/${dewPoint} °C at ${elevation} m -> base ${base} m MSL (${agl} m AGL)`;
}

