// Engine displacement calculator: works from bore/stroke in millimetres.

const MM_PER_CM = 10;
const CC_PER_LITRE = 1000;

// Reject anything that is not a triple of finite, usable numbers.
function validate(specs) {
  if (!Array.isArray(specs) || specs.length !== 3) {
    throw new TypeError('specs must be [bore_mm, stroke_mm, cylinders]');
  }
  const [bore, stroke, cylinders] = specs;
  for (const value of [bore, stroke, cylinders]) {
    if (typeof value !== 'number' || !Number.isFinite(value) || value <= 0) {
      throw new RangeError('bore, stroke and cylinder count must be positive numbers');
    }
  }
  // A block cannot be built from a fractional number of cylinders.
  if (!Number.isInteger(cylinders)) {
    throw new RangeError('cylinder count must be a whole number');
  }
  return { bore, stroke, cylinders };
}

function measure(specs) {
  const { bore, stroke, cylinders } = validate(specs);

  // Convert both linear dimensions from millimetres to centimetres.
  const boreCm = bore / MM_PER_CM;
  const strokeCm = stroke / MM_PER_CM;

  const radius = boreCm / 2;
  // Swept volume of one cylinder: a right circular cylinder of height = stroke.
  const singleCylinder = Math.PI * radius * radius * strokeCm;

  const totalCc = singleCylinder * cylinders;
  const litres = totalCc / CC_PER_LITRE;

  // Litres are reported to one decimal, cubic centimetres to the nearest unit.
  return [Math.round(totalCc), Number(litres.toFixed(1))];
}

// Marketing badges are written as e.g. "2.0L", so keep the trailing zero.
function badge(litres) {
  return `${litres.toFixed(1)}L`;
}

function describe(name, specs) {
  const [cc, litres] = measure(specs);
  const [bore, stroke, cylinders] = specs;
  // Square, oversquare and undersquare are decided by the bore/stroke ratio.
  let geometry;
  if (bore > stroke) {
    geometry = 'oversquare';
  } else if (bore < stroke) {
    geometry = 'undersquare';
  } else {
    geometry = 'square';
  }
  return `${name}: ${cylinders} cyl, ${bore}x${stroke}mm ${geometry}, ${cc} cc (${badge(litres)})`;
}

function main() {
  const catalogue = [
    ['Honda B16A', [81, 77.4, 4]],
    ['Chevrolet LS3', [103.25, 92, 8]],
    ['Ford EcoBoost I3', [71.9, 82, 3]],
  ];

  for (const [name, specs] of catalogue) {
    console.log(describe(name, specs));
  }

  // Surface bad catalogue data instead of printing a nonsense displacement.
  try {
    measure([86, 86, 4.5]);
  } catch (err) {
    console.log(`rejected: ${err.message}`);
  }
}

main();

module.exports = { measure, describe, badge };

