const ENCOUNTER_RATE = 0.01;
const CONVERSION_EFFICIENCY = 0.005;

// A state is well formed only if it is a list of exactly four finite numbers
function validateState(state) {
  if (!Array.isArray(state) || state.length !== 4) {
    throw new TypeError('simulate expects a list of exactly four numbers');
  }
  for (const value of state) {
    // Population sizes and rates must be usable in arithmetic, so reject NaN and Infinity too
    if (typeof value !== 'number' || !Number.isFinite(value)) {
      throw new TypeError(`invalid state component: ${value}`);
    }
  }
  const [prey, predators] = state;
  // Negative head counts are biologically meaningless and would corrupt the growth terms
  if (prey < 0 || predators < 0) {
    throw new RangeError('populations cannot start below zero');
  }
}

// Raw Lotka-Volterra increments: exponential growth minus (or plus) the predation coupling
function rawChanges(prey, predators, birthRate, deathRate) {
  const encounters = ENCOUNTER_RATE * prey * predators;
  const preyChange = birthRate * prey - encounters;
  // Only a small fraction of eaten prey becomes new predator biomass
  const predatorChange = CONVERSION_EFFICIENCY * encounters - deathRate * predators;
  return [preyChange, predatorChange];
}

// Populations are whole creatures, and extinction is a floor rather than a negative number
function settle(population) {
  return Math.max(0, Math.round(population));
}

function simulate(state) {
  validateState(state);
  const [prey, predators, birthRate, deathRate] = state;
  const [preyChange, predatorChange] = rawChanges(prey, predators, birthRate, deathRate);
  return [settle(prey + preyChange), settle(predators + predatorChange)];
}

// Run the model forward, collecting every intermediate generation for reporting
function runGenerations(state, generations) {
  const [, , birthRate, deathRate] = state;
  const history = [[settle(state[0]), settle(state[1])]];
  let current = state;
  for (let g = 0; g < generations; g += 1) {
    const [nextPrey, nextPredators] = simulate(current);
    history.push([nextPrey, nextPredators]);
    // The rates are inherent to the species, so they carry over unchanged
    current = [nextPrey, nextPredators, birthRate, deathRate];
  }
  return history;
}

function formatHistory(history) {
  return history
    .map(([prey, predators], generation) => {
      // Flag the moment a group dies out, since the model can never bring it back
      const note = prey === 0 || predators === 0 ? '  <- collapse' : '';
      return `gen ${String(generation).padStart(2)}: prey=${prey}, predators=${predators}${note}`;
    })
    .join('\n');
}

function main() {
  const initial = [1000, 20, 0.1, 0.05];
  console.log(`one generation: ${JSON.stringify(simulate(initial))}`);
  console.log(formatHistory(runGenerations(initial, 8)));
  // A tiny prey pool cannot sustain the predators, which should starve away
  console.log(formatHistory(runGenerations([5, 40, 0.1, 0.5], 4)));
}

main();

module.exports = { simulate, runGenerations, formatHistory };

