const WASTE_FACTOR = 1.15;
const LOCKSTITCH_SOURCES = 2;

// A garment is described by three positive numbers, so anything else is a measurement error
function validateGarment(garment) {
  if (!Array.isArray(garment) || garment.length !== 3) {
    throw new TypeError('garment must be [seamMeters, stitchMillimeters, thicknessMillimeters]');
  }
  const [seam, stitch, thickness] = garment;
  for (const value of [seam, stitch, thickness]) {
    // NaN, strings and negative measurements cannot describe a real piece of cloth
    if (typeof value !== 'number' || !Number.isFinite(value) || value < 0) {
      throw new RangeError(`invalid measurement: ${value}`);
    }
  }
  // A zero stitch length would ask for infinitely many stitches
  if (stitch === 0) {
    throw new RangeError('stitch length must be greater than zero');
  }
  return { seam, stitch, thickness };
}

// One stitch goes down and up through the fabric, hence both terms are doubled
function threadPerStitch(stitchMm, thicknessMm) {
  const millimeters = 2 * stitchMm + 2 * thicknessMm;
  return millimeters / 1000;
}

function stitchCount(seamMeters, stitchMm) {
  const stitchMeters = stitchMm / 1000;
  return seamMeters / stitchMeters;
}

function measure(garment) {
  const { seam, stitch, thickness } = validateGarment(garment);
  const perStitch = threadPerStitch(stitch, thickness);
  const stitches = stitchCount(seam, stitch);
  const bare = stitches * perStitch;
  // Snags and loose ends waste a fixed share of every spool
  const withWaste = bare * WASTE_FACTOR;
  // The top spool and the bottom bobbin each pay the full amount
  return Math.round(withWaste * LOCKSTITCH_SOURCES);
}

function describe(name, garment) {
  const meters = measure(garment);
  const [seam, stitch, thickness] = garment;
  // Spools are sold in hundreds of meters, so report how many to buy
  const spools = Math.ceil(meters / 100);
  return `${name}: ${seam} m of seam at ${stitch} mm stitch on ${thickness} mm cloth ` +
    `-> ${meters} m of thread (${spools} spool${spools === 1 ? '' : 's'})`;
}

function main() {
  const orders = [
    ['linen shirt', [12.5, 2.5, 0.4]],
    ['wool overcoat', [48, 3, 2.2]],
    ['silk lining', [9, 1.8, 0.15]],
  ];
  for (const [name, garment] of orders) {
    console.log(describe(name, garment));
  }
  const total = orders.reduce((sum, [, garment]) => sum + measure(garment), 0);
  console.log(`workshop total: ${total} m`);
  try {
    measure([10, 0, 1]);
  } catch (err) {
    // Reject the faulty order instead of letting a division by zero reach the invoice
    console.log(`rejected order: ${err.message}`);
  }
}

main();

module.exports = { measure, threadPerStitch, stitchCount, describe };

