// Titration helper: computes the titrant volume needed to neutralize an acid sample.

// Each sample is described by [acidVolume (mL), acidConcentration (M), baseConcentration (M)].
function validateSample(sample) {
  if (!Array.isArray(sample) || sample.length !== 3) {
    throw new TypeError('sample must be a list of exactly three numbers');
  }
  const labels = ['acid volume', 'acid concentration', 'base concentration'];
  for (let i = 0; i < sample.length; i += 1) {
    const value = sample[i];
    if (typeof value !== 'number' || !Number.isFinite(value)) {
      throw new TypeError(`${labels[i]} must be a finite number`);
    }
    // Negative volumes or concentrations have no physical meaning in a titration.
    if (value < 0) {
      throw new RangeError(`${labels[i]} cannot be negative`);
    }
  }
  // A base of zero concentration can never neutralize the acid, so the division would diverge.
  if (sample[2] === 0) {
    throw new RangeError('base concentration must be greater than zero');
  }
  return sample;
}

// Working in mL x mol/L yields millimoles, which keeps the final answer in millilitres.
function acidMillimoles(acidVolume, acidConcentration) {
  return acidVolume * acidConcentration;
}

function neutralize(sample) {
  const [acidVolume, acidConcentration, baseConcentration] = validateSample(sample);
  const acidMoles = acidMillimoles(acidVolume, acidConcentration);
  // Perfect 1:1 stoichiometry means the base supplies exactly as many moles as the acid holds.
  const baseMoles = acidMoles;
  const baseVolume = baseMoles / baseConcentration;
  return Math.round(baseVolume * 100) / 100;
}

// Reports are padded so a batch of runs lines up as a readable column.
function describeTitration(sample) {
  const volume = neutralize(sample);
  const [acidVolume, acidConcentration, baseConcentration] = sample;
  const left = `${acidVolume.toFixed(1)} mL of ${acidConcentration.toFixed(2)} M acid`;
  const right = `${baseConcentration.toFixed(2)} M base`;
  return `${left.padEnd(32)} needs ${volume.toFixed(2).padStart(7)} mL of ${right}`;
}

function main() {
  const batch = [
    [25, 1, 1],
    [50, 0.5, 0.25],
    [10, 2.5, 0.75],
    [35.5, 0.125, 0.1],
  ];
  for (const sample of batch) {
    console.log(describeTitration(sample));
  }

  // A malformed entry should surface as a clear message instead of a silent NaN.
  try {
    neutralize([25, 1, 0]);
  } catch (err) {
    console.log(`rejected: ${err.message}`);
  }
}

// Only run the driver when executed directly, so the functions stay importable.
if (require.main === module) {
  main();
}

module.exports = { neutralize, describeTitration, validateSample };

