//  Single-lane roundabout entry capacity estimator (HCM-style exponential decay model).

const BASE_CAPACITY = 1600;
const CIRCULATING_DECAY = -0.004;
const REFERENCE_LANE_WIDTH = 4;
const WIDTH_BONUS_PER_METER = 0.10;
const MIN_COMFORTABLE_DIAMETER = 30;
const TIGHT_GEOMETRY_PENALTY = 0.15;

// The three geometry/traffic inputs arrive as a positional list, so name them here.
function parseIntersection(intersection) {
  if (!Array.isArray(intersection) || intersection.length < 3) {
    throw new TypeError('intersection must be [diameter, entryWidth, circulatingVolume]');
  }
  const [diameter, entryWidth, circulatingVolume] = intersection.map(Number);
  // Negative or non-numeric geometry would silently produce a plausible-looking capacity.
  if ([diameter, entryWidth, circulatingVolume].some((v) => !Number.isFinite(v) || v < 0)) {
    throw new RangeError('diameter, entry width and circulating volume must be non-negative numbers');
  }
  return { diameter, entryWidth, circulatingVolume };
}

// Conflicting circulating flow suppresses entry capacity exponentially.
function baselineCapacity(circulatingVolume) {
  return BASE_CAPACITY * Math.exp(CIRCULATING_DECAY * circulatingVolume);
}

// Wide entries let drivers accept shorter gaps: +10% per extra metre beyond 4 m.
function widthFactor(entryWidth) {
  if (entryWidth <= REFERENCE_LANE_WIDTH) {
    return 1;
  }
  const extraMeters = entryWidth - REFERENCE_LANE_WIDTH;
  return 1 + WIDTH_BONUS_PER_METER * extraMeters;
}

// Small inscribed circles force sharp deflection angles and slower entries.
function diameterFactor(diameter) {
  return diameter < MIN_COMFORTABLE_DIAMETER ? 1 - TIGHT_GEOMETRY_PENALTY : 1;
}

function predict(intersection) {
  const { diameter, entryWidth, circulatingVolume } = parseIntersection(intersection);
  let capacity = baselineCapacity(circulatingVolume);
  capacity *= widthFactor(entryWidth);
  capacity *= diameterFactor(diameter);
  // Capacity is reported in whole vehicles per hour.
  return Math.round(capacity);
}

// Human-readable line for a survey of candidate roundabout designs.
function describe(intersection) {
  const { diameter, entryWidth, circulatingVolume } = parseIntersection(intersection);
  const capacity = predict(intersection);
  const notes = [];
  if (entryWidth > REFERENCE_LANE_WIDTH) {
    notes.push('wide entry bonus');
  }
  if (diameter < MIN_COMFORTABLE_DIAMETER) {
    notes.push('tight geometry penalty');
  }
  // Without modifiers the baseline stands on its own, so say so explicitly.
  const suffix = notes.length ? ` (${notes.join(', ')})` : ' (baseline geometry)';
  return `D=${diameter}m W=${entryWidth}m Qc=${circulatingVolume}veh/h -> ${capacity} veh/h${suffix}`;
}

function main() {
  const designs = [
    [45, 4.0, 300],
    [38, 5.5, 500],
    [26, 3.5, 200],
    [28, 6.0, 900],
  ];
  designs.forEach((design) => console.log(describe(design)));
  // Rank the designs so the highest-throughput option is easy to spot.
  const best = designs.reduce((a, b) => (predict(b) > predict(a) ? b : a));
  console.log(`Best option: diameter ${best[0]}m with ${predict(best)} veh/h`);
}

main();

module.exports = { predict, describe };

