//: Structural design snow load for sloped residential roofs (ASCE-style reduction).

const FLAT_ROOF_COEFFICIENT = 0.7;
const SLOPE_THRESHOLD_DEG = 15;
const SHED_THRESHOLD_DEG = 70;
const SLOPE_DENOMINATOR = 55;

// Reject anything that is not four usable numbers before any arithmetic happens.
function parseStructure(structure) {
  if (!Array.isArray(structure) || structure.length !== 4) {
    throw new TypeError('structure must be a list of four numbers');
  }
  const values = structure.map(Number);
  // NaN slips through Number() for garbage input, so screen the converted values.
  if (values.some((value) => !Number.isFinite(value))) {
    throw new TypeError('structure must contain only finite numeric values');
  }
  const [groundLoad, angle, thermalFactor, exposureFactor] = values;
  if (groundLoad < 0) {
    throw new RangeError('ground snow load cannot be negative');
  }
  // A roof plane beyond vertical is not a roof; the pitch has to stay in the first quadrant.
  if (angle < 0 || angle > 90) {
    throw new RangeError('roof pitch must be between 0 and 90 degrees');
  }
  return { groundLoad, angle, thermalFactor, exposureFactor };
}

// Flat roof baseline: 0.7 * ground load * exposure * thermal.
function flatRoofLoad({ groundLoad, thermalFactor, exposureFactor }) {
  return FLAT_ROOF_COEFFICIENT * groundLoad * exposureFactor * thermalFactor;
}

function slopeFactor(angle) {
  if (angle < SLOPE_THRESHOLD_DEG) {
    // Shallow pitches hold the full drift, so nothing is shaved off.
    return 1;
  }
  if (angle > SHED_THRESHOLD_DEG) {
    // Steeper than 70 degrees: the snow slides away entirely.
    return 0;
  }
  return (SHED_THRESHOLD_DEG - angle) / SLOPE_DENOMINATOR;
}

function evaluate(structure) {
  const parsed = parseStructure(structure);
  const slopedLoad = flatRoofLoad(parsed) * slopeFactor(parsed.angle);
  // Two decimals is the reporting precision for design loads in kPa.
  return Math.round(slopedLoad * 100) / 100;
}

function describe(structure) {
  const { groundLoad, angle } = parseStructure(structure);
  const load = evaluate(structure);
  // Zero load means the roof sheds completely; call that out instead of printing "0.00 kPa" alone.
  const note = load === 0 && angle > SHED_THRESHOLD_DEG ? ' (snow sheds fully)' : '';
  return `${groundLoad.toFixed(2)} kPa ground @ ${angle}deg -> ${load.toFixed(2)} kPa${note}`;
}

function main() {
  const roofs = [
    [1.5, 10, 1.0, 1.0],
    [2.0, 30, 1.1, 0.9],
    [2.4, 70, 1.0, 1.0],
    [3.0, 75, 1.2, 1.0],
  ];
  roofs.forEach((roof) => console.log(describe(roof)));
  try {
    // Confirm the validation layer refuses a malformed structure list.
    evaluate([1.5, 30, 1.0]);
  } catch (err) {
    console.log(`rejected: ${err.message}`);
  }
}

main();

module.exports = { evaluate, describe, flatRoofLoad, slopeFactor };

