const ALPHABET = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ';

// Reduce arbitrary input to the cipher alphabet: uppercase, letters only
function sanitize(text) {
  return String(text).toUpperCase().replace(/[^A-Z]/g, '');
}

// Stretch the keyword to the exact length of the message it has to align with
function repeatKey(key, length) {
  let stream = '';
  while (stream.length < length) {
    stream += key;
  }
  return stream.slice(0, length);
}

// Zero based position of a letter inside the 26 letter alphabet
function letterIndex(letter) {
  return ALPHABET.indexOf(letter);
}

function encrypt(data) {
  const [rawMessage, rawKey] = data;
  const message = sanitize(rawMessage);
  const key = sanitize(rawKey);

  // A keyword with no usable letters cannot drive the substitution at all
  if (key.length === 0) {
    throw new Error('encrypt: the keyword must contain at least one letter');
  }

  const stream = repeatKey(key, message.length);
  let cipher = '';

  for (let i = 0; i < message.length; i += 1) {
    let sum = letterIndex(message[i]) + letterIndex(stream[i]);

    // Wrap back into range instead of running off the end of the alphabet
    if (sum > 25) {
      sum -= 26;
    }

    cipher += ALPHABET[sum];
  }

  return cipher;
}

// Classic presentation of a cipher text: fixed width blocks of five letters
function groupInFives(cipher) {
  return (cipher.match(/.{1,5}/g) || []).join(' ');
}

function main() {
  const jobs = [
    ['Attack at dawn!', 'Lemon'],
    ['Beware the Jabberwock, my son!', 'Vigenere Cipher'],
    ['Meet me at 7 o clock, room 12', 'key']
  ];

  for (const job of jobs) {
    const cipher = encrypt(job);

    // Show what actually got enciphered, since punctuation and digits vanish
    console.log(`plain : ${sanitize(job[0])}`);
    console.log(`key   : ${repeatKey(sanitize(job[1]), cipher.length)}`);
    console.log(`cipher: ${groupInFives(cipher)}`);
    console.log('');
  }

  // Empty keywords are rejected rather than silently returning the plain text
  try {
    encrypt(['Hello there', '1234']);
  } catch (err) {
    console.log(`error : ${err.message}`);
  }
}

main();

