// Minimum angle of deviation for a ray of light crossing an equilateral glass prism.
// The apex angle is fixed at 60 degrees, so the half-angle used below is 30 degrees.

const APEX_ANGLE = 60;
const CAUCHY_B = 4000;

// Cauchy's equation is normally written with the wavelength in micrometres; here the
// coefficient B is given directly in nanometres squared, so no unit conversion occurs.
function cauchyIndex(baseIndex, wavelengthNm) {
  const a = baseIndex - 0.02;
  return a + CAUCHY_B / (wavelengthNm * wavelengthNm);
}

function toRadians(degrees) {
  return (degrees * Math.PI) / 180;
}

function toDegrees(radians) {
  return (radians * 180) / Math.PI;
}

// Snell's law at minimum deviation gives n * sin(A/2) = sin((A + D)/2).
function minimumDeviation(index) {
  const sineOfRefraction = index * Math.sin(toRadians(APEX_ANGLE / 2));
  // Total internal reflection: no ray emerges and the deviation is undefined.
  if (sineOfRefraction > 1) {
    throw new RangeError(`refractive index ${index} is too high for a 60 degree prism`);
  }
  const halfPath = toDegrees(Math.asin(sineOfRefraction));
  return 2 * halfPath - APEX_ANGLE;
}

function deflect(prism) {
  // The task hands the two parameters over as a single list.
  const [baseIndex, wavelengthNm] = prism;
  if (!(baseIndex > 0) || !(wavelengthNm > 0)) {
    throw new TypeError('prism expects a positive index and a positive wavelength');
  }
  const adjustedIndex = cauchyIndex(baseIndex, wavelengthNm);
  const deviation = minimumDeviation(adjustedIndex);
  // Rounding to two decimals is part of the required result.
  return Math.round(deviation * 100) / 100;
}

// Visible-light reference wavelengths used for the dispersion report.
const SPECTRUM = [
  ['red', 706.5],
  ['yellow', 587.6],
