// Circle geometry helpers: area computation, validation and a small report.

// Radii must be finite, non-negative numbers; anything else is a programming error.
function validateRadius(radius) {
  if (typeof radius !== 'number' || Number.isNaN(radius)) {
    throw new TypeError(`radius must be a number, got ${String(radius)}`);
  }
  // Infinity would silently produce an infinite area, so reject it explicitly.
  if (!Number.isFinite(radius)) {
    throw new RangeError('radius must be finite');
  }
  if (radius < 0) {
    throw new RangeError(`radius must be non-negative, got ${radius}`);
  }
  return radius;
}

function calculateCircleArea(radius) {
  const r = validateRadius(radius);
  // Math.PI * r * r keeps the exact double result for r = 1 (returns Math.PI).
  return Math.PI * r * r;
}

function calculateCircumference(radius) {
  const r = validateRadius(radius);
  return 2 * Math.PI * r;
}

// Inverse of the area formula, handy when a target area is known instead of a radius.
function radiusFromArea(area) {
  if (typeof area !== 'number' || !Number.isFinite(area) || area < 0) {
    throw new RangeError(`area must be a finite non-negative number, got ${String(area)}`);
  }
  return Math.sqrt(area / Math.PI);
}

// Area of a ring: the difference of two disc areas, outer radius first.
function calculateAnnulusArea(outerRadius, innerRadius) {
  const outer = validateRadius(outerRadius);
  const inner = validateRadius(innerRadius);
  if (inner > outer) {
    throw new RangeError('inner radius cannot exceed the outer radius');
  }
  return calculateCircleArea(outer) - calculateCircleArea(inner);
}

function formatNumber(value, decimals = 4) {
  // toFixed avoids exponential notation for the magnitudes used here.
  return value.toFixed(decimals);
}

function describeCircle(radius) {
  const area = calculateCircleArea(radius);
  const circumference = calculateCircumference(radius);
  return `r=${formatNumber(radius, 2)}  area=${formatNumber(area)}  perimeter=${formatNumber(circumference)}`;
}

function main() {
  const radii = [0, 1, 2, 2.5, 10];
  // One descriptive line per sample radius.
  for (const r of radii) {
    console.log(describeCircle(r));
  }

  // Sanity checks from the task statement, shown as exact multiples of Math.PI.
  console.log('area(1) === Math.PI       ->', calculateCircleArea(1) === Math.PI);
  console.log('area(2) === 4 * Math.PI   ->', calculateCircleArea(2) === 4 * Math.PI);

  const ring = calculateAnnulusArea(3, 1);
  console.log(`ring 1..3 area=${formatNumber(ring)}`);

  // Round-tripping an area back through radiusFromArea should recover the radius.
  console.log(`radius for area ${formatNumber(ring)} as a full disc = ${formatNumber(radiusFromArea(ring))}`);

  try {
    calculateCircleArea(-4);
  } catch (err) {
    // Negative radii are rejected rather than squared into a positive area.
    console.log(`rejected: ${err.message}`);
  }
}

main();

module.exports = {
  calculateCircleArea,
  calculateCircumference,
  calculateAnnulusArea,
  radiusFromArea,
  describeCircle,
};

