// Dice rolling utilities: a single-die roller plus a few helpers built on top of it.

// Validate the die description once, so rollDice itself stays a one-liner.
function assertValidSides(sides) {
  if (!Number.isInteger(sides)) {
    throw new TypeError(`sides must be an integer, got ${typeof sides}: ${sides}`);
  }
  // A die needs at least two distinct faces to be a die at all.
  if (sides < 2) {
    throw new RangeError(`sides must be at least 2, got ${sides}`);
  }
}

function rollDice(sides) {
  assertValidSides(sides);
  // Math.random() is in [0, 1), so flooring the scaled value gives 0..sides-1.
