function objectToKeyValueArray(obj) {
  const result = []; // Initialize an empty array to store the key-value pairs.

  // Handle the case where the input is not an object or is null.
  if (typeof obj !== 'object' || obj === null) {
    return result; // Return an empty array for invalid input.
  }

  // Iterate over the keys of the input object.
  for (const key in obj) {
    // Ensure the key belongs to the object itself, not its prototype chain.
    if (Object.prototype.hasOwnProperty.call(obj, key)) {
      const value = obj[key]; // Get the value associated with the current key.
      result.push([key, value]); // Add the [key, value] pair to the result array.
    }
  }

  return result; // Return the final array of key-value pairs.
}

