const LOWER = 'abcdefghijklmnopqrstuvwxyz';
const UPPER = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ';
const DIGITS = '0123456789';
const ALPHANUMERIC = LOWER + UPPER + DIGITS;

// Node exposes a CSPRNG; fall back to Math.random in plain browsers
let nodeCrypto = null;
try {
  nodeCrypto = require('crypto');
} catch (err) {
  nodeCrypto = null;
}

function randomIndex(limit) {
  if (nodeCrypto) {
    // Rejection sampling keeps every character equally likely
    const ceiling = Math.floor(256 / limit) * limit;
    let byte;
    do {
      byte = nodeCrypto.randomBytes(1)[0];
    } while (byte >= ceiling);
    return byte % limit;
  }
  return Math.floor(Math.random() * limit);
}

function generateRandomPassword(length) {
  // Reject anything that is not a usable positive character count
  if (!Number.isInteger(length) || length <= 0) {
    throw new RangeError('length must be a positive integer');
  }
  let password = '';
  for (let i = 0; i < length; i += 1) {
    password += ALPHANUMERIC[randomIndex(ALPHANUMERIC.length)];
  }
  return password;
}

function countClasses(password) {
  // Track which of the three character classes actually showed up
  const seen = { lower: 0, upper: 0, digit: 0 };
  for (const ch of password) {
    if (LOWER.includes(ch)) seen.lower += 1;
    else if (UPPER.includes(ch)) seen.upper += 1;
    else seen.digit += 1;
  }
  return seen;
}

function describePassword(password) {
  const seen = countClasses(password);
  const variety = Object.values(seen).filter((n) => n > 0).length;
  // Entropy of a uniform draw over the alphabet, rounded for display
  const bits = password.length * Math.log2(ALPHANUMERIC.length);
  return `${password}  (len ${password.length}, ${variety}/3 classes, ~${bits.toFixed(1)} bits)`;
}

function main() {
  // The lengths the task mentions, plus one longer sample
  const lengths = [8, 4, 16];
  for (const len of lengths) {
    console.log(describePassword(generateRandomPassword(len)));
  }
  try {
    generateRandomPassword(0);
  } catch (err) {
    // Show that invalid input is reported rather than silently accepted
    console.log(`rejected length 0: ${err.message}`);
  }
}

if (require.main === module) {
  main();
}

module.exports = { generateRandomPassword, describePassword };

