// This function calculates the number of full days remaining until a future date.
const daysUntil = (futureDateString) => {
  // Define a constant for milliseconds in a day.
  const MS_PER_DAY = 1000 * 60 * 60 * 24; 

  // Get today's date.
  const today = new Date(); 
  // Set today's time to midnight to ensure accurate day calculation.
  today.setHours(0, 0, 0, 0); 

  // Parse the future date string into a Date object.
  const futureDate = new Date(futureDateString); 
  // Also set the future date's time to midnight.
  futureDate.setHours(0, 0, 0, 0); 

  // Calculate the difference in milliseconds between the two dates.
  const diffInMs = futureDate.getTime() - today.getTime(); 

  // If the future date is in the past, return 0.
  if (diffInMs < 0) {
    return 0; 
  }

  // Calculate the number of full days.
  const days = Math.floor(diffInMs / MS_PER_DAY); 

  // Return the calculated number of days.
  return days; 
};

