// Traffic light state machine: red -> green -> yellow -> red

// Canonical order of the cycle; index arithmetic gives the successor state
const CYCLE = ['red', 'green', 'yellow'];

// How long each state stays lit, in seconds (used by the schedule builder)
const DURATIONS = {
  red: 30,
  green: 25,
  yellow: 5
};

function normalizeState(state) {
  // Accept 'Red', ' GREEN ' and friends, but reject anything that is not text
  if (typeof state !== 'string') {
    throw new TypeError(`Traffic light state must be a string, got ${typeof state}`);
  }
  return state.trim().toLowerCase();
}

function getNextTrafficLightState(currentState) {
  const state = normalizeState(currentState);
  const index = CYCLE.indexOf(state);

  // indexOf returns -1 for colours that are not part of the cycle
  if (index === -1) {
    throw new Error(`Unknown traffic light state: "${currentState}"`);
  }

  // Wrap around so that yellow leads back to red
  return CYCLE[(index + 1) % CYCLE.length];
}

function runCycle(startState) {
  const start = normalizeState(startState);
  const states = [start];

  // Step forward until we return to the starting colour: one full cycle
  let current = getNextTrafficLightState(start);
  while (current !== start) {
    states.push(current);
    current = getNextTrafficLightState(current);
  }
  return states;
}

function buildSchedule(startState) {
  let elapsed = 0;

  // Each entry records when a colour switches on and for how long it holds
  return runCycle(startState).map(state => {
    const entry = { state, startsAt: elapsed, duration: DURATIONS[state] };
    elapsed += DURATIONS[state];
    return entry;
  });
}

function formatSchedule(schedule) {
  const total = schedule.reduce((sum, entry) => sum + entry.duration, 0);
  const lines = schedule.map(entry => {
    // Pad the colour name so the timings line up in the printed table
    const label = entry.state.padEnd(6, ' ');
    return `t=${String(entry.startsAt).padStart(3, ' ')}s  ${label} ${entry.duration}s`;
  });
  lines.push(`full cycle: ${total}s`);
  return lines.join('\n');
}

