// Utilities for inverting objects: values become keys, keys become values.

// Object keys are always strings, so a value must first be turned into a key;
// symbols are valid property keys already and must not be stringified.
function toKey(value) {
  if (typeof value === 'symbol') return value;
  return String(value);
}

// Builds the inverted object from own enumerable pairs, mirroring Object.entries.
function invertObject(obj) {
  if (obj === null || typeof obj !== 'object') {
    throw new TypeError('invertObject expects an object');
  }
  const inverted = {};
  for (const [key, value] of Object.entries(obj)) {
    inverted[toKey(value)] = key;
  }
  return inverted;
}

// Reports values that collide after conversion to keys, so a caller can verify
// the uniqueness assumption instead of silently losing pairs.
function findDuplicateValues(obj) {
  const counts = new Map();
  for (const value of Object.values(obj)) {
    const key = toKey(value);
    counts.set(key, (counts.get(key) || 0) + 1);
  }
  const duplicates = [];
  for (const [key, count] of counts) {
    if (count > 1) duplicates.push(key);
  }
  return duplicates;
}

// Inverts only when the uniqueness precondition actually holds.
function invertStrict(obj) {
  const duplicates = findDuplicateValues(obj);
  if (duplicates.length > 0) {
    throw new Error(`duplicate values: ${duplicates.join(', ')}`);
  }
  return invertObject(obj);
}

// Renders an object for logging, quoting strings so that {1: 'a'} stays
// distinguishable from {1: a}.
function formatObject(obj) {
  const parts = Object.entries(obj).map(([key, value]) => {
    const shown = typeof value === 'string' ? `'${value}'` : String(value);
    return `${key}: ${shown}`;
  });
  return `{${parts.join(', ')}}`;
}

// Shows the inversion on a few objects and on input that breaks uniqueness.
function main() {
  const samples = [{ a: 1, b: 2 }, { name: 'Alice' }, { x: true, y: false }];
  for (const sample of samples) {
    console.log(`${formatObject(sample)} -> ${formatObject(invertObject(sample))}`);
  }

  try {
    invertStrict({ a: 1, b: 1 });
  } catch (err) {
    console.log(`invertStrict rejected input: ${err.message}`);
  }

  const roundTrip = invertObject(invertObject({ first: 'second' }));
  console.log(`round trip: ${formatObject(roundTrip)}`);
}

main();

module.exports = { invertObject, invertStrict, findDuplicateValues, formatObject };

