// Splits a sentence into word tokens, ignoring punctuation and extra spacing.
function tokenize(sentence) {
  // Anything that is not a letter, digit, apostrophe or hyphen separates words.
  const rawParts = sentence.split(/[^A-Za-z0-9'\-]+/);
  const words = [];
  for (const part of rawParts) {
    // The split leaves empty strings at string boundaries; those are not words.
    if (part.length === 0) continue;
    // A token made only of separators-turned-hyphens ("--") carries no letters.
    if (/^[-']+$/.test(part)) continue;
    words.push(part);
  }
  return words;
}

// Returns the first longest word of the sentence, or '' when there is none.
function findLongestWord(sentence) {
  // Guard against non-string input so callers get a predictable string back.
  if (typeof sentence !== 'string') {
    throw new TypeError('findLongestWord expects a string');
  }
  const words = tokenize(sentence);
  let longest = '';
  for (const word of words) {
    // Strict ">" keeps the first word encountered when lengths tie.
    if (word.length > longest.length) {
      longest = word;
    }
  }
  return longest;
}

// Collects every word sharing the maximum length, useful for reporting ties.
function findAllLongestWords(sentence) {
  const longest = findLongestWord(sentence);
  if (longest === '') return [];
  return tokenize(sentence).filter((word) => word.length === longest.length);
}

// Builds a one-line human readable summary for a single sentence.
function describeSentence(sentence) {
  const longest = findLongestWord(sentence);
  // An empty (or punctuation-only) sentence has nothing to describe.
  if (longest === '') {
    return `"${sentence}" -> no words found`;
  }
  const ties = findAllLongestWords(sentence);
  let summary = `"${sentence}" -> "${longest}" (${longest.length} chars)`;
  // Mention the competitors only when the winner was actually contested.
  if (ties.length > 1) {
