// Manual implementation of substring replacement, without relying on String.prototype.replaceAll.

// Returns the index of `needle` in `haystack` at or after `from`, or -1 if absent.
function indexOfFrom(haystack, needle, from) {
  const limit = haystack.length - needle.length;
  for (let i = from; i <= limit; i++) {
    let match = true;
    for (let j = 0; j < needle.length; j++) {
      // Compare character by character; bail out on the first mismatch.
      if (haystack[i + j] !== needle[j]) {
        match = false;
        break;
      }
    }
    if (match) return i;
  }
  return -1;
}

function replaceAll(mainStr, searchStr, replaceStr) {
  // All three arguments must be strings for character-level scanning to make sense.
  if (typeof mainStr !== 'string' || typeof searchStr !== 'string' || typeof replaceStr !== 'string') {
    throw new TypeError('replaceAll expects three string arguments');
  }
  // An empty search string has no well-defined occurrences, so leave the input untouched.
  if (searchStr === '') return mainStr;

  const pieces = [];
  let cursor = 0;
  let hit = indexOfFrom(mainStr, searchStr, cursor);
  while (hit !== -1) {
    pieces.push(mainStr.slice(cursor, hit), replaceStr);
    // Resume past the match so replacements never overlap or re-scan inserted text.
    cursor = hit + searchStr.length;
    hit = indexOfFrom(mainStr, searchStr, cursor);
  }
  pieces.push(mainStr.slice(cursor));
  return pieces.join('');
}

// Counts non-overlapping occurrences, used by the report to explain each result.
function countOccurrences(mainStr, searchStr) {
  if (searchStr === '') return 0;
  let total = 0;
  let cursor = 0;
  let hit = indexOfFrom(mainStr, searchStr, cursor);
  while (hit !== -1) {
    total++;
    cursor = hit + searchStr.length;
    hit = indexOfFrom(mainStr, searchStr, cursor);
  }
  return total;
}

// Formats one replacement as a human-readable line of output.
function describeReplacement(mainStr, searchStr, replaceStr) {
  const result = replaceAll(mainStr, searchStr, replaceStr);
  const n = countOccurrences(mainStr, searchStr);
  // Pluralise the noun so the report reads naturally for a single hit.
  const label = n === 1 ? 'occurrence' : 'occurrences';
  return `"${mainStr}" [${n} ${label} of "${searchStr}" -> "${replaceStr}"] => "${result}"`;
}

function main() {
  const cases = [
    ['hello world world', 'world', 'there'],
    ['banana', 'a', 'o'],
    ['aaa', 'aa', 'b'],
    ['no match here', 'xyz', 'abc'],
    ['abc', '', 'z']
  ];
  for (const [text, search, replacement] of cases) {
    console.log(describeReplacement(text, search, replacement));
  }
}

main();

module.exports = { replaceAll, countOccurrences, describeReplacement };

