// Group words into buckets keyed by their (lower-cased) first letter.

// Only strings that actually begin with a letter can be grouped meaningfully.
function firstLetterKey(word) {
  const first = word.charAt(0).toLowerCase();
  // A single-character comparison is enough; no need for a regular expression here.
  if (first < 'a' || first > 'z') return null;
  return first;
}

function groupByFirstLetter(words) {
  // The caller may hand us anything, so reject non-arrays instead of silently returning {}.
  if (!Array.isArray(words)) {
    throw new TypeError('groupByFirstLetter expects an array of strings');
  }

  const groups = {};

  for (const word of words) {
    // Numbers or nested arrays have no "first letter", so they are contract violations.
    if (typeof word !== 'string') {
      throw new TypeError(`expected a string, received ${typeof word}`);
    }

    const key = firstLetterKey(word);
    // Empty strings and entries like "42" or "-dash" are skipped rather than bucketed.
    if (key === null) continue;

    // Using a plain object means we must create the bucket on first sight of a letter.
    if (!Object.prototype.hasOwnProperty.call(groups, key)) {
      groups[key] = [];
    }
    groups[key].push(word);
  }

  return groups;
}

// Sorting the keys gives a stable, alphabetical view of the grouping.
function sortedKeys(groups) {
  return Object.keys(groups).sort();
}

// Render the grouping as a human-readable report, one letter per line.
function formatGroups(groups) {
  const lines = [];
  for (const key of sortedKeys(groups)) {
    const bucket = groups[key];
    // Case-insensitive ordering keeps "apricot" next to "Apple" in the output.
    const ordered = bucket
      .slice()
      .sort((a, b) => a.toLowerCase().localeCompare(b.toLowerCase()));
    lines.push(`${key.toUpperCase()}: ${ordered.join(', ')}`);
  }
  // An empty grouping would otherwise produce an empty string with no explanation.
  if (lines.length === 0) {
    return '(no groupable words)';
  }
  return lines.join('\n');
}

function main() {
  const words = ['Apple', 'Banana', 'apricot', 'Cat', 'cherry', 'avocado', '7up', ''];
  const groups = groupByFirstLetter(words);

  console.log(formatGroups(groups));

  // Report how many inputs were dropped because they did not start with a letter.
  const grouped = sortedKeys(groups).reduce((sum, k) => sum + groups[k].length, 0);
  console.log(`grouped ${grouped} of ${words.length} entries`);

  try {
    groupByFirstLetter('Apple');
  } catch (err) {
    // A bare string is iterable, so failing loudly is better than grouping its characters.
    console.log(`rejected: ${err.message}`);
  }
}

main();

module.exports = { groupByFirstLetter, formatGroups };

