// Title Case conversion utilities.
// Words are separated by runs of whitespace; punctuation attached to a word
// (like "o'clock" or "well-known") is kept, and only the leading letter is raised.

// Capitalizes a single word: first alphabetic character up, the rest down.
function capitalizeWord(word) {
  // find the first character that can actually carry a case distinction
  const index = word.search(/[a-z]/i);
  if (index === -1) {
    return word.toLowerCase();
  }
  const head = word.slice(0, index);
  const letter = word[index].toUpperCase();
  const tail = word.slice(index + 1).toLowerCase();
  return head + letter + tail;
}

function toTitleCase(str) {
  // reject non-strings early so callers get a clear error instead of "undefined"
  if (typeof str !== 'string') {
    throw new TypeError('toTitleCase expects a string');
  }
  // split on the separators themselves so the original spacing survives the join
  const parts = str.split(/(\s+)/);
  return parts
    .map((part) => (/^\s+$/.test(part) ? part : capitalizeWord(part)))
    .join('');
}

// Counts the words in a string, ignoring empty fragments produced by edge spaces.
function countWords(str) {
  return str.split(/\s+/).filter((word) => word.length > 0).length;
}

// Builds one report line comparing the input with its title-cased form.
function formatReportLine(str) {
  const converted = toTitleCase(str);
  const words = countWords(str);
  // singular vs plural label, so the output reads naturally
  const label = words === 1 ? 'word' : 'words';
  return `${JSON.stringify(str)} -> ${JSON.stringify(converted)} (${words} ${label})`;
}

function main(argv) {
  // command-line arguments win; otherwise fall back to a built-in sample set
  const inputs = argv.length > 0 ? argv : [
    'hello world',
    'this is a test',
    '  leading and trailing  ',
    "o'clock rules apply",
    'MIXED case INPUT here',
    '42 apples and 7 pears',
  ];

  for (const input of inputs) {
    console.log(formatReportLine(input));
  }
}

main(process.argv.slice(2));

// export for reuse when loaded as a CommonJS module
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { toTitleCase, capitalizeWord, countWords, formatReportLine };
}

